# ---------------- DB PostgreSQL / Supabase ----------------



from bunseki.assessment_attempts import (

    AttemptError as ResumableAttemptError,

    get_or_create_attempt as resumable_get_or_create_attempt,

    load_attempt_progress as resumable_load_attempt_progress,

    resume_attempt as resumable_resume_attempt,

    save_attempt_answer as resumable_save_attempt_answer,

    submit_attempt as resumable_submit_attempt,

)



def _pg_connect():

    """Conexión PostgreSQL compatible con Supabase."""

    if not DATABASE_URL:

        st.error("Falta DATABASE_URL. Configúralo en Streamlit Cloud → App → Settings → Secrets.")

        st.stop()

    kwargs = {"cursor_factory": RealDictCursor}

    if "sslmode=" not in DATABASE_URL.lower():

        kwargs["sslmode"] = "require"

    c = psycopg2.connect(DATABASE_URL, **kwargs)

    c.autocommit = True

    return c





def conn():

    """Mantiene el nombre conn() para no cambiar la lógica visual de la app."""

    last_error = None

    for attempt in range(5):

        try:

            return _pg_connect()

        except Exception as e:

            last_error = e

            time.sleep(0.4 * (attempt + 1))

    raise last_error





def fetchone(sql, params=None):

    c = conn()

    try:

        with c.cursor() as cur:

            cur.execute(sql, params or ())

            row = cur.fetchone()

            return dict(row) if row else None

    finally:

        c.close()





def fetchall(sql, params=None):

    c = conn()

    try:

        with c.cursor() as cur:

            cur.execute(sql, params or ())

            rows = cur.fetchall()

            return [dict(r) for r in rows]

    finally:

        c.close()





def execute(sql, params=None, returning=False):

    c = conn()

    try:

        with c.cursor() as cur:

            cur.execute(sql, params or ())

            if returning:

                row = cur.fetchone()

                return dict(row) if row else None

            return None

    finally:

        c.close()





