def _strip_code_fences(raw: str) -> str:

    raw = (raw or "").strip()

    raw = re.sub(r"^```(?:json)?\s*", "", raw, flags=re.I)

    raw = re.sub(r"\s*```$", "", raw)

    return raw.strip()





def _safe_json_loads(raw, default):

    try:

        return json.loads(_strip_code_fences(raw))

    except Exception:

        return default





def read_uploaded_plan_text(uploaded_file) -> str:
    # BUNSEKI_R8_21_8A_ROBUST_PLAN_DOCUMENT_READER
    if uploaded_file is None:
        return ""

    name = str(uploaded_file.name or "").lower()

    data = uploaded_file.read()
    uploaded_file.seek(0)

    if not data:
        return ""

    if name.endswith(".txt") or name.endswith(".md"):
        return data.decode(
            "utf-8",
            errors="ignore",
        ).strip()

    if name.endswith(".docx"):
        if Document is None:
            return ""

        try:
            doc = Document(BytesIO(data))

            extracted = []

            for paragraph in doc.paragraphs:
                text = re.sub(
                    r"\s+",
                    " ",
                    str(paragraph.text or ""),
                ).strip()

                if text:
                    extracted.append(text)

            for table in doc.tables:
                for row in table.rows:
                    row_values = []
                    previous = None

                    for cell in row.cells:
                        value = re.sub(
                            r"\s+",
                            " ",
                            str(cell.text or ""),
                        ).strip()

                        if value and value != previous:
                            row_values.append(value)

                        previous = value

                    if row_values:
                        extracted.append(
                            " | ".join(row_values)
                        )

            return "\n".join(extracted).strip()

        except Exception:
            return ""

    if name.endswith(".pdf"):
        try:
            from pypdf import PdfReader

            reader = PdfReader(BytesIO(data))

            pages = []

            for page in reader.pages:
                text = (
                    page.extract_text()
                    or ""
                ).strip()

                if text:
                    pages.append(text)

            return "\n".join(pages).strip()

        except Exception:
            try:
                from PyPDF2 import PdfReader

                reader = PdfReader(BytesIO(data))

                pages = []

                for page in reader.pages:
                    text = (
                        page.extract_text()
                        or ""
                    ).strip()

                    if text:
                        pages.append(text)

                return "\n".join(pages).strip()

            except Exception:
                return ""

    return data.decode(
        "utf-8",
        errors="ignore",
    ).strip()





# BUNSEKI_R2_SOURCE_TRACEABILITY_V3
def _normalize_source_trace_text(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _locate_plan_source_evidence(raw_text, item):
    lines = str(raw_text or "").splitlines()
    if not lines:
        return "", ""

    normalized_lines = [_normalize_source_trace_text(line) for line in lines]
    candidate = _normalize_source_trace_text((item or {}).get("source_excerpt"))
    normalized_doc = " ".join(line for line in normalized_lines if line)

    def pack(index):
        start = max(0, index - 1)
        end = min(len(lines), index + 2)
        excerpt = _normalize_source_trace_text(" ".join(lines[start:end]))[:500]
        locator = f"Lineas {start + 1}-{end}"
        return excerpt, locator

    if candidate and candidate.casefold() in normalized_doc.casefold():
        candidate_terms = [token for token in re.findall(r"\w+", candidate.casefold()) if len(token) >= 4]
        best_index = None
        best_score = 0
        for index, line in enumerate(normalized_lines):
            folded = line.casefold()
            score = sum(1 for token in candidate_terms[:20] if token in folded)
            if score > best_score:
                best_index = index
                best_score = score
        if best_index is not None and best_score > 0:
            return pack(best_index)

    raw_terms = []
    for key in ("topic", "subtopic", "unit_name", "keywords"):
        value = _normalize_source_trace_text((item or {}).get(key))
        if value:
            raw_terms.extend(re.split(r"[,;:/|]+", value))

    terms = []
    for value in raw_terms:
        for token in re.findall(r"\w+", value.casefold()):
            if len(token) >= 4 and token not in terms:
                terms.append(token)

    best_index = None
    best_score = 0
    topic = _normalize_source_trace_text((item or {}).get("topic")).casefold()

    for index, line in enumerate(normalized_lines):
        folded = line.casefold()
        if not folded:
            continue
        score = sum(1 for term in terms[:20] if term in folded)
        if topic and topic in folded:
            score += 6
        if score > best_score:
            best_index = index
            best_score = score

    if best_index is None or best_score <= 0:
        return "", ""

    return pack(best_index)


def _attach_plan_source_traceability(raw_text, parsed):
    if not isinstance(parsed, dict):
        return parsed

    topics = parsed.get("topics")
    if not isinstance(topics, list):
        return parsed

    for item in topics:
        if not isinstance(item, dict):
            continue
        excerpt, locator = _locate_plan_source_evidence(raw_text, item)
        item["source_excerpt"] = excerpt
        item["source_locator"] = locator

    return parsed


def ensure_plan_source_traceability_schema():
    execute("ALTER TABLE IF EXISTS plan_topics ADD COLUMN IF NOT EXISTS source_excerpt TEXT")
    execute("ALTER TABLE IF EXISTS plan_topics ADD COLUMN IF NOT EXISTS source_locator TEXT")

# BUNSEKI_R8_21_9A_CURRICULUM_FIDELITY_PARSER
def parse_plan_topics_with_ai(raw_text: str, title: str = "") -> dict:

    """Convierte un plan analítico en unidades/temas/resultados. Usa el servicio generativo si hay API; si no, fallback robusto."""

    raw_text = (raw_text or "")[:60000]

    fallback_topics = []

    # fallback por líneas con palabras académicas frecuentes

    for line in raw_text.splitlines():

        clean = re.sub(r"\s+", " ", line).strip(" -•\t")

        if 8 <= len(clean) <= 160 and any(w in clean.lower() for w in ["unidad", "tema", "resultado", "competencia", "contenido", "aprendizaje", "objetivo"]):

            fallback_topics.append({

                "unit_name": clean[:80],

                "topic": clean[:90],

                "subtopic": "",

                "learning_outcome": "Comprender y aplicar el contenido del plan analítico.",

                "bloom_level": "Comprender/Aplicar",

                "keywords": clean

            })

        if len(fallback_topics) >= 80:

            break

    if not fallback_topics:

        fallback_topics = [{

            "unit_name": "Unidad general",

            "topic": title or "Contenido del plan analítico",

            "subtopic": "",

            "learning_outcome": "Comprender, aplicar y evaluar los contenidos del plan.",

            "bloom_level": "Comprender/Aplicar",

            "keywords": title or "plan analítico"

        }]



    client = ai_client()

    if not client:

        return _attach_plan_source_traceability(raw_text, {"summary": "Plan cargado con extracción básica local.", "topics": fallback_topics})



    prompt = f"""

Actúa como diseñador curricular universitario.

Analiza este plan analítico y devuelve SOLO JSON válido con esta estructura:

{{

  "summary": "resumen breve",

  "topics": [

    {{

      "unit_name": "Unidad 1",

      "topic": "tema principal",

      "subtopic": "subtema",

      "learning_outcome": "resultado de aprendizaje evaluable",

      "bloom_level": "Recordar/Comprender/Aplicar/Analizar/Evaluar/Crear",

      "keywords": "palabras clave separadas por coma",
      "source_excerpt": "fragmento textual breve copiado literalmente del PLAN que sustenta este tema"

    }}

  ]

}}

FIDELIDAD CURRICULAR OBLIGATORIA:
1. Recorre las unidades y contenidos en el mismo orden del PLAN.
2. Cada contenido académico explícitamente enumerado o listado debe aparecer representado en topics.
3. No fusiones contenidos académicos diferentes únicamente para reducir el número de filas.
4. Conserva los nombres específicos presentes en el PLAN.
5. Si aparecen Teorema de Pitágoras, Ley del paralelogramo, Determinantes, Matriz inversa u otros contenidos explícitos, deben permanecer identificables en la salida.
6. No sustituyas contenidos específicos por categorías genéricas si eso provoca la pérdida del nombre original.
7. Usa unit_name para la unidad oficial del documento.
8. Usa topic para el núcleo o título temático de la unidad.
9. Usa subtopic para cada contenido académico atómico. Conserva de manera fiel el nombre utilizado en el PLAN.
10. Un contenido numerado distinto debe generar una fila distinta cuando represente un contenido académico.
11. Si un contenido contiene tipos, métodos o conceptos independientes, conserva todos sus nombres.
12. Las instrucciones administrativas, políticas del curso y sistema de puntuación no deben convertirse en contenidos académicos.
13. No inventes contenidos que no estén sustentados por el PLAN.
14. learning_outcome debe corresponder al contenido académico concreto.
15. bloom_level debe usar únicamente Recordar, Comprender, Aplicar, Analizar, Evaluar o Crear.
16. Antes de responder realiza una auditoría interna de cobertura para comprobar que ningún contenido curricular explícito haya desaparecido.
17. Puedes devolver hasta 80 topics. Nunca fusiones contenidos únicamente para cumplir un límite.
Devuelve SOLO JSON válido. No uses markdown.



Título: {title}

PLAN:

{raw_text}

"""

    try:

        resp = client.models.generate_content(model="gemini-2.5-flash-lite", contents=prompt)

        parsed = _safe_json_loads(resp.text, {})

        if isinstance(parsed, dict) and isinstance(parsed.get("topics"), list) and parsed["topics"]:

            return _attach_plan_source_traceability(raw_text, parsed)

    except Exception:

        pass

    return _attach_plan_source_traceability(raw_text, {"summary": "Plan cargado con extracción básica local.", "topics": fallback_topics})





def save_analytic_plan(title, course, teacher_id, filename, raw_text, parsed, academic_context=None):
    ensure_plan_source_traceability_schema()

    academic_context = academic_context or {}

    row = execute("""

        INSERT INTO analytic_plans(title, course, subject, course_level, parallel, shift, teacher_id, filename, raw_text, summary, created_at)

        VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id

    """, (

        title, course,

        academic_context.get("subject"), academic_context.get("course_level"),

        academic_context.get("parallel"), academic_context.get("shift"),

        teacher_id, filename, raw_text, parsed.get("summary",""), now()

    ), returning=True)

    plan_id = row["id"]

    for item in parsed.get("topics", []):

        execute("""

            INSERT INTO plan_topics(plan_id, unit_name, topic, subtopic, learning_outcome, bloom_level, keywords, source_excerpt, source_locator)

            VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s)

        """, (

            plan_id,

            item.get("unit_name",""),

            item.get("topic",""),

            item.get("subtopic",""),

            item.get("learning_outcome",""),

            item.get("bloom_level",""),

            item.get("keywords",""),
            item.get("source_excerpt",""),
            item.get("source_locator",""),

        ))

    return plan_id





