# BUNSEKI_R7_MOODLE_PREVIEW_V1
def render_moodle_gold_preview(gold_items):
    st.markdown("#### Vista previa Moodle")
    st.caption(
        "Simulación docente de cómo se verá cada pregunta Gold antes de exportarla. "
        "La importación final puede variar ligeramente según el tema de Moodle."
    )

    for position, item in enumerate(gold_items, 1):
        try:
            options = json.loads(item.get("options_json") or "[]")
        except Exception:
            options = []

        if not isinstance(options, list):
            options = []

        options = [str(option) for option in options]
        correct_answer = re.sub(
            r"\s+",
            " ",
            str(item.get("correct_answer") or ""),
        ).strip().casefold()

        with st.expander(
            f"Pregunta {position} · {item.get('topic') or 'Sin tema'}",
            expanded=(position == 1),
        ):
            st.markdown(f"**{position}. {item.get('question') or ''}**")

            if options:
                for option_index, option in enumerate(options):
                    label = chr(65 + option_index)
                    st.write(f"○ {label}. {option}")
            else:
                st.warning("Esta pregunta no contiene opciones válidas.")

            st.caption(
                "Etiquetas Moodle: "
                f"Gold · Bloom:{item.get('bloom_level') or '-'} · "
                f"Dificultad:{item.get('difficulty_level') or '-'}"
            )

            correct_option = next(
                (
                    option
                    for option in options
                    if re.sub(r"\s+", " ", option).strip().casefold()
                    == correct_answer
                ),
                None,
            )

            st.markdown("**Clave docente**")
            if correct_option:
                st.success(f"Respuesta correcta: {correct_option}")
            else:
                st.warning(
                    "No se pudo identificar una respuesta correcta única "
                    "para la vista previa."
                )

            explanation = str(item.get("explanation") or "").strip()
            if explanation:
                st.info(f"Retroalimentación: {explanation}")
            else:
                st.caption("Sin retroalimentación general registrada.")

            st.caption(
                f"Banco: Gold · ID #{item.get('id')} · "
                f"Resultado de aprendizaje: {item.get('learning_outcome') or '-'}"
            )


def get_gold_question_bank_items_for_moodle(plan_id):
    ensure_question_bank_gold_schema()
    return fetchall(
        "SELECT q.*, pt.source_excerpt, pt.source_locator, "
        "ap.title AS plan_title "
        "FROM question_bank_items q "
        "JOIN plan_topics pt ON pt.id=q.plan_topic_id "
        "JOIN analytic_plans ap ON ap.id=q.plan_id "
        "WHERE q.plan_id=%s "
        "AND q.status='approved' "
        "AND q.governance_level='gold' "
        "ORDER BY q.id",
        (plan_id,),
    )


def build_moodle_xml_from_gold_items(plan_id):
    import xml.etree.ElementTree as ET

    rows = get_gold_question_bank_items_for_moodle(plan_id)
    if not rows:
        raise ValueError("No existen preguntas Gold para exportar.")

    plan_title = str(rows[0].get("plan_title") or f"Plan {plan_id}").strip()
    quiz = ET.Element("quiz")

    category_question = ET.SubElement(
        quiz,
        "question",
        {"type": "category"},
    )
    category = ET.SubElement(category_question, "category")
    ET.SubElement(category, "text").text = (
        f"$course$/top/BunsekiChat/{plan_title}"
    )

    exported_count = 0

    for item in rows:
        if item.get("status") != "approved":
            continue
        if item.get("governance_level") != "gold":
            continue

        try:
            options = json.loads(item.get("options_json") or "[]")
        except Exception as exc:
            raise ValueError(
                f"La pregunta #{item.get('id')} tiene opciones JSON inválidas."
            ) from exc

        if not isinstance(options, list) or len(options) < 2:
            raise ValueError(
                f"La pregunta #{item.get('id')} no tiene suficientes opciones."
            )

        options = [str(option) for option in options]

        def normalize_answer(value):
            return re.sub(r"\s+", " ", str(value or "")).strip().casefold()

        correct_answer = normalize_answer(item.get("correct_answer"))
        matches = [
            option
            for option in options
            if normalize_answer(option) == correct_answer
        ]

        if len(matches) != 1:
            raise ValueError(
                f"La respuesta correcta de la pregunta #{item.get('id')} "
                "no coincide de forma única con sus opciones."
            )

        correct_option = matches[0]

        question = ET.SubElement(
            quiz,
            "question",
            {"type": "multichoice"},
        )

        name = ET.SubElement(question, "name")
        ET.SubElement(name, "text").text = (
            f"Bunseki Gold #{item.get('id')} - "
            f"{item.get('topic') or 'Pregunta'}"
        )

        questiontext = ET.SubElement(
            question,
            "questiontext",
            {"format": "html"},
        )
        ET.SubElement(questiontext, "text").text = str(
            item.get("question") or ""
        )

        generalfeedback = ET.SubElement(
            question,
            "generalfeedback",
            {"format": "html"},
        )
        ET.SubElement(generalfeedback, "text").text = str(
            item.get("explanation") or ""
        )

        ET.SubElement(question, "defaultgrade").text = "1.0000000"
        ET.SubElement(question, "penalty").text = "0.3333333"
        ET.SubElement(question, "hidden").text = "0"
        ET.SubElement(question, "single").text = "true"
        ET.SubElement(question, "shuffleanswers").text = "true"
        ET.SubElement(question, "answernumbering").text = "abc"

        correctfeedback = ET.SubElement(
            question,
            "correctfeedback",
            {"format": "html"},
        )
        ET.SubElement(correctfeedback, "text").text = "Respuesta correcta."

        partiallycorrectfeedback = ET.SubElement(
            question,
            "partiallycorrectfeedback",
            {"format": "html"},
        )
        ET.SubElement(partiallycorrectfeedback, "text").text = (
            "Revisa la retroalimentación general."
        )

        incorrectfeedback = ET.SubElement(
            question,
            "incorrectfeedback",
            {"format": "html"},
        )
        ET.SubElement(incorrectfeedback, "text").text = (
            "Revisa el razonamiento y vuelve a intentarlo."
        )

        tags = ET.SubElement(question, "tags")
        tag_values = [
            "BunsekiChat",
            "Gold",
            f"Bloom:{item.get('bloom_level') or ''}",
            f"Dificultad:{item.get('difficulty_level') or ''}",
            f"Tema:{item.get('topic') or ''}",
        ]
        for tag_value in tag_values:
            if not tag_value.endswith(":") and tag_value.strip():
                tag = ET.SubElement(tags, "tag")
                ET.SubElement(tag, "text").text = tag_value.strip()

        for option in options:
            fraction = "100" if option == correct_option else "0"
            answer = ET.SubElement(
                question,
                "answer",
                {"fraction": fraction, "format": "html"},
            )
            ET.SubElement(answer, "text").text = option
            feedback = ET.SubElement(
                answer,
                "feedback",
                {"format": "html"},
            )
            ET.SubElement(feedback, "text").text = (
                "Respuesta correcta."
                if fraction == "100"
                else "Opción incorrecta."
            )

        exported_count += 1

    if exported_count == 0:
        raise ValueError("No se encontró ninguna pregunta Gold exportable.")

    xml_bytes = ET.tostring(
        quiz,
        encoding="utf-8",
        xml_declaration=True,
    )
    ET.fromstring(xml_bytes)

    safe_title = re.sub(
        r"[^A-Za-z0-9._-]+",
        "_",
        plan_title,
    ).strip("._") or f"plan_{plan_id}"

    filename = f"{safe_title}_Bunseki_Gold_Moodle.xml"
    return xml_bytes, filename, exported_count


def approve_question_bank_item(item_id, approved_by):
    ensure_question_bank_gold_schema()

    if not actor_can_manage_question_bank_item(item_id, approved_by):

        raise ValueError("No tienes autorización para aprobar esta pregunta.")

    return execute("""

        UPDATE question_bank_items

        SET status='approved', governance_level='validated', approved_by=%s, approved_at=%s, updated_at=%s

        WHERE id=%s AND status='draft'

        RETURNING *

    """, (approved_by, now(), now(), item_id), returning=True)





def reject_question_bank_item(item_id, actor_id):

    if not actor_can_manage_question_bank_item(item_id, actor_id):

        raise ValueError("No tienes autorización para rechazar esta pregunta.")

    return execute("""

        UPDATE question_bank_items SET status='rejected', updated_at=%s

        WHERE id=%s AND status='draft' RETURNING *

    """, (now(), item_id), returning=True)





def delete_question_bank_item(item_id, actor_id):

    """Soft delete only: teacher actions must never physically delete bank items."""

    if not actor_can_manage_question_bank_item(item_id, actor_id):

        raise ValueError("No tienes autorización para eliminar esta pregunta.")

    return execute("""

        UPDATE question_bank_items SET status='deleted', updated_at=%s

        WHERE id=%s AND status IN ('draft', 'rejected') RETURNING *

    """, (now(), item_id), returning=True)





def generate_topic_question_drafts(teacher_id, plan_topic_id, difficulty="Intermedio", n_questions=10):

    """Generate and persist AI drafts for one selected curricular topic, never for a student quiz."""

    if difficulty not in QUESTION_BANK_DIFFICULTIES:

        raise ValueError("Dificultad inválida.")

    n_questions = int(n_questions)

    if not 1 <= n_questions <= 20:

        raise ValueError("El número de preguntas debe estar entre 1 y 20.")

    topic_context = get_plan_topic_for_actor(plan_topic_id, teacher_id)

    if not topic_context:

        raise ValueError("No se encontró el tema curricular seleccionado.")

    client = ai_client()

    if not client:

        raise RuntimeError("No hay un modelo Gemini configurado para generar borradores.")

    model = "gemini-2.5-flash"

    prompt = f"""

Eres diseñador de evaluación universitaria. Genera EXACTAMENTE {n_questions} preguntas de opción múltiple.

Devuelve SOLO un arreglo JSON válido, sin markdown. Cada objeto debe tener: question, options,

correct_answer, explanation, bloom_level, difficulty_level. options debe contener exactamente 4 textos

distintos y correct_answer debe coincidir exactamente con una opción.



ALINEACIÓN OBLIGATORIA: no cambies ni inventes otro tema. Cada pregunta debe comprobar el resultado de

aprendizaje dentro del tema curricular indicado y respetar Bloom y dificultad solicitados.

Unidad: {topic_context.get('unit_name') or ''}

Tema obligatorio: {topic_context.get('topic') or ''}

Subtema: {topic_context.get('subtopic') or ''}

Resultado de aprendizaje: {topic_context.get('learning_outcome') or ''}

Bloom permitido: {topic_context.get('bloom_level') or ''} (usa uno de: {', '.join(QUESTION_BANK_BLOOM_LEVELS)})

Palabras clave: {topic_context.get('keywords') or ''}

Dificultad obligatoria: {difficulty}

"""

    try:

        response = client.models.generate_content(model=model, contents=prompt)

        generated = _safe_json_loads(response.text, [])

    except Exception as exc:

        raise RuntimeError("No se pudieron generar los borradores curriculares.") from exc

    if not isinstance(generated, list) or len(generated) != n_questions:

        raise ValueError("Gemini debe devolver exactamente el número de preguntas solicitado.")

    normalized = []

    for draft in generated:

        draft = dict(draft) if isinstance(draft, dict) else {}

        # Topic provenance is deliberately copied from plan_topic, never accepted from Gemini.

        draft["difficulty_level"] = difficulty

        if not draft.get("bloom_level"):

            draft["bloom_level"] = topic_context.get("bloom_level") or "Aplicar"

        normalized.append(validate_question_bank_payload(draft))

    return create_question_bank_drafts(teacher_id, plan_topic_id, normalized, model)





ASSESSMENT_AUDIENCE_MODES = ("academic_context", "targeted")





def _assessment_audience_mode(assessment):

    mode = str((assessment or {}).get("audience_mode") or "academic_context").strip().lower()

    return mode if mode in ASSESSMENT_AUDIENCE_MODES else "invalid"





