def normalize_adaptive_difficulty(value):

    raw = normalize_spaces(value) or "Intermedio"

    aliases = {

        "inicial": "Inicial",

        "basico": "Básico",

        "básico": "Básico",

        "intermedio": "Intermedio",

        "avanzado": "Avanzado",

    }

    normalized = aliases.get(strip_accents(raw).lower())

    if normalized not in ADAPTIVE_DIFFICULTIES:

        raise ValueError(f"Dificultad adaptativa inválida: {raw}")

    return normalized





def adaptive_bloom_levels_for_difficulty(difficulty):

    difficulty = normalize_adaptive_difficulty(difficulty)

    return {

        "Inicial": {"Recordar", "Comprender"},

        "Básico": {"Recordar", "Comprender"},

        "Intermedio": {"Comprender", "Aplicar"},

        "Avanzado": {"Aplicar", "Analizar", "Evaluar", "Crear"},

    }[difficulty]





def adaptive_difficulty_instruction(difficulty):

    difficulty = normalize_adaptive_difficulty(difficulty)

    return {

        "Inicial": "conceptos fundamentales, reconocimiento e interpretación directa; evita problemas multietapa",

        "Básico": "comprensión conceptual y aplicación directa en uno o dos pasos, con datos explícitos",

        "Intermedio": "aplicación contextualizada y resolución de problemas de varios pasos con interpretación",

        "Avanzado": "análisis de situaciones no rutinarias, modelación, decisiones justificadas e interpretación crítica",

    }[difficulty]





def fallback_questions(n_questions, base_topics=None, assessment_context=None):

    assessment_context = assessment_context or {}

    pool = local_research_question_pool(assessment_context.get("subject", ""))

    if pool:

        quiz_type = str(assessment_context.get("quiz_type") or "adaptive").lower()

        if not is_research_quiz(quiz_type):

            requested_difficulty = normalize_adaptive_difficulty(

                assessment_context.get("difficulty") or "Intermedio"

            )

            allowed_bloom = adaptive_bloom_levels_for_difficulty(requested_difficulty)

            preferred = [

                dict(item)

                for item in pool

                if str(item.get("bloom_level") or "").strip() in allowed_bloom

            ]

            if preferred:

                remaining = [

                    dict(item)

                    for item in pool

                    if item not in preferred

                ]

                return preferred + remaining

        return pool

    base_topics = [x for x in (base_topics or []) if x] or [assessment_context.get("subject") or "Matemáticas"]

    fallback = []

    for i in range(int(n_questions)):

        t = base_topics[i % len(base_topics)] if base_topics else "Matemáticas"

        fallback.append({

            "question": f"Pregunta {i+1}: Resuelve o explica un concepto clave relacionado con {t}.",

            "options": [

                f"Aplicar correctamente el procedimiento de {t}",

                "Elegir una respuesta sin justificar",

                "Ignorar las condiciones del problema",

                "Usar una fórmula no relacionada",

            ],

            "correct_answer": f"Aplicar correctamente el procedimiento de {t}",

            "explanation": f"La respuesta correcta debe usar el procedimiento o concepto central de {t}.",

            "bloom_level": "Aplicar",

            "topic": t,

        })

    return fallback









def local_fast_adaptive_pool(subject):

    """Banco local validado para evaluaciones/prácticas rápidas sin esperar al generador externo."""

    key = strip_accents(subject or "").lower()

    if "calculo" not in key:

        return []

    combined = []

    seen = set()

    for source in (DERIVATIVE_APPLICATIONS_QUESTION_BANK, DIFFERENTIAL_CALCULUS_QUESTION_BANK):

        for raw in source:

            item = normalize_question_payload(raw)

            if not item:

                continue

            code = item.get("item_code") or stable_item_code(item.get("question", ""))

            if code in seen:

                continue

            seen.add(code)

            combined.append(item)

    return combined





def adaptive_questions_for_difficulty(questions, difficulty):

    difficulty = normalize_adaptive_difficulty(difficulty)

    allowed = adaptive_bloom_levels_for_difficulty(difficulty)

    aligned = []

    for raw in questions or []:

        item = normalize_question_payload(raw)

        if not item:

            continue

        bloom = str(item.get("bloom_level") or "").strip()

        if bloom in allowed:

            item["difficulty_level"] = difficulty

            aligned.append(item)

    return aligned






