def _adaptive_practice_autosave_answer(
    user_id,
    attempt_id,
    item,
    position,
    widget_key,
    serve_batch_key,
):
    if not attempt_id:
        return

    value = st.session_state.get(
        widget_key
    )

    if value is None:
        return

    uid = int(user_id)

    question_key = (
        _adaptive_practice_answer_question_key(
            item,
            serve_batch_key,
        )
    )

    bank_question_id = item.get(
        "bank_question_id"
    )

    payload = {
        "value":
            value,

        "bank_question_id":
            (
                int(bank_question_id)
                if bank_question_id
                not in (None, "")
                else None
            ),

        "item_code":
            str(
                item.get("item_code")
                or ""
            ),

        "position":
            int(position),

        "serve_batch_key":
            str(
                serve_batch_key
                or ""
            ),
    }

    error_key = (
        f"adaptive_practice_"
        f"autosave_error_{uid}"
    )

    connection = conn()

    try:
        resumable_save_attempt_answer(
            connection,
            attempt_id=int(attempt_id),
            user_id=uid,
            question_key=question_key,
            question_id=None,
            answer_payload=payload,
            elapsed_seconds=0,
            current_position=int(position),
        )

        connection.commit()

        st.session_state[
            error_key
        ] = None

    except Exception as exc:
        connection.rollback()

        st.session_state[
            error_key
        ] = str(exc)

    finally:
        connection.close()


def adaptive_practice_next_difficulty(current_difficulty, correct, total):

    current = normalize_adaptive_difficulty(current_difficulty)

    ratio = float(correct or 0) / max(1, int(total or 0))

    idx = ADAPTIVE_DIFFICULTIES.index(current)

    if ratio >= 0.80 and idx < len(ADAPTIVE_DIFFICULTIES) - 1:

        return ADAPTIVE_DIFFICULTIES[idx + 1], "Dominaste este bloque; la siguiente práctica aumenta la exigencia cognitiva."

    if ratio < 0.50 and idx > 0:

        return ADAPTIVE_DIFFICULTIES[idx - 1], "Conviene consolidar fundamentos antes de volver a subir la dificultad."

    return current, "Mantendremos la dificultad para consolidar el desempeño antes de cambiar de nivel."






# BUNSEKI_R8_20_V3_DYNAMIC_AI_PRACTICE_BANK
AI_PRACTICE_PROMPT_VERSION = "r8.20-v4"
AI_PRACTICE_MODEL = "gemini-2.5-flash"
# BUNSEKI_R8_20_V4_AI_RESILIENCE
# BUNSEKI_R8_20_V5_1_SUBTOPIC_PROMPT_FOCUS
AI_PRACTICE_MAX_ATTEMPTS = 4


def _ai_practice_generate_content_resilient(
    client,
    prompt,
    purpose="generación",
):
    """Retry transient provider failures and surface a friendly error."""
    import time

    transient_tokens = (
        "503",
        "unavailable",
        "high demand",
        "temporarily",
        "timeout",
        "timed out",
        "429",
        "resource_exhausted",
        "rate limit",
        "rate_limit",
    )

    last_kind = "ProviderError"

    for attempt in range(1, AI_PRACTICE_MAX_ATTEMPTS + 1):
        try:
            return client.models.generate_content(
                model=AI_PRACTICE_MODEL,
                contents=prompt,
            )
        except Exception as exc:
            last_kind = type(exc).__name__
            message = str(exc).lower()
            transient = any(
                token in message
                for token in transient_tokens
            )

            if not transient:
                raise RuntimeError(
                    "No fue posible completar la "
                    f"{purpose} con IA. "
                    "Revise la configuración del proveedor "
                    f"({last_kind})."
                ) from exc

            if attempt < AI_PRACTICE_MAX_ATTEMPTS:
                delay_seconds = min(2 ** attempt, 8)
                time.sleep(delay_seconds)

    raise RuntimeError(
        "El servicio de IA está temporalmente saturado. "
        "BunsekiChat realizó varios reintentos sin éxito. "
        "Espere unos segundos y vuelva a intentar."
    )


