def _strict_ai_practice_item(raw, topic, subtopic, difficulty):
    if not isinstance(raw, dict):
        return None

    question = normalize_spaces(raw.get("question", ""))
    options = [
        normalize_spaces(value)
        for value in (raw.get("options") or [])
        if normalize_spaces(value)
    ]
    options = list(dict.fromkeys(options))
    correct_answer = normalize_spaces(raw.get("correct_answer", ""))

    if not question or len(options) != 4 or correct_answer not in options:
        return None

    bloom = normalize_spaces(raw.get("bloom_level", "")) or "Aplicar"
    allowed = adaptive_bloom_levels_for_difficulty(difficulty)

    # BUNSEKI_R8_20_V6_BLOOM_SET_HOTFIX
    bloom_order = (
        "Recordar",
        "Comprender",
        "Aplicar",
        "Analizar",
        "Evaluar",
        "Crear",
    )
    allowed_values = [
        level
        for level in bloom_order
        if level in (allowed or set())
    ]

    if bloom not in allowed_values:
        bloom = allowed_values[0] if allowed_values else "Aplicar"

    return {
        "question": question,
        "options": options,
        "correct_answer": correct_answer,
        "explanation": normalize_spaces(raw.get("explanation", "")),
        "bloom_level": bloom,
        "difficulty_level": difficulty,
        "topic": topic,
        "subtopic": subtopic,
        "item_code": stable_item_code(
            f"{topic}|{subtopic}|{difficulty}|{question}"
        ),
    }


def _verify_ai_practice_items(client, items, topic, subtopic):
    verification_input = [
        {
            "index": index,
            "question": item["question"],
            "options": item["options"],
        }
        for index, item in enumerate(items)
    ]

    prompt = f"""
Actúa como verificador matemático independiente.

Tema o materia obligatorio: {topic}
Subtema obligatorio: {subtopic}

Para cada pregunta:
1. Resuélvela de forma independiente.
2. Elige EXACTAMENTE una opción proporcionada.
3. Comprueba que pertenece exclusivamente al subtema indicado.
4. valid=true solo si el enunciado es claro y tiene una respuesta inequívoca.
5. Devuelve SOLO JSON válido.

Formato:
[
  {{
    "index": 0,
    "valid": true,
    "correct_answer": "texto exacto de una opción",
    "reason": "justificación breve"
  }}
]

Preguntas:
{json.dumps(verification_input, ensure_ascii=False)}
"""

    response = _ai_practice_generate_content_resilient(
        client,
        prompt,
        purpose="verificación matemática",
    )
    parsed = _safe_json_loads(response.text, [])
    if not isinstance(parsed, list):
        return {}

    result = {}
    for row in parsed:
        if not isinstance(row, dict):
            continue
        try:
            index = int(row.get("index"))
        except Exception:
            continue
        result[index] = {
            "valid": bool(row.get("valid")),
            "correct_answer": normalize_spaces(
                row.get("correct_answer", "")
            ),
            "reason": normalize_spaces(row.get("reason", "")),
        }
    return result


# BUNSEKI_R8_21_BANK_SUPPLY_UNIQUE_ASSIGNMENT
AI_PRACTICE_SUPPLY_TARGET_DEFAULT = 40
AI_PRACTICE_NEAR_DUPLICATE_THRESHOLD = 0.86


def _ai_practice_normalize_question_text(value):
    import re
    import unicodedata
    text = normalize_spaces(value or "").lower()
    text = unicodedata.normalize("NFKD", text)
    text = "".join(c for c in text if not unicodedata.combining(c))
    text = re.sub(r"[^\\w\\s]", " ", text)
    return normalize_spaces(text)


def _ai_practice_question_tokens(value):
    return {
        token
        for token in _ai_practice_normalize_question_text(value).split()
        if len(token) > 2
    }


def _ai_practice_question_similarity(left, right):
    a = _ai_practice_question_tokens(left)
    b = _ai_practice_question_tokens(right)
    union = a | b
    return (len(a & b) / len(union)) if union else 0.0


