def ai_practice_verified_count(topic, subtopic, difficulty):
    ensure_ai_practice_supply_schema()
    row = fetchone(
        """
        SELECT COUNT(*) AS n
        FROM ai_practice_question_bank
        WHERE topic=%s
          AND subtopic=%s
          AND difficulty_level=%s
          AND verification_status='verified'
          AND active=TRUE
        """,
        (topic, subtopic, normalize_adaptive_difficulty(difficulty)),
    )
    return int((row or {}).get("n") or 0)


def get_ai_practice_bank_supply_coverage():
    ensure_ai_practice_supply_schema()
    return fetchall(
        """
        SELECT
            topic,
            subtopic,
            difficulty_level,
            COUNT(*) FILTER (
                WHERE verification_status='verified' AND active=TRUE
            ) AS verified,
            COUNT(*) FILTER (
                WHERE verification_status='needs_review' AND active=TRUE
            ) AS needs_review,
            COALESCE(SUM(usage_count),0) AS uses
        FROM ai_practice_question_bank
        GROUP BY topic, subtopic, difficulty_level
        ORDER BY topic, subtopic, difficulty_level
        """
    )


def ensure_ai_practice_bank_target(
    topic,
    subtopic,
    difficulty,
    target_verified=AI_PRACTICE_SUPPLY_TARGET_DEFAULT,
    max_batches=12,
):
    difficulty = normalize_adaptive_difficulty(difficulty)
    initial = ai_practice_verified_count(topic, subtopic, difficulty)
    current = initial
    batches = 0
    stagnant = 0
    error = ""
    while current < int(target_verified) and batches < int(max_batches):
        before = current
        try:
            generate_ai_practice_bank_batch(
                0,
                topic,
                subtopic,
                difficulty,
                batch_size=max(10, min(20, int(target_verified) - current + 4)),
            )
        except Exception as exc:
            error = str(exc)
            break
        batches += 1
        current = ai_practice_verified_count(topic, subtopic, difficulty)
        stagnant = stagnant + 1 if current <= before else 0
        if stagnant >= 2:
            break
    return {
        "initial_verified": initial,
        "verified": current,
        "target": int(target_verified),
        "batches": batches,
        "reached": current >= int(target_verified),
        "error": error,
    }


def _ai_practice_rows_to_items(rows, topic, subtopic, difficulty):
    output = []
    for row in rows:
        item = _strict_ai_practice_item(
            {
                "question": row.get("question"),
                "options": _safe_json_loads(row.get("options_json"), []),
                "correct_answer": row.get("correct_answer"),
                "explanation": row.get("explanation"),
                "bloom_level": row.get("bloom_level"),
            },
            topic,
            subtopic,
            difficulty,
        )
        if not item:
            continue
        item["bank_question_id"] = row.get("id")
        item["item_code"] = row.get("item_code") or item["item_code"]
        item["verification_status"] = row.get("verification_status")
        item["generation_source"] = "gemini_verified_bank"
        output.append(item)
    return output


# BUNSEKI_R8_21_1B_REALDICT_COUNT_HOTFIX
def _ai_practice_count_value(row):
    """Read COUNT(*) safely from tuple, RealDictRow, or mapping cursors."""
    if row is None:
        return 0

    if hasattr(row, "get"):
        for key in ("n", "count"):
            value = row.get(key)
            if value is not None:
                return int(value or 0)

        values = list(row.values())
        return int(values[0] or 0) if values else 0

    return int(row[0] or 0)


def reserve_ai_practice_bank_questions(
    uid,
    topic,
    subtopic,
    difficulty,
    n_questions=5,
    round_no=1,
):
    """No-repeat-first allocation; stable within a practice round."""
    ensure_ai_practice_supply_schema()
    difficulty = normalize_adaptive_difficulty(difficulty)
    n_questions = max(1, int(n_questions))
    round_no = max(1, int(round_no))
    batch_key = hashlib.sha256(
        f"r8.21|{int(uid)}|{topic}|{subtopic}|{difficulty}|{round_no}".encode("utf-8")
    ).hexdigest()

    connection = conn()
    try:
        with connection.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) FROM ai_practice_question_serves WHERE serve_batch_key=%s",
                (batch_key,),
            )
            current = int(_ai_practice_count_value(cur.fetchone()) or 0)
            missing = max(0, n_questions - current)

            if missing:
                cur.execute(
                    """
                    WITH candidate AS (
                        SELECT q.id
                        FROM ai_practice_question_bank q
                        WHERE q.topic=%s
                          AND q.subtopic=%s
                          AND q.difficulty_level=%s
                          AND q.verification_status='verified'
                          AND q.active=TRUE
                          AND NOT EXISTS (
                              SELECT 1
                              FROM ai_practice_question_serves mine
                              WHERE mine.user_id=%s
                                AND mine.bank_question_id=q.id
                          )
                          AND NOT EXISTS (
                              SELECT 1
                              FROM ai_practice_question_serves recent
                              WHERE recent.bank_question_id=q.id
                                AND recent.user_id<>%s
                                AND recent.served_at >= CURRENT_TIMESTAMP - INTERVAL '30 minutes'
                          )
                        ORDER BY
                            (
                                SELECT COUNT(*)
                                FROM ai_practice_question_serves recent24
                                WHERE recent24.bank_question_id=q.id
                                  AND recent24.served_at >= CURRENT_TIMESTAMP - INTERVAL '24 hours'
                            ) ASC,
                            q.usage_count ASC,
                            RANDOM()
                        FOR UPDATE SKIP LOCKED
                        LIMIT %s
                    )
                    INSERT INTO ai_practice_question_serves(
                        bank_question_id,user_id,serve_batch_key,
                        topic,subtopic,difficulty_level
                    )
                    SELECT id,%s,%s,%s,%s,%s FROM candidate
                    ON CONFLICT DO NOTHING
                    """,
                    (
                        topic, subtopic, difficulty,
                        int(uid), int(uid), int(missing),
                        int(uid), batch_key, topic, subtopic, difficulty,
                    ),
                )

            cur.execute(
                "SELECT COUNT(*) FROM ai_practice_question_serves WHERE serve_batch_key=%s",
                (batch_key,),
            )
            current = int(_ai_practice_count_value(cur.fetchone()) or 0)
            missing = max(0, n_questions - current)

            if missing:
                cur.execute(
                    """
                    WITH candidate AS (
                        SELECT q.id
                        FROM ai_practice_question_bank q
                        WHERE q.topic=%s
                          AND q.subtopic=%s
                          AND q.difficulty_level=%s
                          AND q.verification_status='verified'
                          AND q.active=TRUE
                          AND NOT EXISTS (
                              SELECT 1
                              FROM ai_practice_question_serves same_batch
                              WHERE same_batch.serve_batch_key=%s
                                AND same_batch.bank_question_id=q.id
                          )
                        ORDER BY
                            (
                                SELECT MAX(previous.served_at)
                                FROM ai_practice_question_serves previous
                                WHERE previous.bank_question_id=q.id
                                  AND previous.user_id=%s
                            ) ASC NULLS FIRST,
                            q.usage_count ASC,
                            RANDOM()
                        FOR UPDATE SKIP LOCKED
                        LIMIT %s
                    )
                    INSERT INTO ai_practice_question_serves(
                        bank_question_id,user_id,serve_batch_key,
                        topic,subtopic,difficulty_level
                    )
                    SELECT id,%s,%s,%s,%s,%s FROM candidate
                    ON CONFLICT DO NOTHING
                    """,
                    (
                        topic, subtopic, difficulty, batch_key,
                        int(uid), int(missing),
                        int(uid), batch_key, topic, subtopic, difficulty,
                    ),
                )
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()

    rows = fetchall(
        """
        SELECT q.*
        FROM ai_practice_question_serves s
        JOIN ai_practice_question_bank q ON q.id=s.bank_question_id
        WHERE s.serve_batch_key=%s
        ORDER BY s.id
        LIMIT %s
        """,
        (batch_key, n_questions),
    )
    return _ai_practice_rows_to_items(rows, topic, subtopic, difficulty)


