def _store_ai_practice_items(items, verifications):
    ensure_ai_practice_supply_schema()
    verified = 0

    for index, item in enumerate(items):
        verification = verifications.get(index, {})
        verifier_answer = normalize_spaces(verification.get("correct_answer", ""))
        verifier_reason = normalize_spaces(verification.get("reason", ""))

        status = "needs_review"
        if (
            verification.get("valid")
            and verifier_answer
            and verifier_answer == item["correct_answer"]
            and verifier_answer in item["options"]
        ):
            status = "verified"

        existing = fetchall(
            """
            SELECT question
            FROM ai_practice_question_bank
            WHERE topic=%s
              AND subtopic=%s
              AND difficulty_level=%s
              AND active=TRUE
            """,
            (item["topic"], item["subtopic"], item["difficulty_level"]),
        )
        if any(
            _ai_practice_question_similarity(item["question"], row.get("question"))
            >= AI_PRACTICE_NEAR_DUPLICATE_THRESHOLD
            for row in existing
        ):
            continue

        inserted = execute(
            """
            INSERT INTO ai_practice_question_bank(
                topic,subtopic,difficulty_level,question,options_json,
                correct_answer,explanation,bloom_level,item_code,ai_model,
                prompt_version,verification_status,verifier_answer,
                verifier_reason,updated_at
            )
            VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CURRENT_TIMESTAMP)
            ON CONFLICT(item_code) DO NOTHING
            RETURNING id
            """,
            (
                item["topic"], item["subtopic"], item["difficulty_level"],
                item["question"], json.dumps(item["options"], ensure_ascii=False),
                item["correct_answer"], item.get("explanation", ""),
                item.get("bloom_level", "Aplicar"), item["item_code"],
                AI_PRACTICE_MODEL, AI_PRACTICE_PROMPT_VERSION, status,
                verifier_answer, verifier_reason,
            ),
            returning=True,
        )
        if inserted and status == "verified":
            verified += 1

    return verified




def generate_ai_practice_bank_batch(
    uid,
    topic,
    subtopic,
    difficulty,
    batch_size=10,
):
    difficulty = normalize_adaptive_difficulty(difficulty)
    client = ai_client()
    if not client:
        raise RuntimeError(
            "La API de IA no está disponible y no existen suficientes "
            "preguntas verificadas para este subtema."
        )

    difficulty_instruction = adaptive_difficulty_instruction(difficulty)

    prompt = f"""
Eres un experto en evaluación matemática universitaria y diseño de ítems.

Genera exactamente {int(batch_size)} preguntas NUEVAS de opción múltiple.

TEMA O MATERIA:
{topic}

SUBTEMA OBLIGATORIO:
{subtopic}

DIFICULTAD:
{difficulty}

CRITERIO COGNITIVO:
{difficulty_instruction}

REGLAS ESTRICTAS:
- Evalúa EXCLUSIVAMENTE el subtema "{subtopic}".
- No mezcles otros temas o subtemas.
- Cada pregunta debe tener exactamente 4 opciones distintas.
- Debe existir una sola respuesta inequívocamente correcta.
- correct_answer debe copiar exactamente una de las opciones.
- Incluye una explicación matemática breve y verificable.
- Ajusta Bloom y razonamiento a la dificultad.
- Evita repetir enunciados dentro del lote.
- Devuelve SOLO JSON válido, sin markdown.

Formato:
[
  {{
    "question": "enunciado",
    "options": ["A", "B", "C", "D"],
    "correct_answer": "A",
    "explanation": "procedimiento o verificación breve",
    "bloom_level": "Aplicar"
  }}
]
"""

    response = _ai_practice_generate_content_resilient(
        client,
        prompt,
        purpose="generación de preguntas",
    )
    parsed = _safe_json_loads(response.text, [])
    if not isinstance(parsed, list) or not parsed:
        raise RuntimeError(
            "La IA no devolvió un lote JSON válido de preguntas."
        )

    clean = []
    seen = set()
    for raw in parsed[: int(batch_size)]:
        item = _strict_ai_practice_item(
            raw,
            topic,
            subtopic,
            difficulty,
        )
        if not item or item["item_code"] in seen:
            continue
        seen.add(item["item_code"])
        clean.append(item)

    if not clean:
        raise RuntimeError(
            "Las preguntas generadas no superaron la validación estructural."
        )

    try:
        verifications = _verify_ai_practice_items(
            client,
            clean,
            topic,
            subtopic,
        )
    except Exception as exc:
        verifications = {
            index: {
                "valid": False,
                "correct_answer": "",
                "reason": (
                    "Verificación IA no disponible: "
                    f"{type(exc).__name__}"
                ),
            }
            for index in range(len(clean))
        }

    verified = _store_ai_practice_items(clean, verifications)
    return {
        "generated": len(clean),
        "verified": verified,
    }


def get_ai_practice_bank_questions(
    uid,
    topic,
    subtopic,
    difficulty,
    limit=40,
):
    ensure_ai_practice_bank_schema()
    difficulty = normalize_adaptive_difficulty(difficulty)

    rows = fetchall(
        """
        SELECT
            q.*,
            COALESCE(seen.seen_count, 0) AS user_seen_count
        FROM ai_practice_question_bank q
        LEFT JOIN (
            SELECT bank_question_id, COUNT(*) AS seen_count
            FROM ai_practice_question_attempts
            WHERE user_id=%s
            GROUP BY bank_question_id
        ) seen
          ON seen.bank_question_id=q.id
        WHERE q.topic=%s
          AND q.subtopic=%s
          AND q.difficulty_level=%s
          AND q.verification_status='verified'
          AND q.active=TRUE
        ORDER BY
            COALESCE(seen.seen_count, 0) ASC,
            q.usage_count ASC,
            q.created_at DESC
        LIMIT %s
        """,
        (
            int(uid),
            topic,
            subtopic,
            difficulty,
            int(limit),
        ),
    )

    output = []
    for row in rows:
        options = _safe_json_loads(row.get("options_json"), [])
        item = _strict_ai_practice_item(
            {
                "question": row.get("question"),
                "options": options,
                "correct_answer": row.get("correct_answer"),
                "explanation": row.get("explanation"),
                "bloom_level": row.get("bloom_level"),
            },
            topic,
            subtopic,
            difficulty,
        )
        if not item:
            continue
        item["bank_question_id"] = row.get("id")
        item["item_code"] = row.get("item_code") or item["item_code"]
        item["user_seen_count"] = int(row.get("user_seen_count") or 0)
        item["verification_status"] = row.get("verification_status")
        item["generation_source"] = "gemini_verified_bank"
        output.append(item)

    return output


def record_ai_practice_bank_result(
    uid,
    item,
    user_answer,
    is_correct,
    topic,
    subtopic,
    difficulty,
    attempt_key,
):
    bank_question_id = item.get("bank_question_id")
    if not bank_question_id:
        return False

    ensure_ai_practice_bank_schema()

    inserted = execute(
        """
        INSERT INTO ai_practice_question_attempts(
            bank_question_id, user_id, attempt_key,
            topic, subtopic, difficulty_level,
            user_answer, is_correct
        )
        VALUES(%s,%s,%s,%s,%s,%s,%s,%s)
        ON CONFLICT(attempt_key) DO NOTHING
        RETURNING id
        """,
        (
            int(bank_question_id),
            int(uid),
            str(attempt_key),
            topic,
            subtopic,
            normalize_adaptive_difficulty(difficulty),
            normalize_spaces(user_answer),
            bool(is_correct),
        ),
        returning=True,
    )

    if not inserted:
        return False

    execute(
        """
        UPDATE ai_practice_question_bank
        SET
            usage_count=usage_count+1,
            correct_count=correct_count+%s,
            incorrect_count=incorrect_count+%s,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=%s
        """,
        (
            1 if is_correct else 0,
            0 if is_correct else 1,
            int(bank_question_id),
        ),
    )
    return True


def adaptive_practice_questions(
    uid,
    current_topic,
    difficulty,
    n_questions=5,
    round_no=1,
    current_subtopic=None,
):
    """Bank-first practice: IA is used only when verified stock is insufficient."""
    difficulty = normalize_adaptive_difficulty(difficulty)

    if current_subtopic:
        reserved = reserve_ai_practice_bank_questions(
            uid,
            current_topic,
            current_subtopic,
            difficulty,
            n_questions=n_questions,
            round_no=round_no,
        )
        if len(reserved) >= int(n_questions):
            return reserved[: int(n_questions)]

        generation_rounds = 0
        while len(reserved) < int(n_questions) and generation_rounds < 2:
            generate_ai_practice_bank_batch(
                uid,
                current_topic,
                current_subtopic,
                difficulty,
                batch_size=max(10, int(n_questions) * 2),
            )
            generation_rounds += 1
            reserved = reserve_ai_practice_bank_questions(
                uid,
                current_topic,
                current_subtopic,
                difficulty,
                n_questions=n_questions,
                round_no=round_no,
            )

        if len(reserved) < int(n_questions):
            count = ai_practice_verified_count(
                current_topic, current_subtopic, difficulty
            )
            raise RuntimeError(
                "El banco verificado todavÃ­a no tiene suficientes preguntas para "
                f"{current_topic} â†’ {current_subtopic} â†’ {difficulty}. "
                f"Disponibles: {count}. El administrador puede abastecer previamente este banco."
            )
        return reserved[: int(n_questions)]

    pool = local_fast_adaptive_pool(current_topic)
    candidates = adaptive_questions_for_difficulty(pool, difficulty)
    if len(candidates) < int(n_questions):
        for q_topic, qdata in adaptive_quiz_for_user(uid, current_topic):
            question, options, correct_idx = qdata
            if not options:
                continue
            bloom = {
                "Inicial": "Comprender",
                "BÃ¡sico": "Comprender",
                "Intermedio": "Aplicar",
                "Avanzado": "Analizar",
            }[difficulty]
            candidates.append(
                {
                    "question": question,
                    "options": list(options),
                    "correct_answer": options[correct_idx],
                    "explanation": f"Repasa el concepto central relacionado con {q_topic} y justifica la respuesta.",
                    "bloom_level": bloom,
                    "difficulty_level": difficulty,
                    "topic": q_topic,
                    "item_code": stable_item_code(question),
                }
            )
    unique = []
    seen = set()
    for item in candidates:
        code = item.get("item_code") or stable_item_code(item.get("question", ""))
        if code in seen:
            continue
        seen.add(code)
        unique.append(dict(item))
    rng = random.Random(
        hashlib.sha256(
            f"practice|{uid}|{current_topic}|{difficulty}|{int(round_no)}".encode("utf-8")
        ).hexdigest()
    )
    rng.shuffle(unique)
    return unique[: int(n_questions)]









def adaptive_learning_prompts(weak_topics, next_difficulty, fallback_topic):

    topics = [normalize_spaces(x) for x in (weak_topics or []) if normalize_spaces(x)]

    focus = topics[0] if topics else (normalize_spaces(fallback_topic) or "el tema evaluado")

    level = normalize_adaptive_difficulty(next_difficulty)

    return [

        f"Explícame {focus} con un ejemplo universitario de nivel {level}. Después hazme una pregunta guiada sin darme la respuesta.",

        f"Dame 3 ejercicios progresivos sobre {focus}, desde el nivel que domino hasta {level}, y espera mi respuesta antes de corregirme.",

        f"Voy a resolver un problema de {focus}. Evalúa mi procedimiento paso a paso, identifica mi error conceptual y dime qué debo dominar para avanzar a {level}.",

    ]





def adaptive_complexity_evidence(questions, difficulty):

    difficulty = normalize_adaptive_difficulty(difficulty)

    allowed = adaptive_bloom_levels_for_difficulty(difficulty)

    distribution = {}

    aligned = 0

    for q in questions or []:

        bloom = str(q.get("bloom_level") or "Sin nivel").strip() or "Sin nivel"

        distribution[bloom] = distribution.get(bloom, 0) + 1

        if bloom in allowed:

            aligned += 1

    summary = ", ".join(f"{k}: {v}" for k, v in sorted(distribution.items(), key=lambda kv: bloom_rank(kv[0]))) or "Sin datos"

    return {

        "aligned": aligned,

        "total": len(questions or []),

        "distribution": summary,

        "instruction": adaptive_difficulty_instruction(difficulty),

    }



def make_assessment_seed(uid, quiz_type, academic_context, salt=None):

    context = academic_context or {}

    raw = "|".join([

        str(uid),

        str(quiz_type or "adaptive"),

        str(context.get("subject", "")),

        str(context.get("course_level", "")),

        str(context.get("parallel", "")),

        str(context.get("shift", "")),

        str(salt or time.time_ns()),

    ])

    return hashlib.sha256(raw.encode("utf-8")).hexdigest()





def normalize_question_payload(question):

    if not isinstance(question, dict):

        return None

    opts = [normalize_spaces(o) for o in question.get("options", []) if normalize_spaces(o)]

    correct = normalize_spaces(question.get("correct_answer", ""))

    if correct and correct not in opts:

        opts.append(correct)

    opts = list(dict.fromkeys(opts))

    if len(opts) > 4:

        opts = opts[:4] if correct in opts[:4] else opts[:3] + [correct]

    if len(opts) < 2 or not correct:

        return None

    question_text = normalize_spaces(question.get("question", ""))

    if not question_text:

        return None

    payload = {

        "question": question_text,

        "options": opts,

        "correct_answer": correct,

        "explanation": normalize_spaces(question.get("explanation", "")),

        "bloom_level": normalize_spaces(question.get("bloom_level", "Aplicar")) or "Aplicar",

        "topic": normalize_spaces(question.get("topic", "")),

    }

    for key in ["subtopic", "dimension", "indicator", "competence", "difficulty_level"]:

        if question.get(key):

            payload[key] = normalize_spaces(question.get(key))

    payload["item_code"] = normalize_spaces(question.get("item_code")) or stable_item_code(question_text)

    return payload





def standardized_research_form(questions, quiz_type, version_code, n_questions, academic_context):

    clean, seen = [], set()

    for question in questions:

        item = normalize_question_payload(question)

        if not item or item["item_code"] in seen:

            continue

        seen.add(item["item_code"])

        clean.append(item)

    form_raw = "|".join([

        str((academic_context or {}).get("subject", "")), RESEARCH_FOCUS_TOPIC,

        str(quiz_type), str(version_code), str(n_questions),

    ])

    form_rng = random.Random(hashlib.sha256(form_raw.encode("utf-8")).hexdigest())

    form_rng.shuffle(clean)

    selected = clean[:int(n_questions)]

    return enrich_research_questions(selected, n_questions)





def randomize_questions_for_student(questions, uid, quiz_type, n_questions, seed):

    rng = random.Random(seed)

    clean = []

    seen = set()

    for q in questions:

        item = normalize_question_payload(q)

        if not item:

            continue

        key = strip_accents(item["question"]).lower()

        if key in seen:

            continue

        seen.add(key)

        opts = item["options"][:]

        rng.shuffle(opts)

        item["options"] = opts

        clean.append(item)

    rng.shuffle(clean)

    return clean[:int(n_questions)]





