def _p5a6_grade_research_quiz_resumable(

    user_id,

    quiz_id,

    attempt_id,

    answers,

):

    quiz, questions = load_adaptive_quiz(quiz_id)

    if not quiz:

        raise ValueError(

            "Instrumento de investigacion no encontrado."

        )



    quiz_type = str(quiz.get("quiz_type") or "").lower()

    if quiz_type not in {"pretest", "posttest"}:

        raise ValueError(

            "El instrumento no es pretest/posttest."

        )

    if int(quiz.get("user_id")) != int(user_id):

        raise ValueError(

            "El instrumento no pertenece al estudiante autenticado."

        )



    connection = _p5a6_transaction_connection()

    try:

        with connection.cursor() as cur:

            cur.execute(

                """

                SELECT status, adaptive_quiz_id, assessment_kind

                FROM public.assessment_attempts

                WHERE id=%s

                  AND user_id=%s

                FOR UPDATE

                """,

                (attempt_id, user_id),

            )

            attempt_row = cur.fetchone()



        if not attempt_row:

            raise ValueError(

                "Intento reanudable no encontrado."

            )



        attempt_status = attempt_row.get("status")

        attempt_quiz_id = attempt_row.get("adaptive_quiz_id")

        attempt_kind = str(

            attempt_row.get("assessment_kind") or ""

        ).lower()



        if (

            attempt_quiz_id is None

            or int(attempt_quiz_id) != int(quiz_id)

        ):

            raise ValueError(

                "El intento reanudable no corresponde "

                "a este instrumento."

            )

        if attempt_kind != quiz_type:

            raise ValueError(

                "El tipo de intento no coincide con el instrumento."

            )



        with connection.cursor() as cur:

            cur.execute(

                """

                SELECT status, score, passed, recommendation

                FROM public.adaptive_quizzes

                WHERE id=%s

                  AND user_id=%s

                FOR UPDATE

                """,

                (quiz_id, user_id),

            )

            quiz_row = cur.fetchone()



        if not quiz_row:

            raise ValueError(

                "Instrumento no encontrado para el estudiante."

            )



        quiz_status = str(

            quiz_row.get("status") or ""

        ).lower()



        if (

            attempt_status == "submitted"

            and quiz_status == "completed"

        ):

            connection.rollback()

            return (

                float(quiz_row.get("score") or 0),

                bool(quiz_row.get("passed")),

                [],

                quiz_row.get("recommendation") or "",

            )



        if attempt_status != "in_progress":

            raise ValueError(

                "El intento ya no esta activo."

            )

        if quiz_status != "generated":

            raise ValueError(

                "El instrumento ya no esta disponible para envio."

            )



        elapsed_seconds = _p5a6_elapsed_seconds(

            connection,

            attempt_id,

            user_id,

        )

        total = max(1, len(questions))

        per_question_time = (

            round(float(elapsed_seconds or 0) / total, 2)

            if elapsed_seconds

            else None

        )



        correct = 0

        weak_topics = []

        graded_questions = []



        for ordinal, question in enumerate(

            questions,

            start=1,

        ):

            question_id = question["id"]

            answer = (answers or {}).get(str(question_id))

            if answer is None or str(answer).strip() == "":

                raise ValueError(

                    "Debes responder todas las preguntas "

                    "antes de enviar."

                )



            position = question.get("position") or ordinal

            resumable_save_attempt_answer(

                connection,

                attempt_id=attempt_id,

                user_id=user_id,

                question_key=f"adaptive_question:{question_id}",

                question_id=question_id,

                answer_payload={"value": answer},

                elapsed_seconds=elapsed_seconds,

                current_position=position,

            )



            is_correct = (

                str(answer).strip()

                == str(question.get("correct_answer", "")).strip()

            )

            if is_correct:

                correct += 1

            else:

                weak_topics.append(

                    question.get("question", "")[:120]

                )



            conceptual_error = conceptual_error_for_question(

                question,

                is_correct,

            )

            estimated_confidence = 0.85 if is_correct else 0.35



            with connection.cursor() as cur:

                cur.execute(

                    """

                    UPDATE public.adaptive_questions

                    SET user_answer=%s,

                        is_correct=%s,

                        attempts=%s,

                        response_time_seconds=%s,

                        conceptual_error=%s,

                        estimated_confidence=%s

                    WHERE id=%s

                      AND quiz_id=%s

                    """,

                    (

                        answer,

                        is_correct,

                        1,

                        per_question_time,

                        conceptual_error,

                        estimated_confidence,

                        question_id,

                        quiz_id,

                    ),

                )

                if cur.rowcount != 1:

                    raise ValueError(

                        "No se pudo actualizar una pregunta."

                    )



            graded = dict(question)

            graded["user_answer"] = answer

            graded["is_correct"] = is_correct

            graded["conceptual_error"] = conceptual_error

            graded["estimated_confidence"] = estimated_confidence

            graded["response_time_seconds"] = per_question_time

            graded_questions.append(graded)



        score = round(correct / total * 100, 2)

        passed = score >= 70

        diagnosis = build_quiz_diagnosis(

            score,

            graded_questions,

        )

        recommendation = (

            "Aprobado. Puedes avanzar al siguiente reto."

            if passed

            else (

                "Refuerzo automatico sugerido: revisa las "

                "preguntas falladas y estudia las microclases "

                "sugeridas."

            )

        )



        with connection.cursor() as cur:

            cur.execute(

                """

                UPDATE public.adaptive_quizzes

                SET score=%s,

                    passed=%s,

                    status='completed',

                    recommendation=%s,

                    completed_at=%s,

                    dimension_scores_json=%s,

                    diagnosis_json=%s,

                    cognitive_profile=%s,

                    learning_plan_json=%s,

                    total_time_seconds=%s

                WHERE id=%s

                  AND user_id=%s

                  AND status='generated'

                """,

                (

                    score,

                    passed,

                    recommendation,

                    now(),

                    json.dumps(

                        diagnosis.get("dimension_scores", {}),

                        ensure_ascii=False,

                    ),

                    json.dumps(

                        diagnosis,

                        ensure_ascii=False,

                    ),

                    diagnosis.get("profile", ""),

                    json.dumps(

                        diagnosis.get("learning_plan", {}),

                        ensure_ascii=False,

                    ),

                    float(elapsed_seconds or 0),

                    quiz_id,

                    user_id,

                ),

            )

            if cur.rowcount != 1:

                raise ValueError(

                    "No se pudo finalizar el instrumento."

                )



            profile_field = (

                "pretest_estado"

                if quiz_type == "pretest"

                else "posttest_estado"

            )

            cur.execute(

                f"""

                UPDATE public.profiles

                SET {profile_field}='completado'

                WHERE user_id=%s

                """,

                (user_id,),

            )

            if cur.rowcount != 1:

                raise ValueError(

                    "No se pudo actualizar el estado "

                    "de investigacion del estudiante."

                )



        resumable_submit_attempt(

            connection,

            attempt_id=attempt_id,

            user_id=user_id,

            elapsed_seconds=elapsed_seconds,

        )

        connection.commit()



        return (

            score,

            passed,

            weak_topics,

            recommendation,

        )

    except Exception:

        connection.rollback()

        raise

    finally:

        connection.close()



def render_student_adaptive_evaluation(user, prof, topic, subtopic):

    academic_context = academic_context_from_profile(prof)

    is_control_group = str(prof.get("research_group") or "").strip().lower() == "control"



    st.markdown("### Evaluaciones del docente")

    published_assessments = get_student_teacher_assessments(

        academic_context,

        user["id"],

    )



    if not published_assessments:

        st.caption(

            "No hay evaluaciones docentes publicadas para tu contexto academico."

        )



    for assessment in published_assessments:

        if st.button(

            f"Iniciar / continuar: {assessment['title']}",

            key=f"start_teacher_assessment_{assessment['id']}",

        ):

            try:

                bank_quiz = start_teacher_assessment_attempt(

                    user["id"],

                    assessment["id"],

                    academic_context,

                )

                st.session_state["teacher_assessment_quiz_id"] = bank_quiz["id"]



                if bank_quiz.get("status") == "generated":

                    progress = _p5a6_prepare_teacher_attempt(

                        user["id"],

                        bank_quiz,

                        register_resume=True,

                    )

                    st.session_state["teacher_assessment_attempt_id"] = progress["attempt"]["id"]



                st.rerun()

            except Exception as exc:

                st.error(str(exc))



    bank_quiz_id = st.session_state.get("teacher_assessment_quiz_id")



    if bank_quiz_id:

        bank_quiz, bank_questions = load_adaptive_quiz(bank_quiz_id)



        if bank_quiz and bank_quiz.get("status") == "generated":

            try:

                progress = _p5a6_prepare_teacher_attempt(

                    user["id"],

                    bank_quiz,

                    register_resume=False,

                )

            except Exception as exc:

                st.error(f"No fue posible recuperar el intento: {exc}")

                progress = None



            if progress:

                attempt = progress["attempt"]

                attempt_id = attempt["id"]

                st.session_state["teacher_assessment_attempt_id"] = attempt_id



                total_questions = len(bank_questions)

                answered_count = progress["answered_count"]

                pending_count = max(0, total_questions - answered_count)

                server_elapsed_seconds = progress.get(

                    "server_elapsed_seconds",

                    attempt.get("elapsed_seconds", 0),

                )



                ux1, ux2, ux3 = st.columns(3)

                ux1.metric(

                    "Respondidas",

                    f"{answered_count}/{total_questions}",

                )

                ux2.metric("Pendientes", pending_count)

                ux3.metric(

                    "Tiempo registrado",

                    _p5a6_format_elapsed_seconds(server_elapsed_seconds),

                )

                st.progress(answered_count / max(1, total_questions))

                st.caption(

                    "Guardado automático en base de datos. "

                    "Puedes cerrar esta página y continuar más tarde "

                    "sin perder las respuestas confirmadas."

                )



                if attempt.get("resume_count", 0) > 0:

                    st.info(

                        "Intento recuperado correctamente. "

                        f"Reingresos registrados: {int(attempt.get('resume_count') or 0)}."

                    )



                autosave_error = st.session_state.get(

                    "teacher_assessment_autosave_error"

                )

                if autosave_error:

                    st.error(

                        "No se pudo confirmar el guardado automático de la última "

                        f"respuesta. Mantén esta página abierta y vuelve a intentarlo. "

                        f"Detalle: {autosave_error}"

                    )

                elif answered_count:

                    st.success("Guardado automático activo.")



                answers = {}



                for ordinal, question in enumerate(bank_questions, start=1):

                    question_id = question["id"]

                    options = _safe_json_loads(question.get("options_json"), [])

                    question_key = f"adaptive_question:{question_id}"

                    widget_key = f"bank_answer_{question_id}"



                    saved_row = progress["answers_by_key"].get(question_key)

                    saved_value = None

                    if saved_row:

                        payload = saved_row.get("answer_json") or {}

                        if isinstance(payload, dict):

                            saved_value = payload.get("value")



                    if widget_key not in st.session_state and saved_value in options:

                        st.session_state[widget_key] = saved_value



                    position = question.get("position") or ordinal

                    answers[str(question_id)] = st.radio(

                        question["question"],

                        options,

                        index=None,

                        key=widget_key,

                        on_change=_p5a6_autosave_teacher_answer,

                        args=(

                            user["id"],

                            attempt_id,

                            question_id,

                            position,

                            widget_key,

                        ),

                    )

                    if saved_row:

                        st.caption("✓ Respuesta guardada")



                st.caption(

                    "El envío final cerrará el intento y las respuestas "

                    "ya no podrán modificarse."

                )

                if st.button(

                    "Enviar evaluacion del docente",

                    key=f"grade_teacher_assessment_{bank_quiz_id}",

                ):

                    unanswered = [

                        qid

                        for qid, answer in answers.items()

                        if answer is None or str(answer).strip() == ""

                    ]



                    if unanswered:

                        st.warning(

                            "Debes responder todas las preguntas antes de enviar la evaluacion."

                        )

                    else:

                        try:

                            _p5a6_grade_teacher_assessment_resumable(

                                user["id"],

                                bank_quiz_id,

                                attempt_id,

                                answers,

                            )

                            st.session_state["teacher_assessment_autosave_error"] = None

                            st.success("Evaluacion enviada correctamente.")

                            st.rerun()

                        except Exception as exc:

                            st.error(str(exc))



        elif bank_quiz:

            st.info(

                f"Evaluacion completada. Puntaje: {bank_quiz.get('score', 0)}%"

            )



    st.markdown('### 🧠 Evaluación e investigación')
    st.caption('Selecciona evaluación adaptativa, pretest o posttest. Los instrumentos de investigación usan 20 preguntas y quedan vinculados a materia, curso, paralelo y jornada.')



    official_student = is_official_profile(prof)

    if official_student and (not prof.get("consentimiento_informado") or not prof.get("usar_en_investigacion")):

        st.error("Debes completar el consentimiento informado antes de acceder a los instrumentos oficiales.")

        return

    if official_student and str(prof.get("research_group") or "").strip().lower() not in {"experimental", "control"}:

        st.error("El docente debe asignarte al grupo Experimental o Control antes de iniciar el pretest.")

        return



    if official_student and str(prof.get("pretest_estado") or "pendiente").lower() != "completado":

        mode_options = ["Pretest"]

    elif official_student:

        mode_options = ["Pretest", "Posttest"]

    else:

        mode_options = ["Evaluación adaptativa", "Pretest", "Posttest"]

    if st.session_state.get("assessment_mode") not in mode_options:

        st.session_state["assessment_mode"] = mode_options[0]

    mode_label = st.radio(

        "Tipo de evaluación",

        mode_options,

        horizontal=True,

        key="assessment_mode",

    )

    quiz_type = {

        "Evaluación adaptativa": "adaptive",

        "Pretest": "pretest",

        "Posttest": "posttest",

    }[mode_label]

    research_mode = is_research_quiz(quiz_type)

    current_key = f"current_adaptive_quiz_id_{quiz_type}"



    profile = get_student_consultation_profile(user["id"])

    a,b,c = st.columns(3)

    a.markdown(f"<div class='metric'><b>{profile['total_questions']}</b><br><span>Consultas usadas</span></div>", unsafe_allow_html=True)

    b.markdown(f"<div class='metric'><b>{academic_context.get('cohort')}</b><br><span>Cohorte</span></div>", unsafe_allow_html=True)

    last_quiz = get_latest_adaptive_quiz(user["id"], quiz_type)

    completed_pretest = get_latest_adaptive_quiz(user["id"], "pretest")

    last_score = "N/D" if not last_quiz or last_quiz.get("score") is None else f"{float(last_quiz.get('score')):.0f}%"

    c.markdown(f"<div class='metric'><b>{last_score}</b><br><span>{quiz_type_label(quiz_type)}</span></div>", unsafe_allow_html=True)



    plans = pd.DataFrame(get_analytic_plans())

    if not plans.empty and research_mode and "subject" in plans.columns:

        subject_key = strip_accents(academic_context.get("subject", "")).lower()

        filtered_plans = plans[

            plans["subject"].fillna("").astype(str).map(lambda x: strip_accents(x).lower()).isin(["", subject_key])

        ].copy()

        if not filtered_plans.empty:

            plans = filtered_plans

    plan_options = [None] + (plans["id"].tolist() if not plans.empty else [])

    plan_id = st.selectbox(

        "Plan analítico base",

        plan_options,

        format_func=lambda x: "Todos los planes disponibles" if x is None else f"{x} · {plans.loc[plans['id']==x,'title'].iloc[0]}",

    )

    difficulty_key = f"adaptive_difficulty_{quiz_type}"

    difficulty = st.selectbox(

        "Dificultad para la próxima evaluación",

        ADAPTIVE_DIFFICULTIES,

        index=2,

        disabled=research_mode,

        key=difficulty_key,

    )

    difficulty = normalize_adaptive_difficulty(difficulty)

    n_questions = RESEARCH_QUESTION_COUNT if research_mode else st.slider(

        "Número de preguntas", 5, 20, 10, key=f"adaptive_question_count_{quiz_type}"

    )



    if research_mode:

        st.markdown(

            f"<div class='eval-card'><b>{quiz_type_label(quiz_type)} de investigación</b><br>"

            f"<span class='eval-chip'>{academic_context.get('subject')}</span>"

            f"<span class='eval-chip'>{RESEARCH_FOCUS_TOPIC}</span>"

            f"<span class='eval-chip'>{academic_context.get('cohort')}</span>"

            f"<span class='eval-chip'>{RESEARCH_QUESTION_COUNT} preguntas aleatorias</span></div>",

            unsafe_allow_html=True,

        )



    focus_mismatch = research_mode and last_quiz and not quiz_matches_research_focus(last_quiz)

    if focus_mismatch:

        st.warning(

            f"Este {quiz_type_label(quiz_type).lower()} fue generado con un tema anterior "

            f"({last_quiz.get('source_topic') or 'sin tema'}). Debe regenerarse con {RESEARCH_FOCUS_TOPIC}."

        )

        if last_quiz.get("status") == "completed":

            st.error("Este instrumento ya fue completado. Para una prueba limpia usa un estudiante nuevo o elimina ese intento desde Supabase.")

            return

        if st.button(f"Regenerar {quiz_type_label(quiz_type)} con {RESEARCH_FOCUS_TOPIC}", use_container_width=True):

            try:

                with st.spinner(f"Regenerando {quiz_type_label(quiz_type).lower()}..."):

                    supersede_adaptive_quiz(last_quiz["id"])

                    st.session_state.pop(current_key, None)

                    quiz_id = create_adaptive_quiz(

                        user["id"],

                        plan_id=plan_id,

                        difficulty=difficulty,

                        n_questions=n_questions,

                        quiz_type=quiz_type,

                        academic_context=academic_context,

                    )

                st.session_state[current_key] = quiz_id

                st.rerun()

            except Exception as e:

                st.error("No se pudo regenerar el instrumento.")

                st.exception(e)

        return



    if quiz_type == "posttest":

        if not completed_pretest or completed_pretest.get("status") != "completed":

            st.warning("El posttest se habilita cuando el estudiante haya completado el pretest.")

            return

        if is_control_group:

            st.info("Grupo control: continúa con el postest según el protocolo, sin intervención del tutor adaptativo.")

        else:

            render_research_lesson_panel(user, academic_context, completed_pretest)

            render_guided_exercises_panel(user, academic_context, completed_pretest)

            if official_student:

                lesson_ready = research_learning_event_exists(user["id"], "class_generated", completed_pretest["id"])

                exercises_ready = research_learning_event_exists(user["id"], "guided_exercises_completed", completed_pretest["id"])

                if not lesson_ready or not exercises_ready:

                    pending_steps = []

                    if not lesson_ready:

                        pending_steps.append("generar y estudiar la clase de refuerzo")

                    if not exercises_ready:

                        pending_steps.append("completar los ejercicios guiados")

                    st.warning("Antes del posttest debes " + " y ".join(pending_steps) + ".")

                    return



    if not research_mode:

        st.caption("Carga rápida: BunsekiChat usa primero el banco validado local y recurre al generador externo solo cuando faltan ítems adecuados.")



    col1, col2 = st.columns(2)

    can_generate = not (research_mode and last_quiz)

    generate_label = (

        f"Iniciar {quiz_type_label(quiz_type)}"

        if research_mode

        else f"Generar nueva evaluación · {difficulty}"

    )

    if col1.button(generate_label, use_container_width=True, disabled=not can_generate):

        try:

            with st.spinner(f"Generando {quiz_type_label(quiz_type).lower()}..."):

                quiz_id = create_adaptive_quiz(

                        user["id"],

                        plan_id=plan_id,

                        difficulty=difficulty,

                        n_questions=n_questions,

                        quiz_type=quiz_type,

                        academic_context=academic_context,

                    )

            st.session_state[current_key] = quiz_id

            st.success("Instrumento generado. Si no ves las preguntas, baja un poco en la página.")

            time.sleep(0.4)

            st.rerun()

        except Exception as e:

            st.error("No se pudo generar el instrumento. Revisa el detalle técnico o envía esta captura.")

            st.exception(e)

            return

    if research_mode and not can_generate:

        if last_quiz.get("status") == "completed":

            st.info(f"{quiz_type_label(quiz_type)} ya fue completado. El resultado queda registrado para la investigación.")

        else:

            st.info(f"{quiz_type_label(quiz_type)} ya fue generado. Completa el instrumento pendiente para conservar la trazabilidad.")



    if not research_mode and last_quiz and last_quiz.get("status") == "completed" and not last_quiz.get("passed"):

        if col2.button("Reintento automático por no alcanzar 70%", use_container_width=True):

            _, questions = load_adaptive_quiz(last_quiz["id"])

            weak = [q.get("question","") for q in questions if not q.get("is_correct")]

            quiz_id = create_adaptive_quiz(

                user["id"],

                plan_id=last_quiz.get("plan_id"),

                difficulty=difficulty,

                n_questions=n_questions,

                parent_quiz_id=last_quiz["id"],

                retry_focus="\n".join(weak[:5]),

                quiz_type=quiz_type,

                academic_context=academic_context

            )

            st.session_state[current_key] = quiz_id

            st.rerun()



    quiz_id = st.session_state.get(current_key) or (last_quiz.get("id") if last_quiz else None)

    if not quiz_id:

        st.info("Inicia una evaluación para comenzar.")

        return



    quiz, questions = load_adaptive_quiz(int(quiz_id))

    if not quiz or not questions:

        st.warning("No se pudo cargar la evaluación.")

        return



    if not research_mode:

        visible_difficulty = normalize_adaptive_difficulty(

            quiz.get("difficulty") or "Intermedio"

        )

        if visible_difficulty != difficulty:

            st.info(

                f"La evaluación visible fue generada en nivel {visible_difficulty}. "

                f"Has seleccionado {difficulty} para la próxima evaluación. "

                "Pulsa el botón de generación para crear un instrumento nuevo con ese nivel."

            )



    st.markdown(

        f"<div class='eval-card'><h3>{quiz.get('title','Evaluación adaptativa')}</h3>"

        f"<span class='eval-chip'>Intento: {quiz.get('attempt_no',1)}</span>"

        f"<span class='eval-chip'>Tipo: {quiz_type_label(quiz.get('quiz_type') or 'adaptive')}</span>"

        f"<span class='eval-chip'>Dificultad: {quiz.get('difficulty','')}</span>"

        f"<span class='eval-chip'>Estado: {quiz.get('status','')}</span>"

        f"<span class='eval-chip'>Cohorte: {quiz.get('cohort') or academic_context.get('cohort')}</span>"

        f"<span class='eval-chip'>Tema: {quiz.get('source_topic') or 'Adaptativo'}</span></div>",

        unsafe_allow_html=True,

    )



    if not research_mode:

        complexity = adaptive_complexity_evidence(

            questions,

            quiz.get("difficulty") or difficulty,

        )

        st.caption(

            f"Evidencia adaptativa: {complexity['aligned']}/{complexity['total']} preguntas "

            f"alineadas al nivel {normalize_adaptive_difficulty(quiz.get('difficulty') or difficulty)}. "

            f"Bloom: {complexity['distribution']}."

        )

        if complexity["total"] and complexity["aligned"] < complexity["total"]:

            st.warning("Algunas preguntas no coinciden con la demanda cognitiva esperada; genera un nuevo intento antes de usar este resultado como evidencia.")



    if quiz.get("status") == "completed":

        score = float(quiz.get("score") or 0)

        cls = "eval-result-pass" if quiz.get("passed") else "eval-result-fail"

        st.markdown(f"<div class='{cls}'>Resultado: {score:.0f}% · {'Aprobado' if quiz.get('passed') else 'No aprobado'} · {quiz.get('recommendation') or ''}</div>", unsafe_allow_html=True)

        render_quiz_diagnosis(quiz)

        for q in questions:

            icon = "✅" if q.get("is_correct") else "❌"

            st.markdown(f"<div class='eval-question'><b>{icon} {q.get('question')}</b><br><span class='small'>Tu respuesta: {q.get('user_answer') or 'Sin respuesta'} · Correcta: {q.get('correct_answer')}</span><br><br>{q.get('explanation') or ''}</div>", unsafe_allow_html=True)

        if (quiz.get("quiz_type") or quiz_type) == "pretest":

            if is_control_group:

                st.info("Grupo control: espera el momento establecido por el docente para realizar el postest.")

            else:

                render_research_lesson_panel(user, academic_context, quiz)

                render_guided_exercises_panel(user, academic_context, quiz)

        if (quiz.get("quiz_type") or quiz_type) == "posttest":

            if not is_control_group:

                render_final_survey(user, quiz)

        return



    if research_mode:

        session_attempt_key = f"research_attempt_id_{quiz_id}"

        register_resume = (

            session_attempt_key not in st.session_state

        )



        try:

            progress = _p5a6_prepare_research_attempt(

                user["id"],

                quiz,

                register_resume=register_resume,

            )

        except Exception as exc:

            st.error(

                "No fue posible recuperar "

                f"el instrumento: {exc}"

            )

            return



        attempt = progress["attempt"]

        attempt_id = attempt["id"]

        st.session_state[session_attempt_key] = attempt_id



        total_questions = len(questions)

        answered_count = progress["answered_count"]

        pending_count = max(0, total_questions - answered_count)

        server_elapsed_seconds = progress.get(

            "server_elapsed_seconds",

            attempt.get("elapsed_seconds", 0),

        )



        ux1, ux2, ux3 = st.columns(3)

        ux1.metric(

            "Respondidas",

            f"{answered_count}/{total_questions}",

        )

        ux2.metric("Pendientes", pending_count)

        ux3.metric(

            "Tiempo registrado",

            _p5a6_format_elapsed_seconds(server_elapsed_seconds),

        )

        st.progress(

            answered_count / max(1, total_questions)

        )

        st.caption(

            "Guardado automático en base de datos. "

            "Puedes cerrar esta página y continuar más tarde "

            "sin perder las respuestas confirmadas."

        )



        if attempt.get("resume_count", 0) > 0:

            st.info(

                "Intento recuperado correctamente. "

                f"Reingresos registrados: {int(attempt.get('resume_count') or 0)}."

            )



        autosave_error_key = (

            f"research_assessment_autosave_error_{quiz_id}"

        )

        autosave_error = st.session_state.get(

            autosave_error_key

        )

        if autosave_error:

            st.error(

                "No se pudo confirmar el guardado automático de la última "

                f"respuesta. Mantén esta página abierta y vuelve a intentarlo. "

                f"Detalle: {autosave_error}"

            )

        elif answered_count:

            st.success("Guardado automático activo.")



        answers = {}

        for i, q in enumerate(

            questions,

            start=1,

        ):

            opts = (

                q.get("options")

                or _safe_json_loads(

                    q.get("options_json"),

                    [],

                )

            )

            st.markdown(

                f"<div class='eval-question'>"

                f"<b>{i}. {q.get('question')}</b><br>"

                f"<span class='eval-chip'>"

                f"{q.get('bloom_level') or 'Aplicar'}"

                f"</span>"

                f"<span class='eval-chip'>"

                f"{q.get('dimension') or 'Aplicaciones'}"

                f"</span>"

                f"<span class='eval-chip'>"

                f"{q.get('difficulty_level') or 'Medio'}"

                f"</span></div>",

                unsafe_allow_html=True,

            )



            question_id = q["id"]

            question_key = f"adaptive_question:{question_id}"

            widget_key = f"research_q_{quiz_id}_{question_id}"



            saved_row = progress[

                "answers_by_key"

            ].get(question_key)

            saved_value = None

            if saved_row:

                payload = (

                    saved_row.get("answer_json")

                    or {}

                )

                if isinstance(payload, dict):

                    saved_value = payload.get("value")



            if (

                widget_key not in st.session_state

                and saved_value in opts

            ):

                st.session_state[

                    widget_key

                ] = saved_value



            position = q.get("position") or i

            answers[str(question_id)] = st.radio(

                "Selecciona una respuesta",

                opts,

                index=None,

                key=widget_key,

                label_visibility="collapsed",

                on_change=_p5a6_autosave_research_answer,

                args=(

                    user["id"],

                    attempt_id,

                    quiz_id,

                    question_id,

                    position,

                    widget_key,

                ),

            )

            if saved_row:

                st.caption("✓ Respuesta guardada")



        st.caption(

            "El envío final cerrará el intento y las respuestas "

            "ya no podrán modificarse."

        )

        if st.button(

            f"Enviar {quiz_type_label(quiz_type)}",

            key=f"submit_research_quiz_{quiz_id}",

            type="primary",

            use_container_width=True,

        ):

            unanswered = [

                question_id

                for question_id, answer

                in answers.items()

                if answer is None

                or str(answer).strip() == ""

            ]

            if unanswered:

                st.warning(

                    "Debes responder todas las preguntas "

                    "antes de enviar."

                )

            else:

                try:

                    (

                        score,

                        passed,

                        weak_topics,

                        recommendation,

                    ) = _p5a6_grade_research_quiz_resumable(

                        user["id"],

                        int(quiz_id),

                        attempt_id,

                        answers,

                    )



                    event_type = f"{quiz_type}_submitted"

                    gps_actual = capture_browser_gps(

                        user["id"],

                        page="evaluacion_ia",

                        topic=topic,

                        subtopic=subtopic,

                        event_type=event_type,

                        show_status=False,

                    )

                    log_location_event(

                        user["id"],

                        event_type,

                        page="evaluacion_ia",

                        topic=topic,

                        subtopic=subtopic,

                        gps=gps_actual,

                    )



                    if passed:

                        st.success(

                            f"Resultado: {score:.0f}%. "

                            "Aprobaste la evaluacion."

                        )

                    else:

                        st.warning(

                            f"Resultado registrado: "

                            f"{score:.0f}%."

                        )



                    st.rerun()

                except Exception as exc:

                    st.error(str(exc))

        return



    with st.form(f"adaptive_quiz_form_{quiz_id}"):

        timer_key = f"quiz_started_at_{quiz_id}"

        if timer_key not in st.session_state:

            st.session_state[timer_key] = time.time()

        answers = {}

        for i, q in enumerate(questions, start=1):

            opts = q.get("options") or _safe_json_loads(q.get("options_json"), [])

            st.markdown(

                f"<div class='eval-question'><b>{i}. {q.get('question')}</b><br>"

                f"<span class='eval-chip'>{q.get('bloom_level') or 'Aplicar'}</span>"

                f"<span class='eval-chip'>{q.get('dimension') or 'Aplicaciones'}</span>"

                f"<span class='eval-chip'>{q.get('difficulty_level') or quiz.get('difficulty') or 'Intermedio'}</span></div>",

                unsafe_allow_html=True

            )

            answers[str(q["id"])] = st.radio("Selecciona una respuesta", opts, key=f"adaptive_q_{quiz_id}_{q['id']}", label_visibility="collapsed")

        submitted = st.form_submit_button("Calificar evaluación", use_container_width=True)



    if submitted:

        elapsed_seconds = round(time.time() - float(st.session_state.get(f"quiz_started_at_{quiz_id}", time.time())), 2)

        score, passed, weak_topics, recommendation = grade_adaptive_quiz(int(quiz_id), answers, elapsed_seconds=elapsed_seconds)

        event_type = f"{quiz_type}_submitted"

        gps_actual = capture_browser_gps(user['id'], page='evaluacion_ia', topic=topic, subtopic=subtopic, event_type=event_type, show_status=False)

        log_location_event(user['id'], event_type, page='evaluacion_ia', topic=topic, subtopic=subtopic, gps=gps_actual)

        if passed:

            st.success(f"Resultado: {score:.0f}%. Aprobaste la evaluación.")

        else:

            if research_mode:

                st.warning(f"Resultado registrado: {score:.0f}%.")

            else:

                st.warning(f"Resultado: {score:.0f}%. No alcanzaste el 70%. Se habilitó el reintento automático.")

        st.rerun()





