def render_student_sidebar(prof):

    sidebar_brand("Estudiante", "Tutor matemático universitario")

    st.sidebar.markdown("<div class='saas-section-title'>Navegación</div>", unsafe_allow_html=True)

    is_control_group = str(prof.get("research_group") or "").strip().lower() == "control"

    official_student = is_official_profile(prof)

    pretest_completed = str(prof.get("pretest_estado") or "pendiente").strip().lower() == "completado"

    if official_student and not pretest_completed:

        student_pages = ["🧠 Evaluación"]

    elif official_student and is_control_group:

        student_pages = ["🧠 Evaluación", "📈 Mi progreso"]

    else:

        student_pages = ["💬 Tutor", "🧠 Evaluación", "📘 Descargar aprendizaje", "🎮 Prueba de nivel", "📈 Mi progreso"]

    if st.session_state.get("student_nav") not in student_pages:

        st.session_state["student_nav"] = student_pages[0]

    page = st.sidebar.radio(

        "Menú del estudiante",

        student_pages,

        label_visibility="collapsed",

        key="student_nav"

    )

    st.sidebar.markdown(

        "<div class='saas-help-card'><b>¿Buscas el posttest?</b><br>Selecciona <b>Evaluación</b> y luego elige <b>Posttest</b>.</div>",

        unsafe_allow_html=True,

    )

    st.sidebar.markdown("<div class='saas-section-title'>Configuración académica</div>", unsafe_allow_html=True)

    topic = st.sidebar.selectbox("Área", list(TOPICS.keys()), key="student_topic")

    subtopic = st.sidebar.selectbox("Subtema", TOPICS[topic], key="student_subtopic")

    level = prof.get("level") or "Inicial"

    academic_context = academic_context_from_profile(prof)

    st.sidebar.markdown(

        f"<div class='saas-help-card'><b>Nivel actual:</b> {level}<br><b>Materia:</b> {academic_context.get('subject') or 'Sin materia'}<br><b>Curso:</b> {academic_context.get('cohort') or 'Sin curso'}<br><b>Grupo:</b> {prof.get('research_group') or 'Sin asignar'}</div>",

        unsafe_allow_html=True

    )

    st.sidebar.markdown("<div class='saas-section-title'>Sesión</div>", unsafe_allow_html=True)

    if st.sidebar.button("Cerrar sesión", key="student_logout"):

        st.session_state.clear()

        st.rerun()



    def _select_student_page(target_page):

        if target_page in student_pages:

            st.session_state["student_nav"] = target_page



    with st.expander("☰ Navegación alternativa", expanded=False):

        st.caption(

            "Respaldo de navegación. Úsalo solo si el navegador oculta el panel lateral."

        )

        fallback_columns = st.columns(2)

        for idx, page_name in enumerate(student_pages):

            fallback_columns[idx % 2].button(

                page_name,

                key=f"student_nav_fallback_{idx}",

                use_container_width=True,

                on_click=_select_student_page,

                args=(page_name,),

            )



    return page, topic, subtopic, level



