def render_official_first_login(user, prof):

    sidebar_brand("Estudiante oficial", "Activación de cuenta")

    if st.sidebar.button("Cerrar sesión", key="official_onboarding_logout"):

        st.session_state.clear()

        st.rerun()



    st.markdown(

        "<div class='hero'>" + bunseki_logo_html(

            "Activación de cuenta oficial",

            "Confirma tus datos, acepta el consentimiento y protege tu cuenta antes del pretest",

        ) + "</div>",

        unsafe_allow_html=True,

    )

    st.info(

        f"Cohorte: {prof.get('cohort') or OFFICIAL_COHORT_CODE} · "

        f"Grupo: {prof.get('research_group') or 'Sin asignar'} · "

        "Tus resultados no ingresarán al análisis hasta completar este proceso."

    )



    with st.form("official_first_login_form"):

        st.markdown("### 1. Confirma tus datos")

        c1, c2 = st.columns(2)

        with c1:

            cedula = st.text_input("Cédula / usuario", value=str(prof.get("cedula") or user.get("username") or ""), disabled=True)

            first_names = st.text_input("Nombres", value=str(prof.get("first_names") or ""))

            last_names = st.text_input("Apellidos", value=str(prof.get("last_names") or ""))

            correo = st.text_input("Correo", value=str(prof.get("correo") or ""))

        with c2:

            subject = st.text_input("Materia", value=str(prof.get("subject") or "Cálculo I"))

            course_level = st.text_input("Curso / nivel", value=str(prof.get("course_level") or "1"))

            parallel = st.text_input("Paralelo", value=str(prof.get("parallel") or ""))

            shift = st.selectbox(

                "Jornada",

                ACADEMIC_SHIFTS,

                index=ACADEMIC_SHIFTS.index(normalize_shift(prof.get("shift"))) if normalize_shift(prof.get("shift")) in ACADEMIC_SHIFTS else 0,

            )

            st.text_input("Cohorte de investigación", value=str(prof.get("cohort") or OFFICIAL_COHORT_CODE), disabled=True)

            st.text_input("Grupo de investigación", value=str(prof.get("research_group") or "Sin asignar"), disabled=True)

        st.caption("La cédula, cohorte y grupo son controlados por el docente. Si alguno es incorrecto, no continúes y comunícalo al responsable de la investigación.")



        st.markdown("### 2. Consentimiento informado")

        st.markdown(INFORMED_CONSENT_TEXT)

        consent = st.checkbox(

            "He leído la información y acepto voluntariamente participar en esta investigación.",

            value=False,

        )



        st.markdown("### 3. Cambia la contraseña temporal")

        p1, p2 = st.columns(2)

        new_password = p1.text_input("Nueva contraseña", type="password", help="Mínimo 8 caracteres, con letras, número y símbolo.")

        confirm_password = p2.text_input("Confirmar nueva contraseña", type="password")

        submitted = st.form_submit_button("Confirmar datos y activar cuenta", use_container_width=True)



    if not submitted:

        return



    clean_names = normalize_person_name(first_names)

    clean_surnames = normalize_person_name(last_names)

    clean_email = str(correo or "").strip().lower()

    errors = []

    if not clean_names or not clean_surnames:

        errors.append("Completa nombres y apellidos oficiales.")

    if not re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", clean_email):

        errors.append("Ingresa un correo válido.")

    duplicate_email = fetchone(

        "SELECT user_id FROM profiles WHERE LOWER(COALESCE(correo,''))=%s AND user_id<>%s LIMIT 1",

        (clean_email, user["id"]),

    )

    if duplicate_email:

        errors.append("El correo ya pertenece a otro estudiante.")

    if not subject.strip() or not course_level.strip() or not parallel.strip() or not shift:

        errors.append("Completa materia, curso, paralelo y jornada.")

    if not consent:

        errors.append("Debes aceptar el consentimiento para participar y acceder al pretest oficial.")

    if len(new_password) < 8 or not re.search(r"[A-Za-z]", new_password) or not re.search(r"\d", new_password) or not re.search(r"[^A-Za-z0-9]", new_password):

        errors.append("La nueva contraseña debe tener al menos 8 caracteres, letras, número y símbolo.")

    if new_password != confirm_password:

        errors.append("Las contraseñas no coinciden.")

    if new_password and verify_password(new_password, user.get("password_hash") or ""):

        errors.append("La nueva contraseña debe ser diferente de la temporal.")

    if errors:

        for error in errors:

            st.error(error)

        return



    clean_subject = normalize_academic_text(subject)

    clean_course = normalize_course_level(course_level)

    clean_parallel = normalize_parallel(parallel)

    clean_shift = normalize_shift(shift)

    course_label = build_course_label(clean_course, clean_parallel, clean_shift)

    consent_date = now()

    c = conn()

    c.autocommit = False

    try:

        with c.cursor() as cur:

            cur.execute("""

                UPDATE profiles SET

                    first_names=%s,last_names=%s,correo=%s,subject=%s,course_level=%s,parallel=%s,shift=%s,

                    course=%s,full_name_normalized=%s,profile_completed=1,consentimiento_informado=TRUE,

                    fecha_consentimiento=%s,usar_en_investigacion=TRUE,pretest_estado=COALESCE(NULLIF(pretest_estado,''),'pendiente'),

                    posttest_estado=COALESCE(NULLIF(posttest_estado,''),'pendiente')

                WHERE user_id=%s

            """, (

                clean_names, clean_surnames, clean_email, clean_subject, clean_course, clean_parallel, clean_shift,

                course_label, normalize_spaces(f"{clean_names} {clean_surnames}"), consent_date, user["id"],

            ))

            cur.execute("""

                UPDATE users SET password_hash=%s,password_temporal=FALSE,primer_ingreso=FALSE WHERE id=%s

            """, (hash_password(new_password), user["id"]))

        c.commit()

    except Exception:

        c.rollback()

        raise

    finally:

        c.close()



    st.session_state.user = get_user(user["id"])

    st.session_state["student_nav"] = "🧠 Evaluación"

    st.session_state["assessment_mode"] = "Pretest"

    st.success("Cuenta activada. Serás dirigido al pretest oficial.")

    st.rerun()



def profile_page(user):

    prof=get_profile(user['id'])

    academic_defaults = academic_context_from_profile(prof)

    gps_actual = capture_browser_gps(user['id'], page='Ficha inicial', event_type='app_open', show_status=True)

    st.markdown("<div class='card'><h3>Ficha inicial del estudiante</h3><p class='small'>Registra datos oficiales. La app normaliza nombres, apellidos, materia, curso, paralelo y jornada para la investigación y los reportes.</p></div>", unsafe_allow_html=True)

    with st.form("perfil"):

        c1,c2,c3=st.columns(3)

        data={}

        with c1:

            data['first_names']=st.text_input("Nombres", prof.get('first_names') or '')

            data['last_names']=st.text_input("Apellidos", prof.get('last_names') or '')

            data['birth_date']=str(st.date_input("Fecha de nacimiento", value=birth_date_value(prof.get('birth_date'))))

            data['subject']=academic_selectbox("Materia", ACADEMIC_SUBJECTS, academic_defaults["subject"], "profile_subject")

        with c2:

            data['course_level']=academic_selectbox("Curso / nivel", ACADEMIC_COURSE_LEVELS, academic_defaults["course_level"], "profile_course_level", normalize_course_level)

            data['parallel']=academic_selectbox("Paralelo", ACADEMIC_PARALLELS, academic_defaults["parallel"], "profile_parallel", normalize_parallel)

            data['shift']=academic_selectbox("Jornada", ACADEMIC_SHIFTS, academic_defaults["shift"], "profile_shift", normalize_shift)

            data['teacher']=st.text_input("Docente", prof.get('teacher') or '')

            data['phone']=st.text_input("Número celular", prof.get('phone') or '')

        with c3:

            data['province']=st.text_input("Provincia", prof.get('province') or '')

            data['city']=st.text_input("Ciudad", prof.get('city') or '')

            data['canton']=st.text_input("Cantón", prof.get('canton') or '')

            data['address']=st.text_area("Dirección", prof.get('address') or '')

            auto_lat = (gps_actual or {}).get('lat') if gps_actual else None

            auto_lon = (gps_actual or {}).get('lon') if gps_actual else None

            data['gps_lat']=st.number_input("GPS latitud", value=float(auto_lat if auto_lat is not None else (prof.get('gps_lat') or 0.0)), format="%.6f")

            data['gps_lon']=st.number_input("GPS longitud", value=float(auto_lon if auto_lon is not None else (prof.get('gps_lon') or 0.0)), format="%.6f")

            data['gps_accuracy']=str((gps_actual or {}).get('accuracy') or prof.get('gps_accuracy') or '')

        submitted=st.form_submit_button("Guardar ficha")

        if submitted:

            data['first_names'] = normalize_person_name(data.get('first_names'))

            data['last_names'] = normalize_person_name(data.get('last_names'))

            data['subject'] = normalize_academic_text(data.get('subject'))

            data['course_level'] = normalize_course_level(data.get('course_level'))

            data['parallel'] = normalize_parallel(data.get('parallel'))

            data['shift'] = normalize_shift(data.get('shift'))

            data['cohort'] = build_course_label(data['course_level'], data['parallel'], data['shift'])

            data['course'] = data['cohort']

            data['full_name_normalized'] = normalize_spaces(f"{data['first_names']} {data['last_names']}")

            if not data['first_names'] or not data['last_names']:

                st.warning("Ingresa nombres y apellidos oficiales del estudiante.")

            elif not data['subject'] or not data['course_level'] or not data['parallel'] or not data['shift']:

                st.warning("Completa materia, curso, paralelo y jornada.")

            else:

                data['profile_completed']=1

                update_profile(user['id'], data)

                st.success(f"Ficha guardada: {data['full_name_normalized']} · {data['subject']} · {data['cohort']}")

                st.rerun()

    st.info("GPS automático activado con consentimiento del navegador. En producción debe ejecutarse en HTTPS; en desarrollo funciona en localhost.")



def student_page(user):
    inject_student_layout_cleanup_v2()

    inject_bunseki_frontend_skin()
    prof=get_profile(user['id'])

    if is_official_profile(prof) and not official_profile_ready(user, prof):

        return render_official_first_login(user, prof)

    if not prof.get('profile_completed'): return profile_page(user)

    academic_context = academic_context_from_profile(prof)

    hero_html = (

        "<div class='hero'>"

        + bunseki_logo_html(APP_NAME, 'Bienvenido/a, ' + str(prof.get('first_names') or '') + ' · ' + academic_context.get('subject','Matemáticas universitarias'))

        + f"<div style='margin-top:12px'><span class='badge'>Nivel: {prof.get('level','Inicial')}</span> <span class='badge'>{academic_context.get('cohort','Sin curso')}</span></div>"

        + "</div>"

    )

    st.markdown(hero_html, unsafe_allow_html=True)



    pretest_completed = str(prof.get("pretest_estado") or "pendiente").strip().lower() == "completado"

    quick_assessment_mode = "Posttest" if pretest_completed else "Pretest"

    st.markdown(

        f"<div class='saas-help-card'><b>Acceso rápido a la evaluación</b><br>"

        f"Pulsa el botón para abrir directamente el <b>{quick_assessment_mode}</b>.</div>",

        unsafe_allow_html=True,

    )

    if st.button(

        f"Abrir {quick_assessment_mode}",

        key="student_assessment_shortcut",

        type="primary",

        use_container_width=True,

    ):

        st.session_state["student_nav"] = "🧠 Evaluación"

        st.session_state["assessment_mode"] = quick_assessment_mode



    page, topic, subtopic, level = render_student_sidebar(prof)

    gps_actual = capture_browser_gps(user['id'], page=page, topic=topic, subtopic=subtopic, event_type='app_open', show_status=False)

    rows=interactions(user['id']); user_q=[r for r in rows if r['role']=='user']

    m1,m2,m3,m4=st.columns(4)

    m1.markdown(f"<div class='metric'><b>{len(user_q)}</b><br><span>Consultas</span></div>", unsafe_allow_html=True)

    m2.markdown(f"<div class='metric'><b>{len(set([r['topic'] for r in user_q if r['topic']]))}</b><br><span>Áreas trabajadas</span></div>", unsafe_allow_html=True)

    m3.markdown(f"<div class='metric'><b>{sum(r['tokens_est'] for r in rows)}</b><br><span>Tokens estimados</span></div>", unsafe_allow_html=True)

    m4.markdown(f"<div class='metric'><b>{level}</b><br><span>Nivel actual</span></div>", unsafe_allow_html=True)



    if page == "🧠 Evaluación":

        render_student_adaptive_evaluation(user, prof, topic, subtopic)

        return



    if page == "📈 Mi progreso":

        st.markdown("<div class='card'><h3>📈 Mi progreso académico</h3><p class='small'>Resumen de tus consultas, áreas trabajadas y evolución.</p></div>", unsafe_allow_html=True)

        if user_q:

            df_prog = pd.DataFrame(user_q)

            c1, c2 = st.columns(2)

            c1.plotly_chart(px.histogram(df_prog, x='topic', title='Mis consultas por área'), use_container_width=True)

            c2.plotly_chart(px.histogram(df_prog, x='created_at', title='Mi actividad en el tiempo'), use_container_width=True)

            st.dataframe(df_prog, use_container_width=True, height=320)

        else:

            st.info("Aún no tienes consultas registradas.")

        return



    # Descarga individual para estudiantes: evidencia de lo investigado y aprendido

    st.markdown("### 📘 Descargar mi aprendizaje")
    st.caption("Genera un reporte personal con tus consultas, respuestas recibidas, temas trabajados y trazabilidad académica.")

    exp1, exp2, exp3 = st.columns(3)

    profile_export, report_df_export = build_student_summary(user['id'])

    exp1.download_button(

        "📊 Descargar CSV",

        report_df_export.to_csv(index=False).encode("utf-8-sig"),

        f"mi_aprendizaje_{profile_export.get('username','estudiante')}.csv",

        "text/csv",

        use_container_width=True,

    )

    try:

        exp2.download_button(

            "📝 Descargar Word",

            export_student_docx(user['id']),

            f"mi_aprendizaje_{profile_export.get('username','estudiante')}.docx",

            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",

            use_container_width=True,

        )

    except Exception as e:

        exp2.warning(f"Word no disponible: {e}")

    try:

        exp3.download_button(

            "📄 Descargar PDF",

            export_student_pdf(user['id']),

            f"mi_aprendizaje_{profile_export.get('username','estudiante')}.pdf",

            "application/pdf",

            use_container_width=True,

        )

    except Exception as e:

        exp3.warning(f"PDF no disponible: {e}")



    if page == "📘 Descargar aprendizaje":

        st.markdown("<div class='card'><h3>Vista previa de mi aprendizaje</h3></div>", unsafe_allow_html=True)

        st.dataframe(report_df_export, use_container_width=True, height=360)

        return



    left,right=st.columns([1.5,1])

    with left:

        st.markdown("<div class='card'><h3>💬 Tutor matemático</h3><p class='small'>Sugerencias para preguntar mejor:</p></div>", unsafe_allow_html=True)

        with st.expander("💡 Ver sugerencias de prompt", expanded=False):

            for sug in prompt_suggestions(topic, subtopic, level):

                st.markdown(f"- {sug}")

        for r in rows[-12:]: render_message(r['role'], r['clean_message'] or r['message'])

        q=st.chat_input("Escribe tu pregunta de matemáticas...")

        if q:

            if contains_bad_language(q):

                warning = "Tu consulta contiene lenguaje inapropiado. Reformúlala con respeto para poder ayudarte mejor."

                gps_actual = capture_browser_gps(user['id'], page=page, topic=topic, subtopic=subtopic, event_type='interaction', show_status=False)

                log_location_event(user['id'], 'chat_message_blocked', page=page, topic=topic, subtopic=subtopic, gps=gps_actual)

                log_interaction(user['id'],'user',q,topic,subtopic,level,gps=gps_actual)

                log_interaction(user['id'],'assistant',warning,topic,subtopic,level,"moderacion",0,gps=gps_actual)

                st.rerun()

            gps_actual = capture_browser_gps(user['id'], page=page, topic=topic, subtopic=subtopic, event_type='interaction', show_status=False)

            log_location_event(user['id'], 'chat_message', page=page, topic=topic, subtopic=subtopic, gps=gps_actual)

            log_interaction(user['id'],'user',q,topic,subtopic,level,gps=gps_actual)

            ans,model,ms=ask_ai(q,topic,subtopic,level,prof)

            log_interaction(user['id'],'assistant',ans,topic,subtopic,level,model,ms,gps=gps_actual)

            st.rerun()

    with right:

        st.markdown(

            "<div class='card'><h3>🎯 Configura tu práctica</h3>"

            "<p class='small'>Elige el área que quieres reforzar. En <b>Recomendado</b>, BunsekiChat ajusta la dificultad según tu desempeño; también puedes escoger un nivel manualmente.</p></div>",

            unsafe_allow_html=True,

        )



        practice_topics = list(TOPICS.keys())

        _adaptive_practice_hydrate_session(user)

        default_practice_topic = topic if topic in practice_topics else practice_topics[0]

        topic_state_key = f"adaptive_practice_topic_{user['id']}"

        # BUNSEKI_R8_21_4B_DURABLE_SELECTOR_STATE
        topic_value_key = f"adaptive_practice_topic_value_{user['id']}"
        persisted_topic = st.session_state.get(topic_value_key)
        if (
            st.session_state.get(topic_state_key) not in practice_topics
            and persisted_topic in practice_topics
        ):
            st.session_state[topic_state_key] = persisted_topic

        if st.session_state.get(topic_state_key) not in practice_topics:

            st.session_state[topic_state_key] = default_practice_topic

        practice_topic = st.selectbox(

            "Tema de práctica",

            practice_topics,

            key=topic_state_key,

            help="Puedes cambiar el área de práctica sin modificar tu materia, pretest o nivel oficial.",

        )

        st.session_state[topic_value_key] = practice_topic

        practice_subtopics = list(TOPICS.get(practice_topic, []))
        if not practice_subtopics:
            practice_subtopics = [practice_topic]

        default_practice_subtopic = (
            subtopic
            if subtopic in practice_subtopics
            else practice_subtopics[0]
        )

        subtopic_state_key = (
            f"adaptive_practice_subtopic_{user['id']}_"
            f"{strip_accents(practice_topic).lower()}"
        )

        subtopic_value_key = (
            f"adaptive_practice_subtopic_value_{user['id']}_"
            f"{strip_accents(practice_topic).lower()}"
        )
        persisted_subtopic = st.session_state.get(subtopic_value_key)
        if (
            st.session_state.get(subtopic_state_key) not in practice_subtopics
            and persisted_subtopic in practice_subtopics
        ):
            st.session_state[subtopic_state_key] = persisted_subtopic

        if st.session_state.get(subtopic_state_key) not in practice_subtopics:
            st.session_state[subtopic_state_key] = default_practice_subtopic

        practice_subtopic = st.selectbox(
            "Subtema de práctica",
            practice_subtopics,
            key=subtopic_state_key,
            help=(
                "El subtema permite focalizar la práctica. "
                "En Matemáticas básicas puedes elegir Álgebra elemental, "
                "Trigonometría o Geometría analítica."
            ),
        )

        st.session_state[subtopic_value_key] = practice_subtopic

        subtopic = practice_subtopic



        level_choices = ["Recomendado", *ADAPTIVE_DIFFICULTIES]

        level_state_key = (
            f"adaptive_practice_level_choice_{user['id']}_"
            f"{strip_accents(practice_topic).lower()}_"
            f"{strip_accents(practice_subtopic).lower()}"
        )

        level_value_key = (
            f"adaptive_practice_level_value_{user['id']}_"
            f"{strip_accents(practice_topic).lower()}_"
            f"{strip_accents(practice_subtopic).lower()}"
        )
        persisted_level = st.session_state.get(level_value_key)
        if (
            st.session_state.get(level_state_key) not in level_choices
            and persisted_level in level_choices
        ):
            st.session_state[level_state_key] = persisted_level

        if st.session_state.get(level_state_key) not in level_choices:

            st.session_state[level_state_key] = "Recomendado"

        practice_level_choice = st.selectbox(

            "Nivel de práctica",

            level_choices,

            key=level_state_key,

            help="Recomendado parte de tu nivel actual y se ajusta con tus resultados. Los otros niveles permiten práctica libre.",

                                            format_func=lambda value: PRACTICE_LEVEL_LABELS.get(value, value),
)

        st.session_state[level_value_key] = practice_level_choice
        st.caption(PRACTICE_LEVEL_HELP.get(practice_level_choice, ""))



        practice_key = (
            f"adaptive_practice_state_{user['id']}_"
            f"{strip_accents(practice_topic).lower()}_"
            f"{strip_accents(practice_subtopic).lower()}"
        )

        if practice_key not in st.session_state:

            profile_level = prof.get("level") if prof.get("level") in ADAPTIVE_DIFFICULTIES else "Básico"

            st.session_state[practice_key] = {

                "round": 1,

                "difficulty": normalize_adaptive_difficulty(profile_level),

                "result": None,

                "selection_signature": None,

            }



        practice_state = st.session_state[practice_key]

        selection_signature = f"{practice_topic}|{practice_subtopic}|{practice_level_choice}"

        if practice_state.get("selection_signature") != selection_signature:

            practice_state["round"] = 1

            practice_state["result"] = None
            practice_state["items"] = []
            practice_state["items_signature"] = None

            practice_state["selection_signature"] = selection_signature

            if practice_level_choice != "Recomendado":

                practice_state["difficulty"] = normalize_adaptive_difficulty(practice_level_choice)

            else:

                profile_level = prof.get("level") if prof.get("level") in ADAPTIVE_DIFFICULTIES else "Básico"

                practice_state["difficulty"] = normalize_adaptive_difficulty(profile_level)

            st.session_state[practice_key] = practice_state



        if practice_level_choice == "Recomendado":

            practice_difficulty = normalize_adaptive_difficulty(practice_state.get("difficulty") or "Básico")

            practice_mode_label = "Adaptativo automático"

        else:

            practice_difficulty = normalize_adaptive_difficulty(practice_level_choice)

            practice_state["difficulty"] = practice_difficulty

            st.session_state[practice_key] = practice_state

            practice_mode_label = "Nivel elegido por el estudiante"



        practice_round = int(practice_state.get("round") or 1)

        try:
                        # BUNSEKI_R8_21_3_ACTIVE_PRACTICE_PERSISTENCE
            practice_items_signature = (
                f"{practice_topic}|{practice_subtopic}|"
                f"{practice_difficulty}|{practice_round}"
            )
            cached_practice_items = practice_state.get("items") or []
            cached_items_signature = practice_state.get("items_signature")
            if cached_practice_items and cached_items_signature == practice_items_signature:
                practice_items = cached_practice_items
            else:
                practice_items = adaptive_practice_questions(
                                user["id"],
                                practice_topic,
                                practice_difficulty,
                                n_questions=5,
                                round_no=practice_round,
                                current_subtopic=practice_subtopic,
                            )
                practice_state["items"] = practice_items
                practice_state["items_signature"] = practice_items_signature

                _adaptive_practice_persist_active(
                    user["id"],
                    practice_topic,
                    practice_subtopic,
                    practice_level_choice,
                    practice_difficulty,
                    practice_state,
                )
        except Exception as practice_generation_error:
            st.error(
                "No se pudo preparar una práctica verificada para "
                f"{practice_topic} → {practice_subtopic}: "
                f"{practice_generation_error}"
            )
            st.stop()



        st.markdown(

            "<div class='quiz-card-premium'><h3>🎯 Práctica adaptativa</h3>"

            "<p class='small'>5 preguntas para entrenarte antes de una evaluación. No genera nota, no altera el pretest/posttest y no cambia tu nivel oficial.</p>"

            f"<span class='quiz-topic-chip'>Tema: {practice_topic}</span>"
              f"<span class='quiz-topic-chip'>Subtema: {practice_subtopic}</span>"

            f"<span class='quiz-topic-chip'>Nivel: {practice_difficulty}</span>"

            f"<span class='quiz-topic-chip'>Modo: {practice_mode_label}</span></div>",

            unsafe_allow_html=True,

        )



        practice_attempt_id = (
            st.session_state.get(
                f"adaptive_practice_attempt_id_{user['id']}"
            )
        )

        if not practice_attempt_id:
            restored_active = (
                _adaptive_practice_restore_active(
                    user["id"]
                )
            )

            if restored_active:
                practice_attempt_id = (
                    restored_active.get(
                        "attempt_id"
                    )
                )

                if practice_attempt_id:
                    st.session_state[
                        (
                            "adaptive_practice_"
                            f"attempt_id_{user['id']}"
                        )
                    ] = int(
                        practice_attempt_id
                    )

        practice_batch_key = (
            _adaptive_practice_batch_key(
                user["id"],
                practice_topic,
                practice_subtopic,
                practice_difficulty,
                practice_round,
            )
        )

        practice_saved_answers = (
            _adaptive_practice_load_saved_answers(
                user["id"],
                practice_attempt_id,
            )
        )

        practice_answers = {}

        recovered_answer_count = 0

        autosave_error_key = (
            "adaptive_practice_"
            f"autosave_error_{user['id']}"
        )

        autosave_error = (
            st.session_state.get(
                autosave_error_key
            )
        )

        if autosave_error:
            st.warning(
                "La última respuesta no pudo "
                "guardarse automáticamente. "
                "Puedes volver a seleccionarla."
            )

        for i, item in enumerate(
            practice_items,
            start=1,
        ):
            options = (
                item.get("options")
                or []
            )

            question_key = (
                _adaptive_practice_answer_question_key(
                    item,
                    practice_batch_key,
                )
            )

            widget_key = (
                _adaptive_practice_answer_widget_key(
                    user["id"],
                    practice_round,
                    item,
                    practice_batch_key,
                )
            )

            saved_row = (
                practice_saved_answers.get(
                    question_key
                )
            )

            if (
                widget_key
                not in st.session_state
                and saved_row
            ):
                payload = (
                    saved_row.get(
                        "answer_json"
                    )
                    or {}
                )

                if isinstance(
                    payload,
                    dict,
                ):
                    saved_value = (
                        payload.get(
                            "value"
                        )
                    )

                    if saved_value in options:
                        st.session_state[
                            widget_key
                        ] = saved_value

                        recovered_answer_count += 1

            practice_answers[
                str(i)
            ] = st.radio(
                (
                    f"{i}. "
                    f"[{item.get('bloom_level') or 'Comprender'}] "
                    f"{item.get('question')}"
                ),
                options,
                index=None,
                key=widget_key,
                on_change=(
                    _adaptive_practice_autosave_answer
                ),
                args=(
                    user["id"],
                    practice_attempt_id,
                    item,
                    i,
                    widget_key,
                    practice_batch_key,
                ),
            )

        if recovered_answer_count:
            st.caption(
                "Progreso recuperado: "
                f"{recovered_answer_count}/"
                f"{len(practice_items)} "
                "respuestas guardadas."
            )

        elif any(
            value is not None
            for value in practice_answers.values()
        ):
            st.caption(
                "Guardado automático activo."
            )

        practice_submit = st.button(
            "Revisar práctica",
            key=(
                "adaptive_practice_submit_"
                f"{user['id']}_"
                f"{practice_round}_"
                f"{practice_difficulty}"
            ),
            use_container_width=True,
        )




        if practice_submit:

            unanswered = [key for key, value in practice_answers.items() if value is None]

            if unanswered:

                st.warning("Responde las 5 preguntas para recibir una ruta de práctica adaptada.")

            else:

                reviewed = []

                correct_count = 0

                weak_topics = []

                for i, item in enumerate(practice_items, start=1):

                    answer = practice_answers[str(i)]

                    ok = str(answer).strip() == str(item.get("correct_answer") or "").strip()

                    correct_count += int(ok)

                    if not ok:

                        weak_topics.append(item.get("topic") or topic)

                    reviewed.append({

                        "question": item.get("question"),

                        "answer": answer,

                        "correct_answer": item.get("correct_answer"),

                        "explanation": item.get("explanation"),

                        "topic": item.get("topic") or practice_topic,
                        "subtopic": item.get("subtopic") or practice_subtopic,

                        "is_correct": ok,

                    })
                    record_ai_practice_bank_result(
                        user["id"],
                        item,
                        answer,
                        ok,
                        practice_topic,
                        practice_subtopic,
                        practice_difficulty,
                        attempt_key=(
                            f"ai_practice|{user['id']}|{practice_topic}|{practice_subtopic}|"
                            f"{practice_difficulty}|{practice_round}|{item.get('item_code') or stable_item_code(item.get('question', ''))}"
                        ),
                    )

                next_difficulty, reason = adaptive_practice_next_difficulty(

                    practice_difficulty,

                    correct_count,

                    len(practice_items),

                )

                practice_state["result"] = {

                    "correct": correct_count,

                    "total": len(practice_items),

                    "reviewed": reviewed,

                    "weak_topics": list(dict.fromkeys(weak_topics)),

                    "next_difficulty": next_difficulty,

                    "reason": reason,

                }

                st.session_state[practice_key] = practice_state

                _adaptive_practice_persist_active(
                    user["id"],
                    practice_topic,
                    practice_subtopic,
                    practice_level_choice,
                    practice_difficulty,
                    practice_state,
                )

                log_location_event(

                    user["id"],

                    "adaptive_practice_reviewed",

                    page=page,

                    topic=practice_topic,

                    subtopic=practice_subtopic,

                    gps=None,

                )

                st.rerun()



        practice_result = practice_state.get("result")

        if practice_result:

            st.success(

                f"Práctica revisada: {practice_result['correct']} de {practice_result['total']} respuestas correctas. "

                "Este dato orienta la siguiente práctica y no es una calificación."

            )

            st.info(

                f"Siguiente práctica recomendada: {practice_result['next_difficulty']}. "

                f"{practice_result['reason']}"

            )

            if practice_level_choice != "Recomendado":

                st.caption(

                    f"Estás en modo manual ({practice_difficulty}). La recomendación no cambia tu selección; puedes modificar el nivel arriba cuando quieras."

                )

            for reviewed in practice_result.get("reviewed", []):

                icon = "✅" if reviewed.get("is_correct") else "❌"

                st.markdown(

                    f"**{icon} {reviewed.get('question')}**  \n"

                    f"Tu respuesta: {reviewed.get('answer')}  \n"

                    f"Respuesta esperada: {reviewed.get('correct_answer')}  \n"

                    f"{reviewed.get('explanation') or ''}"

                )

            st.markdown("**Prompts recomendados para elevar tu nivel**")

            for prompt_text in adaptive_learning_prompts(
                    [practice_subtopic],
                    practice_result.get("next_difficulty"),
                    practice_subtopic,
                ):

                st.code(prompt_text, language=None)



            if practice_level_choice == "Recomendado":

                next_button_label = f"Nueva práctica adaptada · {practice_result['next_difficulty']}"

            else:

                next_button_label = f"Nueva práctica · {practice_difficulty} (nivel elegido)"



            if st.button(

                next_button_label,

                key=f"next_practice_{user['id']}_{practice_round}",

                use_container_width=True,

            ):

                practice_state["round"] = practice_round + 1
                practice_state["items"] = []
                practice_state["items_signature"] = None

                if practice_level_choice == "Recomendado":

                    practice_state["difficulty"] = practice_result["next_difficulty"]

                else:

                    practice_state["difficulty"] = practice_difficulty

                practice_state["result"] = None

                st.session_state[practice_key] = practice_state

                _adaptive_practice_persist_active(
                    user["id"],
                    practice_topic,
                    practice_subtopic,
                    practice_level_choice,
                    practice_difficulty,
                    practice_state,
                )

                st.rerun()



        df = pd.DataFrame(user_q)

        if not df.empty:

            fig = px.histogram(df, x='topic', title='Consultas por área')

            st.plotly_chart(fig, use_container_width=True)





def render_teacher_gps_heatmap(logs: pd.DataFrame, filtered_students: pd.DataFrame | None = None):

    """Mapa de calor docente basado en las coordenadas GPS guardadas en interactions.

    Usa únicamente registros con gps_lat/gps_lon válidos y permite respetar los filtros

    académicos activos del dashboard.

    """

    st.markdown('### 🗺️ Mapa de calor GPS por interacciones')
    st.caption('Visualiza la concentración geográfica de uso de BunsekiChat según las coordenadas guardadas en cada interacción.')



    if logs is None or logs.empty:

        st.info("Aún no existen interacciones para generar el mapa de calor GPS.")

        return



    gps_df = logs.copy()



    # Respeta los filtros de curso/docente/nivel aplicados al dashboard.

    if filtered_students is not None and not filtered_students.empty and "id" in filtered_students.columns:

        allowed_ids = set(filtered_students["id"].dropna().astype(int).tolist())

        gps_df = gps_df[gps_df["user_id"].isin(allowed_ids)]



    # El mapa se construye desde la tabla interactions, no desde el registro manual del perfil.

    if "role" in gps_df.columns:

        gps_df = gps_df[gps_df["role"].astype(str).str.lower().eq("user")]



    required_cols = {"gps_lat", "gps_lon"}

    if not required_cols.issubset(set(gps_df.columns)):

        st.warning("La tabla interactions todavía no tiene columnas gps_lat/gps_lon disponibles.")

        return



    gps_df["gps_lat"] = pd.to_numeric(gps_df["gps_lat"], errors="coerce")

    gps_df["gps_lon"] = pd.to_numeric(gps_df["gps_lon"], errors="coerce")

    gps_df = gps_df.dropna(subset=["gps_lat", "gps_lon"])

    gps_df = gps_df[gps_df["gps_lat"].between(-90, 90) & gps_df["gps_lon"].between(-180, 180)]



    if gps_df.empty:

        st.warning("No hay interacciones con GPS válido. Verifica que el navegador haya autorizado la ubicación y que se esté ejecutando en localhost o HTTPS.")

        return



    # Columnas auxiliares para un hover docente más claro.

    gps_df["estudiante"] = gps_df.get("username", "Sin usuario")

    if "first_names" in gps_df.columns or "last_names" in gps_df.columns:

        gps_df["nombre"] = (

            gps_df.get("first_names", "").fillna("").astype(str).str.strip()

            + " "

            + gps_df.get("last_names", "").fillna("").astype(str).str.strip()

        ).str.strip()

        gps_df.loc[gps_df["nombre"].eq(""), "nombre"] = gps_df["estudiante"]

    else:

        gps_df["nombre"] = gps_df["estudiante"]



    center_lat = float(gps_df["gps_lat"].mean())

    center_lon = float(gps_df["gps_lon"].mean())

    zoom = 11 if len(gps_df) <= 10 else 10



    h1, h2, h3 = st.columns(3)

    h1.markdown(f"<div class='metric'><b>{len(gps_df)}</b><br><span>Interacciones con GPS</span></div>", unsafe_allow_html=True)

    h2.markdown(f"<div class='metric'><b>{gps_df['user_id'].nunique()}</b><br><span>Estudiantes geolocalizados</span></div>", unsafe_allow_html=True)

    last_gps = gps_df["created_at"].max() if "created_at" in gps_df.columns else "N/D"

    h3.markdown(f"<div class='metric'><b>{last_gps}</b><br><span>Último GPS registrado</span></div>", unsafe_allow_html=True)



    fig_heat = px.density_mapbox(

        gps_df,

        lat="gps_lat",

        lon="gps_lon",

        radius=28,

        center={"lat": center_lat, "lon": center_lon},

        zoom=zoom,

        mapbox_style="open-street-map",

        hover_name="nombre",

        hover_data={

            "estudiante": True,

            "topic": True,

            "subtopic": True,

            "created_at": True,

            "gps_lat": ":.6f",

            "gps_lon": ":.6f",

            "gps_accuracy": True if "gps_accuracy" in gps_df.columns else False,

        },

        title="Mapa de calor de uso por coordenadas GPS de interacciones",

    )

    fig_heat.update_layout(margin={"r":0,"t":45,"l":0,"b":0}, height=560)

    st.plotly_chart(fig_heat, use_container_width=True)



    fig_points = px.scatter_mapbox(

        gps_df,

        lat="gps_lat",

        lon="gps_lon",

        color="topic" if "topic" in gps_df.columns else None,

        hover_name="nombre",

        hover_data={

            "estudiante": True,

            "topic": True if "topic" in gps_df.columns else False,

            "subtopic": True if "subtopic" in gps_df.columns else False,

            "created_at": True if "created_at" in gps_df.columns else False,

            "gps_lat": ":.6f",

            "gps_lon": ":.6f",

        },

        center={"lat": center_lat, "lon": center_lon},

        zoom=zoom,

        mapbox_style="open-street-map",

        title="Puntos GPS individuales por interacción",

    )

    fig_points.update_layout(margin={"r":0,"t":45,"l":0,"b":0}, height=500)

    with st.expander("Ver puntos GPS individuales"):

        st.plotly_chart(fig_points, use_container_width=True)

        cols = [c for c in ["id", "user_id", "username", "first_names", "last_names", "course", "teacher", "topic", "subtopic", "created_at", "gps_lat", "gps_lon", "gps_accuracy", "gps_source"] if c in gps_df.columns]

        st.dataframe(gps_df[cols].sort_values("created_at", ascending=False) if "created_at" in cols else gps_df[cols], use_container_width=True, height=280)

        st.download_button(

            "📍 Descargar interacciones con GPS",

        gps_df[cols].to_csv(index=False).encode("utf-8-sig"),

            "interacciones_gps_mapa_calor.csv",

            "text/csv",

            use_container_width=True,

        )





def get_research_results():

    return fetchall("""

        SELECT

            aq.id, aq.user_id, aq.quiz_type, aq.title, aq.subject,

            aq.course_level, aq.parallel, aq.shift, aq.cohort,

            aq.score, aq.passed, aq.question_count, aq.status,

            aq.version_code, aq.dimension_scores_json, aq.diagnosis_json,

            aq.cognitive_profile, aq.learning_plan_json, aq.total_time_seconds,

            aq.created_at, aq.completed_at, aq.research_title, aq.random_seed,

            u.username,

            p.first_names, p.last_names, p.full_name_normalized,

            p.cedula, p.correo, COALESCE(NULLIF(p.estado_dato,''), 'piloto') AS estado_dato,

            COALESCE(p.usar_en_investigacion,FALSE) AS usar_en_investigacion,

            COALESCE(p.consentimiento_informado,FALSE) AS consentimiento_informado,

            p.fecha_consentimiento, p.pretest_estado, p.posttest_estado,

            COALESCE(NULLIF(p.research_group,''), 'Sin asignar') AS research_group,

            COALESCE(aq.subject, p.subject) AS profile_subject,

            COALESCE(aq.course_level, p.course_level) AS profile_course_level,

            COALESCE(aq.parallel, p.parallel) AS profile_parallel,

            COALESCE(aq.shift, p.shift) AS profile_shift,

            COALESCE(aq.cohort, p.cohort, p.course) AS profile_cohort

        FROM adaptive_quizzes aq

        JOIN users u ON u.id=aq.user_id

        LEFT JOIN profiles p ON p.user_id=aq.user_id

        WHERE COALESCE(aq.quiz_type,'adaptive') IN ('pretest','posttest')

        ORDER BY aq.id DESC

    """)





def get_research_students():

    return fetchall("""

        SELECT u.id AS user_id, u.username, p.first_names, p.last_names,

               p.full_name_normalized, p.subject, p.course_level, p.parallel,

               p.shift, p.cohort, p.course, p.cedula, p.correo,

               COALESCE(NULLIF(p.estado_dato,''), 'piloto') AS estado_dato,

               COALESCE(p.usar_en_investigacion,FALSE) AS usar_en_investigacion,

               COALESCE(p.consentimiento_informado,FALSE) AS consentimiento_informado,

               p.fecha_consentimiento,p.pretest_estado,p.posttest_estado,

               COALESCE(NULLIF(p.research_group,''), 'Sin asignar') AS research_group

        FROM users u

        JOIN profiles p ON p.user_id=u.id

        WHERE LOWER(COALESCE(u.role,'student'))='student'

        ORDER BY p.last_names, p.first_names, u.username

    """)





def get_research_item_responses():

    return fetchall("""

        SELECT q.id, q.quiz_id, aq.user_id, aq.quiz_type, aq.version_code,

               aq.subject, aq.course_level, aq.parallel, aq.shift, aq.cohort,

               COALESCE(NULLIF(p.research_group,''), 'Sin asignar') AS research_group,

               COALESCE(NULLIF(q.item_code,''), 'LEGACY-' || q.id::text) AS item_code,

               q.question, q.position, q.dimension, q.difficulty_level, q.bloom_level,

               q.user_answer, q.is_correct, q.response_time_seconds, q.conceptual_error

        FROM adaptive_questions q

        JOIN adaptive_quizzes aq ON aq.id=q.quiz_id

        LEFT JOIN profiles p ON p.user_id=aq.user_id

        WHERE COALESCE(aq.quiz_type,'adaptive') IN ('pretest','posttest')

          AND aq.status='completed'

        ORDER BY q.quiz_id, q.position, q.id

    """)





def get_research_learning_events():

    return fetchall("""

        SELECT rle.*, COALESCE(NULLIF(p.research_group,''), 'Sin asignar') AS research_group

        FROM research_learning_events rle

        LEFT JOIN profiles p ON p.user_id=rle.user_id

        ORDER BY rle.id

    """)





def get_research_interactions():

    return fetchall("""

        SELECT i.id, i.user_id, i.role, i.topic, i.subtopic, i.latency_ms, i.created_at

        FROM interactions i

        WHERE EXISTS (

            SELECT 1 FROM adaptive_quizzes aq

            WHERE aq.user_id=i.user_id AND COALESCE(aq.quiz_type,'adaptive') IN ('pretest','posttest')

        )

        ORDER BY i.user_id, i.created_at, i.id

    """)





def get_research_session_events():

    return fetchall("""

        SELECT le.id, le.user_id, le.event_type, le.page, le.created_at

        FROM location_events le

        WHERE le.event_type='app_open'

          AND EXISTS (

              SELECT 1 FROM adaptive_quizzes aq

              WHERE aq.user_id=le.user_id AND COALESCE(aq.quiz_type,'adaptive') IN ('pretest','posttest')

          )

        ORDER BY le.user_id, le.created_at, le.id

    """)





def get_research_exercise_attempts():

    return fetchall("""

        SELECT rea.*, u.username, p.first_names, p.last_names, p.cohort

        FROM research_exercise_attempts rea

        JOIN users u ON u.id=rea.user_id

        LEFT JOIN profiles p ON p.user_id=rea.user_id

        ORDER BY rea.id DESC

    """)





def get_research_survey_responses():

    return fetchall("""

        SELECT rsr.*, u.username, p.first_names, p.last_names, p.cohort

        FROM research_survey_responses rsr

        JOIN users u ON u.id=rsr.user_id

        LEFT JOIN profiles p ON p.user_id=rsr.user_id

        ORDER BY rsr.id DESC

    """)





def build_research_export_bundle(student_df, result_df, item_df, event_df, interaction_df, exercise_df, session_df=None):

    students = student_df.copy() if student_df is not None else pd.DataFrame()

    results = result_df.copy() if result_df is not None else pd.DataFrame()

    items = item_df.copy() if item_df is not None else pd.DataFrame()

    events = event_df.copy() if event_df is not None else pd.DataFrame()

    interactions_df = interaction_df.copy() if interaction_df is not None else pd.DataFrame()

    exercises = exercise_df.copy() if exercise_df is not None else pd.DataFrame()

    sessions = session_df.copy() if session_df is not None else pd.DataFrame()

    if students.empty:

        empty = pd.DataFrame()

        return {"summary": empty, "items": empty, "events": empty, "exercises": empty}



    for frame, columns in [

        (results, ["user_id", "score", "total_time_seconds"]),

        (items, ["user_id", "response_time_seconds"]),

        (events, ["user_id", "duration_seconds"]),

        (interactions_df, ["user_id"]),

        (exercises, ["user_id"]),

        (sessions, ["user_id"]),

    ]:

        for column in columns:

            if column in frame.columns:

                frame[column] = pd.to_numeric(frame[column], errors="coerce")



    completed = results.copy()

    if not completed.empty:

        completed = completed[completed.get("status", "").astype(str).eq("completed")]

        completed = completed.sort_values([column for column in ["user_id", "quiz_type", "id"] if column in completed.columns])



    def latest_quiz(user_results, quiz_type):

        if user_results.empty or "quiz_type" not in user_results.columns:

            return {}

        subset = user_results[user_results["quiz_type"].astype(str).eq(quiz_type)]

        return subset.iloc[-1].to_dict() if not subset.empty else {}



    def frame_for_user(frame, user_id):

        if frame.empty or "user_id" not in frame.columns:

            return frame.iloc[0:0].copy()

        return frame[pd.to_numeric(frame["user_id"], errors="coerce").eq(int(user_id))].copy()



    summary_rows = []

    students = students.sort_values([column for column in ["last_names", "first_names", "user_id"] if column in students.columns])

    for _, student in students.drop_duplicates("user_id", keep="last").iterrows():

        user_id = int(student["user_id"])

        user_results = frame_for_user(completed, user_id)

        user_items = frame_for_user(items, user_id)

        user_events = frame_for_user(events, user_id)

        user_interactions = frame_for_user(interactions_df, user_id)

        user_exercises = frame_for_user(exercises, user_id)

        user_sessions = frame_for_user(sessions, user_id)

        pretest = latest_quiz(user_results, "pretest")

        posttest = latest_quiz(user_results, "posttest")

        pre_score = pd.to_numeric(pretest.get("score"), errors="coerce")

        post_score = pd.to_numeric(posttest.get("score"), errors="coerce")

        gain = post_score - pre_score if pd.notna(pre_score) and pd.notna(post_score) else None



        session_dates = set()

        for frame in [user_results, user_events, user_interactions, user_exercises]:

            if "created_at" in frame.columns:

                session_dates.update(str(value)[:10] for value in frame["created_at"].dropna() if str(value).strip())

        answered = user_items[user_items.get("user_answer", pd.Series(index=user_items.index, dtype=str)).fillna("").astype(str).str.strip().ne("")]

        correct_count = int(answered.get("is_correct", pd.Series(index=answered.index, dtype=bool)).fillna(False).astype(bool).sum())

        feedback_count = int(user_exercises.get("feedback", pd.Series(index=user_exercises.index, dtype=str)).fillna("").astype(str).str.strip().ne("").sum())

        bloom_counts = answered.get("bloom_level", pd.Series(dtype=str)).fillna("Sin clasificar").astype(str).value_counts().to_dict()

        difficulty_counts = answered.get("difficulty_level", pd.Series(dtype=str)).fillna("Sin clasificar").astype(str).value_counts().to_dict()

        quiz_seconds = pd.to_numeric(user_results.get("total_time_seconds", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()

        event_seconds = pd.to_numeric(user_events.get("duration_seconds", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()

        dates = [value for value in [pretest.get("completed_at"), posttest.get("completed_at")] if value]

        summary_rows.append({

            "user_id": user_id,

            "cedula": student.get("cedula"),

            "nombres": student.get("first_names"),

            "apellidos": student.get("last_names"),

            "correo": student.get("correo"),

            "materia": student.get("subject"),

            "curso": student.get("course_level"),

            "paralelo": student.get("parallel"),

            "jornada": student.get("shift"),

            "grupo_investigacion": student.get("research_group"),

            "cohorte": student.get("cohort"),

            "estado_dato": student.get("estado_dato"),

            "usar_en_investigacion": student.get("usar_en_investigacion"),

            "consentimiento_informado": student.get("consentimiento_informado"),

            "fecha_consentimiento": student.get("fecha_consentimiento"),

            "pretest_estado": student.get("pretest_estado"),

            "posttest_estado": student.get("posttest_estado"),

            "pretest": None if pd.isna(pre_score) else float(pre_score),

            "posttest": None if pd.isna(post_score) else float(post_score),

            "ganancia_aprendizaje": None if gain is None or pd.isna(gain) else float(gain),

            "tiempo_uso_segundos": float(quiz_seconds + event_seconds),

            "numero_sesiones": len(user_sessions) if not user_sessions.empty else len(session_dates),

            "preguntas_respondidas": len(answered),

            "aciertos": correct_count,

            "errores": int(len(answered) - correct_count),

            "nivel_bloom": json.dumps(bloom_counts, ensure_ascii=False),

            "dificultad": json.dumps(difficulty_counts, ensure_ascii=False),

            "uso_retroalimentacion": feedback_count,

            "fecha_pretest": pretest.get("completed_at"),

            "fecha_posttest": posttest.get("completed_at"),

            "fecha_aplicacion": max(dates) if dates else None,

        })



    summary = pd.DataFrame(summary_rows)

    identity_columns = ["user_id", "cedula", "first_names", "last_names", "cohort", "research_group", "estado_dato"]

    identity = students[[column for column in identity_columns if column in students.columns]].drop_duplicates("user_id")



    def attach_identity(frame):

        if frame.empty or "user_id" not in frame.columns:

            return frame

        clean = frame.drop(columns=[column for column in identity.columns if column != "user_id" and column in frame.columns], errors="ignore")

        return clean.merge(identity, on="user_id", how="left")



    return {

        "summary": summary,

        "items": attach_identity(items),

        "events": attach_identity(events),

        "exercises": attach_identity(exercises),

        "sessions": attach_identity(sessions),

    }





def research_export_excel(bundle):

    output = BytesIO()

    with pd.ExcelWriter(output, engine="openpyxl") as writer:

        sheet_map = {

            "summary": "Resumen_estudiantes",

            "items": "Respuestas_items",

            "events": "Eventos_aprendizaje",

            "exercises": "Ejercicios_feedback",

            "sessions": "Sesiones",

        }

        for key, sheet_name in sheet_map.items():

            frame = bundle.get(key, pd.DataFrame())

            frame.to_excel(writer, sheet_name=sheet_name, index=False)

            worksheet = writer.book[sheet_name]

            worksheet.freeze_panes = "A2"

            worksheet.auto_filter.ref = worksheet.dimensions

    return output.getvalue()





