def admin_reset_student_password(admin_user, target_user_id, new_password, force_change=False):
    admin_role = str((admin_user or {}).get("role") or "").strip().lower()
    if admin_role != "admin":
        raise ValueError("Solo un administrador puede restablecer contraseñas.")

    target = get_user(int(target_user_id))
    if not target or str(target.get("role") or "").strip().lower() != "student":
        raise ValueError("El usuario seleccionado no es un estudiante válido.")

    if not target.get("active"):
        raise ValueError("El estudiante seleccionado está inactivo.")

    password = str(new_password or "")
    if (
        len(password) < 8
        or not re.search(r"[A-Za-z]", password)
        or not re.search(r"\d", password)
        or not re.search(r"[^A-Za-z0-9]", password)
    ):
        raise ValueError(
            "La contraseña debe tener al menos 8 caracteres, "
            "incluyendo letras, número y símbolo."
        )

    update_user(
        int(target_user_id),
        {
            "password_hash": hash_password(password),
            "password_temporal": bool(force_change),
            "primer_ingreso": bool(force_change),
            "last_login": None,
        },
    )
    return get_user(int(target_user_id))


def render_admin_password_reset(admin_user):
    st.markdown("### Restablecer contraseña de estudiante")
    st.caption(
        "El administrador asigna una contraseña nueva. "
        "La contraseña anterior nunca se muestra ni se puede recuperar."
    )

    students = fetchall(
        "SELECT u.id,u.username,u.active,p.first_names,p.last_names "
        "FROM users u "
        "LEFT JOIN profiles p ON p.user_id=u.id "
        "WHERE LOWER(COALESCE(u.role,'student'))='student' "
        "ORDER BY u.username"
    )

    if not students:
        st.info("No hay estudiantes registrados.")
        return

    by_id = {int(row["id"]): row for row in students}

    def _student_label(user_id):
        row = by_id[int(user_id)]
        full_name = normalize_spaces(
            f"{row.get('first_names') or ''} {row.get('last_names') or ''}"
        )
        username = row.get("username") or f"usuario_{user_id}"
        state = "activo" if row.get("active") else "inactivo"
        return f"{full_name or username} · {username} · ID {user_id} · {state}"

    selected_id = st.selectbox(
        "Estudiante",
        list(by_id),
        format_func=_student_label,
        key="admin_password_reset_student",
    )

    new_password = st.text_input(
        "Nueva contraseña",
        type="password",
        key="admin_password_reset_new",
        help="Mínimo 8 caracteres, con letras, número y símbolo.",
    )
    confirm_password = st.text_input(
        "Confirmar nueva contraseña",
        type="password",
        key="admin_password_reset_confirm",
    )

    force_change = st.checkbox(
        "Forzar cambio de contraseña en el próximo ingreso",
        value=False,
        key="admin_password_reset_force_change",
        help=(
            "Para la cuenta de prueba puede dejarlo desmarcado. "
            "Si se activa, el estudiante pasará por el flujo de primer ingreso."
        ),
    )

    confirmation = st.text_input(
        "Confirmación de seguridad",
        key="admin_password_reset_confirmation",
        placeholder="Escriba RESTABLECER",
    )

    if st.button(
        "Restablecer contraseña",
        key="admin_password_reset_button",
        use_container_width=True,
    ):
        if new_password != confirm_password:
            st.error("Las contraseñas no coinciden.")
            return

        if confirmation.strip().upper() != "RESTABLECER":
            st.error("Escriba RESTABLECER para confirmar la operación.")
            return

        try:
            updated = admin_reset_student_password(
                admin_user,
                int(selected_id),
                new_password,
                force_change=force_change,
            )
            st.success(
                f"Contraseña restablecida para {updated.get('username')}. "
                "La contraseña no se mostrará nuevamente."
            )
        except ValueError as exc:
            st.error(str(exc))



