def _science_dt(series):
    return pd.to_datetime(series, errors="coerce", utc=True)


def _science_risk_band(value):
    score = float(value or 0)
    if score >= 60:
        return "Alta"
    if score >= 35:
        return "Media"
    return "Baja"


def _science_recommendation(row):
    days = float(row.get("Días sin actividad") or 0)
    interactions = float(row.get("Interacciones 14d") or 0)
    attempts = float(row.get("Prácticas 30d") or 0)
    accuracy = row.get("Precisión 30d (%)")

    if days >= 14:
        return "Contacto de reenganche y plan breve de retorno"
    if pd.notna(accuracy) and attempts >= 5 and float(accuracy) < 60:
        return "Refuerzo focalizado en temas de menor precisión"
    if interactions <= 2:
        return "Actividad guiada corta y seguimiento en 7 días"
    return "Seguimiento ordinario"


def render_scientific_learning_analytics_dashboard():
    st.markdown("## 🧭 Learning Analytics Science Lab")
    st.caption(
        "Analítica educativa para acompañamiento docente. Las alertas son heurísticas "
        "transparentes: orientan intervención temprana y no sustituyen el juicio académico."
    )

    students = pd.DataFrame(
        fetchall(
            """
            SELECT
                u.id AS user_id,
                u.username,
                u.last_login,
                u.active,
                p.first_names,
                p.last_names,
                p.subject,
                p.course,
                p.course_level,
                p.parallel,
                p.shift,
                p.level
            FROM users u
            LEFT JOIN profiles p ON p.user_id=u.id
            WHERE LOWER(COALESCE(u.role,'student'))='student'
              AND COALESCE(u.active,TRUE)=TRUE
            ORDER BY u.username
            """
        )
    )

    if students.empty:
        st.info("No hay estudiantes activos para construir indicadores.")
        return

    for col in ["subject", "course_level", "parallel", "shift"]:
        if col not in students.columns:
            students[col] = None

    f1, f2, f3, f4 = st.columns(4)

    def _filter_options(column):
        values = sorted(
            {
                str(v).strip()
                for v in students[column].dropna().tolist()
                if str(v).strip()
            }
        )
        return ["Todos"] + values

    subject = f1.selectbox(
        "Materia",
        _filter_options("subject"),
        key="science_kpi_subject_v2",
    )
    course_level = f2.selectbox(
        "Nivel/curso",
        _filter_options("course_level"),
        key="science_kpi_level_v2",
    )
    parallel = f3.selectbox(
        "Paralelo",
        _filter_options("parallel"),
        key="science_kpi_parallel_v2",
    )
    shift = f4.selectbox(
        "Jornada",
        _filter_options("shift"),
        key="science_kpi_shift_v2",
    )

    filtered = students.copy()
    for column, value in {
        "subject": subject,
        "course_level": course_level,
        "parallel": parallel,
        "shift": shift,
    }.items():
        if value != "Todos":
            filtered = filtered[
                filtered[column].fillna("").astype(str).str.strip() == value
            ]

    if filtered.empty:
        st.warning("No hay estudiantes que coincidan con los filtros seleccionados.")
        return

    selected_ids = set(filtered["user_id"].dropna().astype(int).tolist())

    interactions = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, topic, subtopic, level, latency_ms, created_at
            FROM interactions
            """
        )
    )
    practice = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, topic, subtopic, difficulty_level, is_correct, created_at
            FROM research_exercise_attempts
            """
        )
    )
    adaptive = pd.DataFrame(
        fetchall(
            """
            SELECT topic, subtopic, difficulty_level, is_correct,
                   response_time_seconds, attempts
            FROM adaptive_questions
            """
        )
    )
    assessment_attempts = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, teacher_assessment_id, status, resume_count,
                   created_at, updated_at
            FROM assessment_attempts
            WHERE teacher_assessment_id IS NOT NULL
            """
        )
    )
    location_events = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, created_at
            FROM location_events
            """
        )
    )

    now_utc = pd.Timestamp.now(tz="UTC")
    cut_14 = now_utc - pd.Timedelta(days=14)
    cut_28 = now_utc - pd.Timedelta(days=28)
    cut_30 = now_utc - pd.Timedelta(days=30)
    cut_56 = now_utc - pd.Timedelta(days=56)

    if interactions.empty:
        interactions = pd.DataFrame(
            columns=["user_id", "topic", "subtopic", "created_at", "created_dt"]
        )
    else:
        interactions = interactions[
            interactions["user_id"].isin(selected_ids)
        ].copy()
        interactions["created_dt"] = _science_dt(interactions["created_at"])

    if practice.empty:
        practice = pd.DataFrame(
            columns=[
                "user_id", "topic", "subtopic", "is_correct",
                "created_at", "created_dt", "correct_num"
            ]
        )
    else:
        practice = practice[
            practice["user_id"].isin(selected_ids)
        ].copy()
        practice["created_dt"] = _science_dt(practice["created_at"])
        practice["correct_num"] = practice["is_correct"].fillna(False).astype(int)

    if assessment_attempts.empty:
        assessment_attempts = pd.DataFrame(
            columns=[
                "user_id", "status", "resume_count", "created_dt", "updated_dt"
            ]
        )
    else:
        assessment_attempts = assessment_attempts[
            assessment_attempts["user_id"].isin(selected_ids)
        ].copy()
        assessment_attempts["created_dt"] = _science_dt(
            assessment_attempts["created_at"]
        )
        assessment_attempts["updated_dt"] = _science_dt(
            assessment_attempts["updated_at"]
        )

    if location_events.empty:
        location_events = pd.DataFrame(columns=["user_id", "created_dt"])
    else:
        location_events = location_events[
            location_events["user_id"].isin(selected_ids)
        ].copy()
        location_events["created_dt"] = _science_dt(location_events["created_at"])

    filtered["last_login_dt"] = _science_dt(filtered["last_login"])

    recent14 = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_14)
    ]
    prev14 = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_28)
        & (interactions["created_dt"] < cut_14)
    ]
    practice30 = practice[
        practice["created_dt"].notna()
        & (practice["created_dt"] >= cut_30)
    ]

    active_ids = set(recent14["user_id"].dropna().astype(int).tolist())
    active_ids.update(practice30["user_id"].dropna().astype(int).tolist())

    if not assessment_attempts.empty:
        recent_assessment = assessment_attempts[
            assessment_attempts["updated_dt"].notna()
            & (assessment_attempts["updated_dt"] >= cut_14)
        ]
        active_ids.update(
            recent_assessment["user_id"].dropna().astype(int).tolist()
        )

    overall_accuracy = (
        float(practice30["correct_num"].mean() * 100)
        if not practice30.empty
        else float("nan")
    )

    interactions_14 = int(len(recent14))
    interactions_prev = int(len(prev14))
    momentum_delta = interactions_14 - interactions_prev

    gps_recent_ids = set()
    if not location_events.empty:
        gps_recent_ids = set(
            location_events.loc[
                location_events["created_dt"].notna()
                & (location_events["created_dt"] >= cut_30),
                "user_id",
            ]
            .dropna()
            .astype(int)
            .tolist()
        )
    gps_coverage = 100.0 * len(gps_recent_ids) / max(1, len(selected_ids))

    base = filtered[
        [
            "user_id", "username", "first_names", "last_names",
            "last_login_dt", "subject", "course_level", "parallel", "shift"
        ]
    ].copy()

    base["Estudiante"] = (
        base["first_names"].fillna("").astype(str).str.strip()
        + " "
        + base["last_names"].fillna("").astype(str).str.strip()
    ).str.strip()
    base["Estudiante"] = base.apply(
        lambda row: row["Estudiante"] or str(row["username"]),
        axis=1,
    )

    if not interactions.empty:
        last_interaction = interactions.groupby("user_id")["created_dt"].max()
        count14 = recent14.groupby("user_id").size()
        count_prev14 = prev14.groupby("user_id").size()
    else:
        last_interaction = pd.Series(dtype="datetime64[ns, UTC]")
        count14 = pd.Series(dtype="int64")
        count_prev14 = pd.Series(dtype="int64")

    if not practice.empty:
        last_practice = practice.groupby("user_id")["created_dt"].max()
    else:
        last_practice = pd.Series(dtype="datetime64[ns, UTC]")

    if not practice30.empty:
        practice_count30 = practice30.groupby("user_id").size()
        practice_accuracy30 = (
            practice30.groupby("user_id")["correct_num"].mean() * 100
        )
    else:
        practice_count30 = pd.Series(dtype="int64")
        practice_accuracy30 = pd.Series(dtype="float64")

    completed_statuses = {
        "completed", "submitted", "graded", "finished", "complete"
    }

    if not assessment_attempts.empty:
        last_assessment = assessment_attempts.groupby("user_id")["updated_dt"].max()
        resume_sum = (
            assessment_attempts.groupby("user_id")["resume_count"]
            .sum(min_count=1)
            .fillna(0)
        )
        open_mask = ~assessment_attempts["status"].fillna("").astype(str).str.lower().isin(
            completed_statuses
        )
        open_attempts = assessment_attempts[open_mask].groupby("user_id").size()
    else:
        last_assessment = pd.Series(dtype="datetime64[ns, UTC]")
        resume_sum = pd.Series(dtype="float64")
        open_attempts = pd.Series(dtype="int64")

    base["Interacciones 14d"] = base["user_id"].map(count14).fillna(0).astype(int)
    base["Interacciones previas 14d"] = (
        base["user_id"].map(count_prev14).fillna(0).astype(int)
    )
    base["Prácticas 30d"] = (
        base["user_id"].map(practice_count30).fillna(0).astype(int)
    )
    base["Precisión 30d (%)"] = base["user_id"].map(practice_accuracy30)
    base["Reanudaciones"] = base["user_id"].map(resume_sum).fillna(0).astype(int)
    base["Intentos abiertos"] = base["user_id"].map(open_attempts).fillna(0).astype(int)

    base["last_interaction"] = base["user_id"].map(last_interaction)
    base["last_practice"] = base["user_id"].map(last_practice)
    base["last_assessment"] = base["user_id"].map(last_assessment)

    base["Última actividad"] = pd.concat(
        [
            base["last_login_dt"],
            base["last_interaction"],
            base["last_practice"],
            base["last_assessment"],
        ],
        axis=1,
    ).max(axis=1)

    base["Días sin actividad"] = (
        (now_utc - base["Última actividad"]).dt.total_seconds() / 86400
    )
    base["Días sin actividad"] = (
        base["Días sin actividad"].fillna(999).clip(lower=0).round(1)
    )

    base["Momentum"] = (
        (base["Interacciones 14d"] - base["Interacciones previas 14d"])
        / (base["Interacciones previas 14d"] + 1)
    )

    def _academic_risk(row):
        score = 0.0
        attempts = float(row["Prácticas 30d"])
        accuracy = row["Precisión 30d (%)"]
        days = float(row["Días sin actividad"])
        interactions14 = float(row["Interacciones 14d"])
        open_count = float(row["Intentos abiertos"])

        if attempts >= 5 and pd.notna(accuracy):
            score += min(48.0, max(0.0, (60.0 - float(accuracy)) * 1.2))
        elif attempts < 3:
            score += 8.0

        if days >= 21:
            score += 28.0
        elif days >= 14:
            score += 22.0
        elif days >= 7:
            score += 12.0
        elif days >= 3:
            score += 5.0

        if interactions14 == 0:
            score += 18.0
        elif interactions14 <= 2:
            score += 10.0

        if open_count > 0:
            score += min(12.0, open_count * 6.0)

        return min(100.0, round(score, 1))

    def _disconnect_risk(row):
        score = 0.0
        days = float(row["Días sin actividad"])
        interactions14 = float(row["Interacciones 14d"])
        momentum = float(row["Momentum"])

        if days >= 21:
            score += 60.0
        elif days >= 14:
            score += 48.0
        elif days >= 7:
            score += 30.0
        elif days >= 3:
            score += 15.0

        if interactions14 == 0:
            score += 25.0
        elif interactions14 <= 2:
            score += 15.0

        if momentum <= -0.50:
            score += 15.0

        return min(100.0, round(score, 1))

    base["Riesgo académico"] = base.apply(_academic_risk, axis=1)
    base["Riesgo desconexión"] = base.apply(_disconnect_risk, axis=1)
    base["Alerta académica"] = base["Riesgo académico"].map(_science_risk_band)
    base["Alerta desconexión"] = base["Riesgo desconexión"].map(_science_risk_band)
    base["Acción sugerida"] = base.apply(_science_recommendation, axis=1)

    high_academic = int((base["Riesgo académico"] >= 60).sum())
    high_disconnect = int((base["Riesgo desconexión"] >= 60).sum())

    m1, m2, m3 = st.columns(3)
    m1.metric("Estudiantes activos 14d", f"{len(active_ids)}/{len(selected_ids)}")
    m2.metric(
        "Interacciones 14d",
        interactions_14,
        delta=momentum_delta,
        help="Variación frente a los 14 días anteriores.",
    )
    m3.metric(
        "Precisión práctica 30d",
        "Sin datos" if pd.isna(overall_accuracy) else f"{overall_accuracy:.1f}%",
    )

    m4, m5, m6 = st.columns(3)
    m4.metric("Alerta académica alta", high_academic)
    m5.metric("Riesgo desconexión alto", high_disconnect)
    m6.metric(
        "Cobertura GPS 30d",
        f"{gps_coverage:.1f}%",
        help=(
            "Solo cobertura agregada. La ubicación exacta no entra en el puntaje "
            "individual de riesgo."
        ),
    )

    st.markdown("### 🔬 Fricción de aprendizaje por tema")

    interactions30 = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_30)
    ].copy()

    if not interactions30.empty:
        interactions30["Tema"] = (
            interactions30["topic"]
            .fillna("Sin tema")
            .astype(str)
            .str.strip()
            .replace("", "Sin tema")
        )
        topic_i = (
            interactions30.groupby("Tema")
            .agg(
                **{
                    "Interacciones 30d": ("user_id", "size"),
                    "Estudiantes activos": ("user_id", "nunique"),
                }
            )
            .reset_index()
        )
    else:
        topic_i = pd.DataFrame(
            columns=["Tema", "Interacciones 30d", "Estudiantes activos"]
        )

    if not practice30.empty:
        practice30 = practice30.copy()
        practice30["Tema"] = (
            practice30["topic"]
            .fillna("Sin tema")
            .astype(str)
            .str.strip()
            .replace("", "Sin tema")
        )
        topic_p = (
            practice30.groupby("Tema")
            .agg(
                **{
                    "Prácticas 30d": ("correct_num", "size"),
                    "Precisión (%)": ("correct_num", "mean"),
                }
            )
            .reset_index()
        )
        topic_p["Precisión (%)"] = topic_p["Precisión (%)"] * 100
    else:
        topic_p = pd.DataFrame(
            columns=["Tema", "Prácticas 30d", "Precisión (%)"]
        )

    if not adaptive.empty:
        adaptive = adaptive.copy()
        adaptive["Tema"] = (
            adaptive["topic"]
            .fillna("Sin tema")
            .astype(str)
            .str.strip()
            .replace("", "Sin tema")
        )
        adaptive["response_time_seconds"] = pd.to_numeric(
            adaptive["response_time_seconds"], errors="coerce"
        )
        adaptive["attempts"] = pd.to_numeric(
            adaptive["attempts"], errors="coerce"
        )
        topic_a = (
            adaptive.groupby("Tema")
            .agg(
                **{
                    "Tiempo respuesta (s)": ("response_time_seconds", "mean"),
                    "Reintentos promedio": ("attempts", "mean"),
                }
            )
            .reset_index()
        )
    else:
        topic_a = pd.DataFrame(
            columns=["Tema", "Tiempo respuesta (s)", "Reintentos promedio"]
        )

    topic = topic_i.merge(topic_p, on="Tema", how="outer").merge(
        topic_a,
        on="Tema",
        how="outer",
    )

    if topic.empty:
        st.info("Todavía no hay suficiente información temática.")
    else:
        accuracy_gap = (
            100 - pd.to_numeric(topic["Precisión (%)"], errors="coerce")
            .fillna(50)
            .clip(lower=0, upper=100)
        )
        latency = pd.to_numeric(
            topic["Tiempo respuesta (s)"], errors="coerce"
        )
        retry = pd.to_numeric(
            topic["Reintentos promedio"], errors="coerce"
        )
        latency_rank = latency.fillna(latency.median()).rank(pct=True) * 100
        retry_rank = retry.fillna(retry.median()).rank(pct=True) * 100

        topic["Índice fricción"] = (
            0.60 * accuracy_gap
            + 0.25 * latency_rank.fillna(0)
            + 0.15 * retry_rank.fillna(0)
        ).round(1)

        topic = topic.sort_values(
            ["Índice fricción", "Interacciones 30d"],
            ascending=[False, False],
        )

        st.caption(
            "Índice de fricción = baja precisión + mayor tiempo de respuesta + "
            "reintentos. Se usa para priorizar apoyo didáctico."
        )
        st.dataframe(
            topic.head(20),
            use_container_width=True,
            hide_index=True,
        )

        chart = topic.head(10).set_index("Tema")[["Índice fricción"]]
        if not chart.empty:
            st.bar_chart(chart)

    st.markdown("### 📈 Evolución de KPIs · últimas 8 semanas")

    interaction_window = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_56)
    ].copy()
    practice_window = practice[
        practice["created_dt"].notna()
        & (practice["created_dt"] >= cut_56)
    ].copy()

    c1, c2 = st.columns(2)

    with c1:
        st.caption("Interacciones semanales")
        if interaction_window.empty:
            st.info("Sin datos de interacción.")
        else:
            interaction_window["Semana"] = (
                interaction_window["created_dt"]
                .dt.tz_convert(None)
                .dt.to_period("W")
                .astype(str)
            )
            weekly_i = (
                interaction_window.groupby("Semana")
                .size()
                .rename("Interacciones")
                .to_frame()
            )
            st.line_chart(weekly_i)

    with c2:
        st.caption("Precisión semanal de práctica")
        if practice_window.empty:
            st.info("Sin datos de precisión.")
        else:
            practice_window["Semana"] = (
                practice_window["created_dt"]
                .dt.tz_convert(None)
                .dt.to_period("W")
                .astype(str)
            )
            weekly_p = (
                practice_window.groupby("Semana")["correct_num"]
                .mean()
                .mul(100)
                .rename("Precisión (%)")
                .to_frame()
            )
            st.line_chart(weekly_p)

    st.markdown("### 🚦 Matriz de acompañamiento")

    alerts = base[
        [
            "Estudiante",
            "username",
            "Días sin actividad",
            "Interacciones 14d",
            "Prácticas 30d",
            "Precisión 30d (%)",
            "Reanudaciones",
            "Intentos abiertos",
            "Riesgo académico",
            "Riesgo desconexión",
            "Alerta académica",
            "Alerta desconexión",
            "Acción sugerida",
        ]
    ].copy()

    alerts["Precisión 30d (%)"] = pd.to_numeric(
        alerts["Precisión 30d (%)"],
        errors="coerce",
    ).round(1)

    alerts = alerts.sort_values(
        ["Riesgo académico", "Riesgo desconexión", "Días sin actividad"],
        ascending=[False, False, False],
    )

    st.dataframe(
        alerts.head(30),
        use_container_width=True,
        hide_index=True,
    )

    with st.expander("Metodología y límites de las alertas"):
        st.markdown(
            """
            **Riesgo académico:** combina desempeño reciente, práctica, actividad
            e intentos pendientes.

            **Riesgo de desconexión:** combina recencia, volumen de interacción
            y pérdida de momentum.

            **Ubicación:** se usa únicamente como indicador agregado de cobertura.
            La distancia o ubicación exacta del estudiante no se utiliza para
            clasificar su riesgo individual.

            **Uso:** estas señales priorizan acompañamiento; no deben emplearse
            como única base para decisiones académicas.
            """
        )



# BUNSEKI_R8_14_TEACHER_ASSIGNMENT_ADMIN_V1
def _teacher_assignment_admin_write(statements):
    """Execute a small admin-approved transaction without exposing credentials."""
    dsn = (
        globals().get("DATABASE_URL")
        or os.getenv("DATABASE_URL")
        or os.getenv("BUNSEKI_TEST_DATABASE_URL")
        or ""
    )
    dsn = str(dsn or "").strip()
    if not dsn:
        raise RuntimeError("DATABASE_URL no configurada.")

    import psycopg2

    conn = psycopg2.connect(dsn)
    try:
        conn.autocommit = False
        with conn.cursor() as cur:
            for statement, params in statements:
                cur.execute(statement, params)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _teacher_assignment_catalog():
    courses = pd.DataFrame(
        fetchall(
            """
            SELECT
                c.id,
                c.code,
                c.name,
                c.status,
                c.academic_period_id,
                s.name AS subject_name
            FROM courses c
            LEFT JOIN subjects s ON s.id=c.subject_id
            ORDER BY COALESCE(s.name,''), COALESCE(c.name,''), c.id
            """
        )
    )

    parallels = pd.DataFrame(
        fetchall(
            """
            SELECT
                p.id,
                p.course_id,
                p.code,
                p.name,
                p.active,
                c.code AS course_code,
                c.name AS course_name,
                s.name AS subject_name
            FROM parallels p
            JOIN courses c ON c.id=p.course_id
            LEFT JOIN subjects s ON s.id=c.subject_id
            ORDER BY COALESCE(s.name,''), COALESCE(c.name,''), COALESCE(p.name,''), p.id
            """
        )
    )

    return courses, parallels


def _teacher_assignment_rows(teacher_id):
    course_rows = pd.DataFrame(
        fetchall(
            """
            SELECT
                tc.course_id,
                tc.role,
                c.code,
                c.name,
                s.name AS subject_name
            FROM teacher_courses tc
            JOIN courses c ON c.id=tc.course_id
            LEFT JOIN subjects s ON s.id=c.subject_id
            WHERE tc.teacher_id=%s
            ORDER BY COALESCE(s.name,''), COALESCE(c.name,''), c.id
            """,
            (teacher_id,),
        )
    )

    parallel_rows = pd.DataFrame(
        fetchall(
            """
            SELECT
                tp.parallel_id,
                p.course_id,
                p.code,
                p.name,
                c.code AS course_code,
                c.name AS course_name,
                s.name AS subject_name
            FROM teacher_parallels tp
            JOIN parallels p ON p.id=tp.parallel_id
            JOIN courses c ON c.id=p.course_id
            LEFT JOIN subjects s ON s.id=c.subject_id
            WHERE tp.teacher_id=%s
            ORDER BY COALESCE(s.name,''), COALESCE(c.name,''), COALESCE(p.name,''), p.id
            """,
            (teacher_id,),
        )
    )

    return course_rows, parallel_rows


def _teacher_assignment_students(teacher_id):
    return pd.DataFrame(
        fetchall(
            """
            SELECT DISTINCT
                u.id AS user_id,
                u.username,
                COALESCE(
                    NULLIF(TRIM(CONCAT(COALESCE(pr.first_names,''),' ',COALESCE(pr.last_names,''))), ''),
                    u.username
                ) AS student_name,
                c.code AS course_code,
                c.name AS course_name,
                p.code AS parallel_code,
                p.name AS parallel_name,
                e.status AS enrollment_status
            FROM teachers t
            JOIN teacher_courses tc
              ON tc.teacher_id=t.id
            JOIN teacher_parallels tp
              ON tp.teacher_id=t.id
            JOIN enrollments e
              ON e.course_id=tc.course_id
             AND e.parallel_id=tp.parallel_id
            JOIN users u
              ON u.id=e.student_user_id
            LEFT JOIN profiles pr
              ON pr.user_id=u.id
            JOIN courses c
              ON c.id=e.course_id
            JOIN parallels p
              ON p.id=e.parallel_id
             AND p.course_id=e.course_id
            WHERE t.id=%s
            ORDER BY student_name, course_name, parallel_name
            """,
            (teacher_id,),
        )
    )


def render_admin_teacher_assignment_manager(admin_user):
    role = str((admin_user or {}).get("role") or "").strip().lower()
    if role != "admin":
        st.error("Solo un administrador puede gestionar asignaciones docentes.")
        return

    st.markdown("### 👨‍🏫 Gestión docente y asignaciones")
    st.caption(
        "Administra la relación Docente → Materia/Curso → Paralelo. "
        "El dashboard docente y sus indicadores usan estas asignaciones "
        "como fuente de verdad y mantienen acceso deny-by-default."
    )

    teacher_accounts = pd.DataFrame(
        fetchall(
            """
            SELECT
                u.id AS user_id,
                u.username,
                u.active,
                u.role,
                t.id AS teacher_id,
                t.status AS teacher_status
            FROM users u
            LEFT JOIN teachers t
              ON t.user_id=u.id
            WHERE LOWER(COALESCE(u.role,'')) IN ('teacher','docente')
            ORDER BY u.username
            """
        )
    )

    if teacher_accounts.empty:
        st.warning(
            "No existen cuentas con rol teacher/docente. "
            "Crea o habilita primero la cuenta de usuario docente y vuelve a esta sección."
        )
        return

    account_labels = {}
    for _, row in teacher_accounts.iterrows():
        uid = int(row["user_id"])
        status = "registrado" if pd.notna(row.get("teacher_id")) else "sin estructura docente"
        account_labels[uid] = f"{row['username']} · {status}"

    selected_user_id = st.selectbox(
        "Cuenta docente",
        list(account_labels.keys()),
        format_func=lambda value: account_labels[value],
        key="admin_teacher_assignment_user",
    )

    selected_row = teacher_accounts[
        teacher_accounts["user_id"].astype(int) == int(selected_user_id)
    ].iloc[0]

    teacher_id = (
        int(selected_row["teacher_id"])
        if pd.notna(selected_row.get("teacher_id"))
        else None
    )

    if not bool(selected_row.get("active")):
        st.warning("La cuenta seleccionada está inactiva.")

    if teacher_id is None:
        st.info(
            "La cuenta tiene rol docente, pero aún no está registrada en la tabla teachers."
        )
        confirm_register = st.checkbox(
            "Confirmo el alta estructural de este usuario como docente.",
            key=f"confirm_teacher_structure_{selected_user_id}",
        )
        if st.button(
            "Registrar estructura docente",
            disabled=not confirm_register,
            use_container_width=True,
            key=f"register_teacher_structure_{selected_user_id}",
        ):
            _teacher_assignment_admin_write(
                [
                    (
                        """
                        INSERT INTO teachers(user_id,status,created_at,updated_at)
                        VALUES (%s,'active',NOW(),NOW())
                        ON CONFLICT (user_id)
                        DO UPDATE SET status='active', updated_at=NOW()
                        """,
                        (int(selected_user_id),),
                    )
                ]
            )
            st.success("Docente registrado correctamente.")
            st.rerun()
        return

    courses, parallels = _teacher_assignment_catalog()
    assigned_courses, assigned_parallels = _teacher_assignment_rows(teacher_id)

    if courses.empty:
        st.warning("No existen cursos en el catálogo académico.")
        return

    current_course_ids = (
        assigned_courses["course_id"].dropna().astype(int).tolist()
        if not assigned_courses.empty
        else []
    )
    current_parallel_ids = (
        assigned_parallels["parallel_id"].dropna().astype(int).tolist()
        if not assigned_parallels.empty
        else []
    )

    course_labels = {}
    for _, row in courses.iterrows():
        cid = int(row["id"])
        subject = str(row.get("subject_name") or "").strip()
        code = str(row.get("code") or "").strip()
        name = str(row.get("name") or "").strip()
        pieces = [value for value in [subject, code, name] if value]
        course_labels[cid] = " · ".join(pieces) or f"Curso {cid}"

    selected_course_ids = st.multiselect(
        "Materias / cursos asignados",
        options=list(course_labels.keys()),
        default=[
            cid for cid in current_course_ids
            if cid in course_labels
        ],
        format_func=lambda value: course_labels[value],
        key=f"teacher_courses_{teacher_id}",
        help=(
            "Selecciona únicamente los cursos que el docente debe visualizar. "
            "Los indicadores no incluirán cursos no asignados."
        ),
    )

    eligible_parallels = parallels[
        parallels["course_id"].astype(int).isin(
            [int(value) for value in selected_course_ids]
        )
    ].copy()

    parallel_labels = {}
    for _, row in eligible_parallels.iterrows():
        pid = int(row["id"])
        subject = str(row.get("subject_name") or "").strip()
        course_name = str(row.get("course_name") or "").strip()
        pcode = str(row.get("code") or "").strip()
        pname = str(row.get("name") or "").strip()
        course_text = " · ".join(
            value for value in [subject, course_name] if value
        )
        parallel_text = " / ".join(
            value for value in [pcode, pname] if value
        )
        parallel_labels[pid] = (
            f"{course_text} → {parallel_text}"
            if course_text
            else parallel_text or f"Paralelo {pid}"
        )

    selected_parallel_ids = st.multiselect(
        "Paralelos asignados",
        options=list(parallel_labels.keys()),
        default=[
            pid for pid in current_parallel_ids
            if pid in parallel_labels
        ],
        format_func=lambda value: parallel_labels[value],
        key=f"teacher_parallels_{teacher_id}",
        help=(
            "El docente verá estudiantes e indicadores únicamente de estos paralelos "
            "dentro de los cursos seleccionados."
        ),
    )

    c1, c2, c3 = st.columns(3)
    c1.metric("Cursos actuales", len(current_course_ids))
    c2.metric("Paralelos actuales", len(current_parallel_ids))
    current_students = _teacher_assignment_students(teacher_id)
    c3.metric(
        "Estudiantes visibles",
        0 if current_students.empty else current_students["user_id"].nunique(),
    )

    with st.expander("Vista previa del alcance actual", expanded=False):
        if current_students.empty:
            st.info("No hay estudiantes matriculados dentro del alcance actual.")
        else:
            st.dataframe(
                current_students,
                use_container_width=True,
                hide_index=True,
            )

    changes_exist = (
        set(map(int, selected_course_ids)) != set(map(int, current_course_ids))
        or set(map(int, selected_parallel_ids)) != set(map(int, current_parallel_ids))
    )

    st.markdown("#### Guardar alcance docente")
    st.caption(
        "La operación reemplaza solamente las asignaciones del docente seleccionado. "
        "No elimina cursos, paralelos, estudiantes, evaluaciones ni registros históricos."
    )

    confirmation = st.checkbox(
        "Confirmo que revisé cursos y paralelos antes de guardar.",
        key=f"confirm_teacher_assignments_{teacher_id}",
    )

    if st.button(
        "Guardar asignaciones docente",
        disabled=(not confirmation or not changes_exist),
        use_container_width=True,
        key=f"save_teacher_assignments_{teacher_id}",
    ):
        selected_course_ids = [int(value) for value in selected_course_ids]
        selected_parallel_ids = [int(value) for value in selected_parallel_ids]

        if selected_parallel_ids:
            validation = pd.DataFrame(
                fetchall(
                    """
                    SELECT id, course_id
                    FROM parallels
                    WHERE id = ANY(%s)
                    """,
                    (selected_parallel_ids,),
                )
            )
            if len(validation) != len(set(selected_parallel_ids)):
                raise ValueError("Uno o más paralelos seleccionados ya no existen.")

            invalid_course_links = validation[
                ~validation["course_id"].astype(int).isin(selected_course_ids)
            ]
            if not invalid_course_links.empty:
                raise ValueError(
                    "Todos los paralelos deben pertenecer a un curso seleccionado."
                )

        statements = [
            (
                "DELETE FROM teacher_parallels WHERE teacher_id=%s",
                (teacher_id,),
            ),
            (
                "DELETE FROM teacher_courses WHERE teacher_id=%s",
                (teacher_id,),
            ),
        ]

        for course_id in selected_course_ids:
            statements.append(
                (
                    """
                    INSERT INTO teacher_courses(teacher_id,course_id,role,created_at)
                    VALUES (%s,%s,'teacher',NOW())
                    ON CONFLICT DO NOTHING
                    """,
                    (teacher_id, course_id),
                )
            )

        for parallel_id in selected_parallel_ids:
            statements.append(
                (
                    """
                    INSERT INTO teacher_parallels(teacher_id,parallel_id,created_at)
                    VALUES (%s,%s,NOW())
                    ON CONFLICT DO NOTHING
                    """,
                    (teacher_id, parallel_id),
                )
            )

        statements.append(
            (
                """
                UPDATE teachers
                SET status='active', updated_at=NOW()
                WHERE id=%s
                """,
                (teacher_id,),
            )
        )

        _teacher_assignment_admin_write(statements)
        st.success(
            "Asignaciones actualizadas. El próximo acceso del docente "
            "usará automáticamente este nuevo alcance."
        )
        st.rerun()


