# BUNSEKI-018A.5B.1C

# Teacher scoped dashboard / deny-by-default

# ============================================================



def _teacher_record_for_user(user_id):

    """Devuelve el docente asociado al usuario autenticado."""

    if not user_id:

        return None



    return fetchone(

        """

        SELECT id, user_id

        FROM teachers

        WHERE user_id=%s

        """,

        (user_id,),

    )





def _teacher_scope_summary(user_id):

    """

    Resumen restringido exclusivamente a las asignaciones

    del docente autenticado.

    """

    teacher = _teacher_record_for_user(user_id)



    if not teacher:

        return None



    teacher_id = teacher["id"]



    courses = fetchone(

        """

        SELECT COUNT(*) AS total

        FROM teacher_courses

        WHERE teacher_id=%s

        """,

        (teacher_id,),

    ) or {}



    parallels = fetchone(

        """

        SELECT COUNT(*) AS total

        FROM teacher_parallels

        WHERE teacher_id=%s

        """,

        (teacher_id,),

    ) or {}



    enrollments = fetchone(

        """

        SELECT COUNT(*) AS total

        FROM enrollments e

        WHERE EXISTS (

            SELECT 1

            FROM teacher_parallels tp

            WHERE tp.teacher_id=%s

              AND tp.parallel_id=e.parallel_id

        )

        """,

        (teacher_id,),

    ) or {}



    return {

        "teacher_id": teacher_id,

        "courses": int(courses.get("total") or 0),

        "parallels": int(parallels.get("total") or 0),

        "enrollments": int(enrollments.get("total") or 0),

    }





def teacher_can_access_course(user_id, course_id):

    """Deny-by-default para recursos asociados a un curso."""

    if not user_id or not course_id:

        return False



    row = fetchone(

        """

        SELECT EXISTS (

            SELECT 1

            FROM teachers t

            JOIN teacher_courses tc

              ON tc.teacher_id=t.id

            WHERE t.user_id=%s

              AND tc.course_id=%s

        ) AS allowed

        """,

        (user_id, course_id),

    ) or {}



    return bool(row.get("allowed"))





def teacher_can_access_parallel(user_id, parallel_id):

    """Deny-by-default para recursos asociados a un paralelo."""

    if not user_id or not parallel_id:

        return False



    row = fetchone(

        """

        SELECT EXISTS (

            SELECT 1

            FROM teachers t

            JOIN teacher_parallels tp

              ON tp.teacher_id=t.id

            WHERE t.user_id=%s

              AND tp.parallel_id=%s

        ) AS allowed

        """,

        (user_id, parallel_id),

    ) or {}



    return bool(row.get("allowed"))





# BUNSEKI_R8_11_TEACHER_INTERVENTION_V1
def _teacher_intervention_row_allowed(user, row):
    """Deny-by-default reuse of the existing teacher scope guards."""
    course_candidates = [
        row.get("course"),
        row.get("course_level"),
        row.get("subject"),
    ]
    course_candidates = [
        value for value in course_candidates
        if value is not None and str(value).strip()
    ]

    course_ok = False
    for candidate in course_candidates:
        try:
            if teacher_can_access_course(user, candidate):
                course_ok = True
                break
        except Exception:
            continue

    parallel_value = row.get("parallel")
    parallel_ok = False

    parallel_calls = []
    if parallel_value is not None and str(parallel_value).strip():
        parallel_calls.append((user, parallel_value))
        for course_candidate in course_candidates:
            parallel_calls.append(
                (user, course_candidate, parallel_value)
            )

    for args in parallel_calls:
        try:
            if teacher_can_access_parallel(*args):
                parallel_ok = True
                break
        except Exception:
            continue

    return bool(course_ok and parallel_ok)


def _teacher_intervention_dt(series):
    return pd.to_datetime(series, errors="coerce", utc=True)


def _teacher_intervention_band(value):
    score = float(value or 0)
    if score >= 60:
        return "Alta"
    if score >= 35:
        return "Media"
    return "Baja"


def _teacher_intervention_action(row):
    days = float(row.get("Días sin actividad") or 0)
    interactions = float(row.get("Interacciones 14d") or 0)
    attempts = float(row.get("Prácticas 30d") or 0)
    accuracy = row.get("Precisión 30d (%)")

    if days >= 14:
        return "Contacto de reenganche y plan breve de retorno"
    if pd.notna(accuracy) and attempts >= 5 and float(accuracy) < 60:
        return "Refuerzo focalizado en temas de menor precisión"
    if interactions <= 2:
        return "Actividad guiada corta y seguimiento en 7 días"
    return "Seguimiento ordinario"


def render_teacher_intervention_dashboard(user):
    # BUNSEKI_R8_18_VISIBLE_MATRIX_RECORDS_V1
    # BUNSEKI_R8_19_MATRIX_READABILITY_POLISH_V1
    st.markdown("## 🧠 Intervención académica")
    st.caption(
        "Panel gráfico para priorizar acompañamiento dentro de tus cursos y "
        "paralelos asignados. Las alertas son heurísticas de apoyo docente."
    )

    students = pd.DataFrame(
        fetchall(
            """
            SELECT DISTINCT
                u.id AS user_id,
                u.username,
                u.last_login,
                u.active,
                p.first_names,
                p.last_names,
                p.subject,
                COALESCE(c.name, p.course) AS course,
                p.course_level,
                COALESCE(pr.name, p.parallel) AS parallel,
                p.shift,
                p.level,
                e.course_id,
                e.parallel_id,
                c.code AS assigned_course_code,
                c.name AS assigned_course_name,
                pr.code AS assigned_parallel_code,
                pr.name AS assigned_parallel_name
            FROM teachers t
            JOIN teacher_courses tc
              ON tc.teacher_id=t.id
            JOIN teacher_parallels tp
              ON tp.teacher_id=t.id
            JOIN enrollments e
              ON e.course_id=tc.course_id
             AND e.parallel_id=tp.parallel_id
            JOIN users u
              ON u.id=e.student_user_id
            LEFT JOIN profiles p
              ON p.user_id=u.id
            JOIN courses c
              ON c.id=e.course_id
            JOIN parallels pr
              ON pr.id=e.parallel_id
             AND pr.course_id=e.course_id
            WHERE t.user_id=%s
              AND COALESCE(u.active,TRUE)=TRUE
            ORDER BY u.username
            """,
            (int(user["id"]),),
        )
    )

    if students.empty:
        st.info(
            "No hay estudiantes matriculados dentro de tus cursos y paralelos asignados."
        )
        return

    allowed_ids = set(
        students["user_id"].dropna().astype(int).tolist()
    )

    interactions = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, topic, subtopic, level, latency_ms, created_at
            FROM interactions
            """
        )
    )
    practice = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, topic, subtopic, difficulty_level,
                   is_correct, created_at
            FROM research_exercise_attempts
            """
        )
    )
    assessment_attempts = pd.DataFrame(
        fetchall(
            """
            SELECT user_id, teacher_assessment_id, status, resume_count,
                   created_at, updated_at
            FROM assessment_attempts
            WHERE teacher_assessment_id IS NOT NULL
            """
        )
    )

    now_utc = pd.Timestamp.now(tz="UTC")
    cut_14 = now_utc - pd.Timedelta(days=14)
    cut_28 = now_utc - pd.Timedelta(days=28)
    cut_30 = now_utc - pd.Timedelta(days=30)

    if interactions.empty:
        interactions = pd.DataFrame(
            columns=[
                "user_id", "topic", "subtopic",
                "created_at", "created_dt"
            ]
        )
    else:
        interactions = interactions[
            interactions["user_id"].isin(allowed_ids)
        ].copy()
        interactions["created_dt"] = _teacher_intervention_dt(
            interactions["created_at"]
        )

    if practice.empty:
        practice = pd.DataFrame(
            columns=[
                "user_id", "topic", "subtopic", "is_correct",
                "created_at", "created_dt", "correct_num"
            ]
        )
    else:
        practice = practice[
            practice["user_id"].isin(allowed_ids)
        ].copy()
        practice["created_dt"] = _teacher_intervention_dt(
            practice["created_at"]
        )
        practice["correct_num"] = (
            practice["is_correct"].fillna(False).astype(int)
        )

    if assessment_attempts.empty:
        assessment_attempts = pd.DataFrame(
            columns=[
                "user_id", "status", "resume_count",
                "created_at", "updated_at",
                "created_dt", "updated_dt"
            ]
        )
    else:
        assessment_attempts = assessment_attempts[
            assessment_attempts["user_id"].isin(allowed_ids)
        ].copy()
        assessment_attempts["created_dt"] = _teacher_intervention_dt(
            assessment_attempts["created_at"]
        )
        assessment_attempts["updated_dt"] = _teacher_intervention_dt(
            assessment_attempts["updated_at"]
        )

    students["last_login_dt"] = _teacher_intervention_dt(
        students["last_login"]
    )

    recent14 = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_14)
    ]
    previous14 = interactions[
        interactions["created_dt"].notna()
        & (interactions["created_dt"] >= cut_28)
        & (interactions["created_dt"] < cut_14)
    ]
    practice30 = practice[
        practice["created_dt"].notna()
        & (practice["created_dt"] >= cut_30)
    ]

    base = students[
        [
            "user_id",
            "username",
            "first_names",
            "last_names",
            "last_login_dt",
            "subject",
            "course",
            "course_level",
            "parallel",
        ]
    ].copy()

    base["Estudiante"] = (
        base["first_names"].fillna("").astype(str).str.strip()
        + " "
        + base["last_names"].fillna("").astype(str).str.strip()
    ).str.strip()
    base["Estudiante"] = base.apply(
        lambda row: (
            row["Estudiante"]
            if row["Estudiante"]
            else str(row["username"])
        ),
        axis=1,
    )

    last_interaction = (
        interactions.groupby("user_id")["created_dt"].max()
        if not interactions.empty
        else pd.Series(dtype="datetime64[ns, UTC]")
    )
    last_practice = (
        practice.groupby("user_id")["created_dt"].max()
        if not practice.empty
        else pd.Series(dtype="datetime64[ns, UTC]")
    )

    count14 = (
        recent14.groupby("user_id").size()
        if not recent14.empty
        else pd.Series(dtype="int64")
    )
    count_prev14 = (
        previous14.groupby("user_id").size()
        if not previous14.empty
        else pd.Series(dtype="int64")
    )

    practice_count30 = (
        practice30.groupby("user_id").size()
        if not practice30.empty
        else pd.Series(dtype="int64")
    )
    practice_accuracy30 = (
        practice30.groupby("user_id")["correct_num"].mean() * 100
        if not practice30.empty
        else pd.Series(dtype="float64")
    )

    completed_statuses = {
        "completed",
        "submitted",
        "graded",
        "finished",
        "complete",
    }

    if not assessment_attempts.empty:
        last_assessment = (
            assessment_attempts.groupby("user_id")["updated_dt"].max()
        )
        resume_sum = (
            assessment_attempts.groupby("user_id")["resume_count"]
            .sum(min_count=1)
            .fillna(0)
        )
        open_mask = ~assessment_attempts[
            "status"
        ].fillna("").astype(str).str.lower().isin(
            completed_statuses
        )
        open_attempts = (
            assessment_attempts[open_mask]
            .groupby("user_id")
            .size()
        )
    else:
        last_assessment = pd.Series(
            dtype="datetime64[ns, UTC]"
        )
        resume_sum = pd.Series(dtype="float64")
        open_attempts = pd.Series(dtype="int64")

    base["Interacciones 14d"] = (
        base["user_id"].map(count14).fillna(0).astype(int)
    )
    base["Interacciones previas 14d"] = (
        base["user_id"].map(count_prev14).fillna(0).astype(int)
    )
    base["Prácticas 30d"] = (
        base["user_id"].map(practice_count30).fillna(0).astype(int)
    )
    base["Precisión 30d (%)"] = (
        base["user_id"].map(practice_accuracy30)
    )
    base["Reanudaciones"] = (
        base["user_id"].map(resume_sum).fillna(0).astype(int)
    )
    base["Intentos abiertos"] = (
        base["user_id"].map(open_attempts).fillna(0).astype(int)
    )

    # BUNSEKI_R8_15_V3_TEACHER_DATETIME_MAP_HOTFIX
    # Avoid pandas Series.map(Series[datetime64, tz]) casting edge cases.
    # Normalize user ids and map through plain Python dictionaries instead.
    _last_interaction_map = {
        int(key): value
        for key, value in last_interaction.items()
        if pd.notna(key)
    }
    _last_practice_map = {
        int(key): value
        for key, value in last_practice.items()
        if pd.notna(key)
    }
    _last_assessment_map = {
        int(key): value
        for key, value in last_assessment.items()
        if pd.notna(key)
    }

    _base_user_ids = pd.to_numeric(
        base["user_id"],
        errors="coerce",
    )

    base["last_interaction"] = pd.to_datetime(
        _base_user_ids.apply(
            lambda value: (
                _last_interaction_map.get(int(value), pd.NaT)
                if pd.notna(value)
                else pd.NaT
            )
        ),
        errors="coerce",
        utc=True,
    )

    base["last_practice"] = pd.to_datetime(
        _base_user_ids.apply(
            lambda value: (
                _last_practice_map.get(int(value), pd.NaT)
                if pd.notna(value)
                else pd.NaT
            )
        ),
        errors="coerce",
        utc=True,
    )

    base["last_assessment"] = pd.to_datetime(
        _base_user_ids.apply(
            lambda value: (
                _last_assessment_map.get(int(value), pd.NaT)
                if pd.notna(value)
                else pd.NaT
            )
        ),
        errors="coerce",
        utc=True,
    )

    base["Última actividad"] = pd.concat(
        [
            base["last_login_dt"],
            base["last_interaction"],
            base["last_practice"],
            base["last_assessment"],
        ],
        axis=1,
    ).max(axis=1)

    base["Días sin actividad"] = (
        (now_utc - base["Última actividad"])
        .dt.total_seconds()
        / 86400
    )
    base["Días sin actividad"] = (
        base["Días sin actividad"]
        .fillna(999)
        .clip(lower=0)
        .round(1)
    )

    base["Momentum"] = (
        (
            base["Interacciones 14d"]
            - base["Interacciones previas 14d"]
        )
        / (base["Interacciones previas 14d"] + 1)
    )

    def academic_risk(row):
        score = 0.0
        attempts = float(row["Prácticas 30d"])
        accuracy = row["Precisión 30d (%)"]
        days = float(row["Días sin actividad"])
        interactions14 = float(row["Interacciones 14d"])
        open_count = float(row["Intentos abiertos"])

        if attempts >= 5 and pd.notna(accuracy):
            score += min(
                48.0,
                max(
                    0.0,
                    (60.0 - float(accuracy)) * 1.2,
                ),
            )
        elif attempts < 3:
            score += 8.0

        if days >= 21:
            score += 28.0
        elif days >= 14:
            score += 22.0
        elif days >= 7:
            score += 12.0
        elif days >= 3:
            score += 5.0

        if interactions14 == 0:
            score += 18.0
        elif interactions14 <= 2:
            score += 10.0

        if open_count > 0:
            score += min(
                12.0,
                open_count * 6.0,
            )

        return min(
            100.0,
            round(score, 1),
        )

    def disconnect_risk(row):
        score = 0.0
        days = float(row["Días sin actividad"])
        interactions14 = float(row["Interacciones 14d"])
        momentum = float(row["Momentum"])

        if days >= 21:
            score += 60.0
        elif days >= 14:
            score += 48.0
        elif days >= 7:
            score += 30.0
        elif days >= 3:
            score += 15.0

        if interactions14 == 0:
            score += 25.0
        elif interactions14 <= 2:
            score += 15.0

        if momentum <= -0.50:
            score += 15.0

        return min(
            100.0,
            round(score, 1),
        )

    base["Riesgo académico"] = base.apply(
        academic_risk,
        axis=1,
    )
    base["Riesgo desconexión"] = base.apply(
        disconnect_risk,
        axis=1,
    )
    base["Alerta académica"] = base[
        "Riesgo académico"
    ].map(_teacher_intervention_band)
    base["Alerta desconexión"] = base[
        "Riesgo desconexión"
    ].map(_teacher_intervention_band)
    base["Acción sugerida"] = base.apply(
        _teacher_intervention_action,
        axis=1,
    )

    high_academic = int(
        (base["Riesgo académico"] >= 60).sum()
    )
    medium_academic = int(
        (
            (base["Riesgo académico"] >= 35)
            & (base["Riesgo académico"] < 60)
        ).sum()
    )
    high_disconnect = int(
        (base["Riesgo desconexión"] >= 60).sum()
    )
    inactive_7 = int(
        (base["Días sin actividad"] >= 7).sum()
    )
    avg_accuracy = pd.to_numeric(
        base["Precisión 30d (%)"],
        errors="coerce",
    ).mean()

    k1, k2, k3 = st.columns(3)
    k1.metric("Estudiantes acompañados", len(base))
    k2.metric("Riesgo académico alto", high_academic)
    k3.metric("Riesgo académico medio", medium_academic)

    k4, k5, k6 = st.columns(3)
    k4.metric("Riesgo desconexión alto", high_disconnect)
    k5.metric("Sin actividad ≥ 7 días", inactive_7)
    k6.metric(
        "Precisión media 30d",
        "Sin datos" if pd.isna(avg_accuracy) else f"{avg_accuracy:.1f}%",
    )

    # BUNSEKI_R8_17_TEACHER_INTERVENTION_VIEW_SWITCH_V1
    # Explicit view selector avoids tab-panel CSS collisions elsewhere in the app.
    intervention_view = st.radio(
        "Vista de intervención",
        [
            "📊 Panorama de intervención",
            "🚦 Matriz de acompañamiento",
            "📋 Registros",
        ],
        horizontal=True,
        key=f"teacher_intervention_view_{user['id']}",
        label_visibility="collapsed",
    )

    if intervention_view == "📊 Panorama de intervención":
        st.markdown("### Mapa 2×2 · interacción vs precisión")
        st.caption(
            "Distingue baja participación de dificultad conceptual. "
            "La línea horizontal usa 60% de precisión y la vertical "
            "5 interacciones en 14 días como referencias operativas."
        )

        scatter = base[
            [
                "Estudiante",
                "Interacciones 14d",
                "Precisión 30d (%)",
                "Riesgo académico",
                "Riesgo desconexión",
            ]
        ].copy()

        scatter["Precisión 30d (%)"] = pd.to_numeric(
            scatter["Precisión 30d (%)"],
            errors="coerce",
        ).fillna(0)

        if "px" in globals():
            fig = px.scatter(
                scatter,
                x="Interacciones 14d",
                y="Precisión 30d (%)",
                hover_name="Estudiante",
                size="Riesgo académico",
                color="Riesgo desconexión",
                size_max=32,
                title="Mapa de intervención: actividad × desempeño",
            )
            fig.add_hline(
                y=60,
                line_dash="dash",
                annotation_text="Precisión 60%",
            )
            fig.add_vline(
                x=5,
                line_dash="dash",
                annotation_text="5 interacciones / 14d",
            )
            fig.update_yaxes(range=[0, 100])
            st.plotly_chart(
                fig,
                use_container_width=True,
            )
        else:
            st.scatter_chart(
                scatter.set_index("Estudiante")[
                    [
                        "Interacciones 14d",
                        "Precisión 30d (%)",
                    ]
                ]
            )

        st.markdown("### Distribución de alertas")
        risk_counts = (
            base["Alerta académica"]
            .value_counts()
            .reindex(
                ["Alta", "Media", "Baja"],
                fill_value=0,
            )
            .rename("Estudiantes")
            .to_frame()
        )
        st.bar_chart(risk_counts)

        st.markdown("### Fricción temática del grupo")

        if practice30.empty:
            st.info(
                "Todavía no hay práctica reciente "
                "para calcular fricción por tema."
            )
        else:
            topic_friction = (
                practice30.assign(
                    Tema=(
                        practice30["subtopic"]
                        .fillna(practice30["topic"])
                        .fillna("Sin tema")
                        .astype(str)
                        .str.strip()
                        .replace("", "Sin tema")
                    )
                )
                .groupby("Tema")
                .agg(
                    **{
                        "Prácticas": ("correct_num", "size"),
                        "Precisión (%)": ("correct_num", "mean"),
                        "Estudiantes": ("user_id", "nunique"),
                    }
                )
                .reset_index()
            )
            topic_friction["Precisión (%)"] = (
                topic_friction["Precisión (%)"] * 100
            )
            topic_friction["Índice fricción"] = (
                100 - topic_friction["Precisión (%)"]
            ).round(1)
            topic_friction = topic_friction.sort_values(
                ["Índice fricción", "Prácticas"],
                ascending=[False, False],
            )
            st.dataframe(
                topic_friction.head(15),
                use_container_width=True,
                hide_index=True,
            )

    elif intervention_view == "🚦 Matriz de acompañamiento":
        st.markdown("### Matriz de acompañamiento")
        st.caption(
            "La matriz complementa los registros: prioriza quién necesita "
            "acompañamiento, por qué y qué acción realizar."
        )

        matrix = base[
            [
                "Estudiante",
                "username",
                "course",
                "parallel",
                "Última actividad",
                "Días sin actividad",
                "Interacciones 14d",
                "Prácticas 30d",
                "Precisión 30d (%)",
                "Reanudaciones",
                "Intentos abiertos",
                "Riesgo académico",
                "Riesgo desconexión",
                "Alerta académica",
                "Alerta desconexión",
                "Acción sugerida",
            ]
        ].copy()

        matrix["Precisión 30d (%)"] = pd.to_numeric(
            matrix["Precisión 30d (%)"],
            errors="coerce",
        ).round(1)

        matrix = matrix.sort_values(
            [
                "Riesgo académico",
                "Riesgo desconexión",
                "Días sin actividad",
            ],
            ascending=[False, False, False],
        )

        st.success(
            f"Estudiantes en la matriz: {len(matrix)}"
        )

        matrix_display = matrix[
            [
                "Estudiante",
                "course",
                "parallel",
                "Última actividad",
                "Días sin actividad",
                "Interacciones 14d",
                "Prácticas 30d",
                "Precisión 30d (%)",
                "Riesgo académico",
                "Riesgo desconexión",
                "Acción sugerida",
            ]
        ].copy()

        matrix_display["Última actividad"] = pd.to_datetime(
            matrix_display["Última actividad"],
            errors="coerce",
            utc=True,
        ).dt.strftime("%Y-%m-%d %H:%M").fillna("Sin actividad registrada")

        matrix_display["Días sin actividad"] = matrix_display[
            "Días sin actividad"
        ].apply(
            lambda value: (
                "Sin actividad registrada"
                if pd.isna(value) or float(value) >= 900
                else (
                    "< 1 día"
                    if float(value) < 1
                    else f"{float(value):.0f} días"
                )
            )
        )

        matrix_display["Precisión 30d (%)"] = pd.to_numeric(
            matrix_display["Precisión 30d (%)"],
            errors="coerce",
        ).apply(
            lambda value: (
                "Sin datos"
                if pd.isna(value)
                else f"{float(value):.1f}%"
            )
        )

        matrix_display["Riesgo académico"] = pd.to_numeric(
            matrix_display["Riesgo académico"],
            errors="coerce",
        ).apply(
            lambda value: (
                "Sin datos"
                if pd.isna(value)
                else f"{float(value):.0f}/100"
            )
        )

        matrix_display["Riesgo desconexión"] = pd.to_numeric(
            matrix_display["Riesgo desconexión"],
            errors="coerce",
        ).apply(
            lambda value: (
                "Sin datos"
                if pd.isna(value)
                else f"{float(value):.0f}/100"
            )
        )

        matrix_display = matrix_display.rename(
            columns={
                "course": "Curso",
                "parallel": "Paralelo",
                "Interacciones 14d": "Interacciones",
                "Prácticas 30d": "Prácticas",
                "Precisión 30d (%)": "Precisión",
            }
        )

        st.table(matrix_display)

        st.caption(
            "Referencia operativa: riesgo bajo 0–34, medio 35–59 y alto 60–100. "
            "Las alertas orientan acompañamiento docente y no sustituyen el juicio académico."
        )

        csv_bytes = matrix.to_csv(index=False).encode("utf-8-sig")
        st.download_button(
            "⬇️ Descargar matriz de acompañamiento",
            data=csv_bytes,
            file_name="bunseki_matriz_acompanamiento_docente.csv",
            mime="text/csv",
            use_container_width=True,
        )

        selected_student = st.selectbox(
            "Detalle de estudiante",
            matrix["Estudiante"].tolist(),
            key=f"teacher_intervention_student_{user['id']}",
        )

        selected = matrix[
            matrix["Estudiante"] == selected_student
        ].iloc[0]

        d1, d2, d3 = st.columns(3)
        d1.metric(
            "Riesgo académico",
            f"{selected['Riesgo académico']:.0f}/100",
        )
        d2.metric(
            "Riesgo desconexión",
            f"{selected['Riesgo desconexión']:.0f}/100",
        )
        _selected_days = selected["Días sin actividad"]
        d3.metric(
            "Días sin actividad",
            (
                "Sin registro"
                if pd.isna(_selected_days) or float(_selected_days) >= 900
                else (
                    "< 1 día"
                    if float(_selected_days) < 1
                    else f"{float(_selected_days):.0f}"
                )
            ),
        )

        d4, d5, d6 = st.columns(3)
        d4.metric(
            "Interacciones 14d",
            int(selected["Interacciones 14d"]),
        )
        d5.metric(
            "Prácticas 30d",
            int(selected["Prácticas 30d"]),
        )
        _selected_accuracy = selected["Precisión 30d (%)"]
        d6.metric(
            "Precisión 30d",
            (
                "Sin datos"
                if pd.isna(_selected_accuracy)
                else f"{float(_selected_accuracy):.1f}%"
            ),
        )

        _selected_last_activity = pd.to_datetime(
            selected["Última actividad"],
            errors="coerce",
            utc=True,
        )
        st.caption(
            "Última actividad: "
            + (
                "Sin actividad registrada"
                if pd.isna(_selected_last_activity)
                else _selected_last_activity.strftime("%Y-%m-%d %H:%M UTC")
            )
        )

        st.info(
            "Acción sugerida: "
            + str(selected["Acción sugerida"])
        )

    elif intervention_view == "📋 Registros":
        st.markdown("### 📋 Registros de actividad")
        st.caption(
            "Evidencia histórica de actividad dentro del alcance actual del docente. "
            "Estos registros complementan la Matriz de acompañamiento."
        )

        _student_name_map = {
            int(row["user_id"]): str(row["Estudiante"])
            for _, row in base[["user_id", "Estudiante"]].iterrows()
            if pd.notna(row["user_id"])
        }

        _record_frames = []

        if not interactions.empty:
            _ri = interactions[
                ["user_id", "created_dt", "topic", "subtopic", "latency_ms"]
            ].copy()
            _ri["Tipo"] = "Interacción"
            _ri["Detalle"] = _ri.apply(
                lambda row: (
                    f"{str(row.get('topic') or 'Sin tema')} · "
                    f"{str(row.get('subtopic') or 'Sin subtema')}"
                    + (
                        f" · {int(row['latency_ms'])} ms"
                        if pd.notna(row.get("latency_ms"))
                        else ""
                    )
                ),
                axis=1,
            )
            _ri = _ri.rename(columns={"created_dt": "Fecha"})
            _record_frames.append(
                _ri[["user_id", "Fecha", "Tipo", "Detalle"]]
            )

        if not practice.empty:
            _rp = practice[
                [
                    "user_id",
                    "created_dt",
                    "topic",
                    "subtopic",
                    "difficulty_level",
                    "is_correct",
                ]
            ].copy()
            _rp["Tipo"] = "Práctica"
            _rp["Detalle"] = _rp.apply(
                lambda row: (
                    f"{str(row.get('topic') or 'Sin tema')} · "
                    f"{str(row.get('subtopic') or 'Sin subtema')} · "
                    f"{str(row.get('difficulty_level') or 'Sin nivel')} · "
                    + (
                        "Correcta"
                        if bool(row.get("is_correct"))
                        else "Incorrecta"
                    )
                ),
                axis=1,
            )
            _rp = _rp.rename(columns={"created_dt": "Fecha"})
            _record_frames.append(
                _rp[["user_id", "Fecha", "Tipo", "Detalle"]]
            )

        if not assessment_attempts.empty:
            _ra = assessment_attempts[
                [
                    "user_id",
                    "updated_dt",
                    "teacher_assessment_id",
                    "status",
                    "resume_count",
                ]
            ].copy()
            _ra["Tipo"] = "Evaluación"
            _ra["Detalle"] = _ra.apply(
                lambda row: (
                    f"Evaluación {row.get('teacher_assessment_id')} · "
                    f"Estado: {str(row.get('status') or 'Sin estado')} · "
                    f"Reanudaciones: {int(row.get('resume_count') or 0)}"
                ),
                axis=1,
            )
            _ra = _ra.rename(columns={"updated_dt": "Fecha"})
            _record_frames.append(
                _ra[["user_id", "Fecha", "Tipo", "Detalle"]]
            )

        if not _record_frames:
            st.info(
                "Todavía no existen registros de interacción, práctica o evaluación "
                "para los estudiantes de este alcance."
            )
        else:
            _records = pd.concat(
                _record_frames,
                ignore_index=True,
            )
            _records["Estudiante"] = _records["user_id"].map(
                _student_name_map
            ).fillna("Estudiante")
            _records["Fecha"] = pd.to_datetime(
                _records["Fecha"],
                errors="coerce",
                utc=True,
            )
            _records = _records.sort_values(
                "Fecha",
                ascending=False,
                na_position="last",
            )

            _records_view = _records[
                [
                    "Fecha",
                    "Estudiante",
                    "Tipo",
                    "Detalle",
                ]
            ].copy()

            st.success(
                f"Registros encontrados: {len(_records_view)}"
            )

            _records_display = _records_view.copy()
            _records_display["Fecha"] = pd.to_datetime(
                _records_display["Fecha"],
                errors="coerce",
                utc=True,
            ).dt.strftime("%Y-%m-%d %H:%M").fillna("Sin fecha")

            st.table(
                _records_display.head(100)
            )

            if len(_records_display) > 100:
                st.caption(
                    "Se muestran los 100 registros más recientes. "
                    "La descarga CSV contiene el conjunto completo."
                )

            st.download_button(
                "⬇️ Descargar registros CSV",
                data=_records_view.to_csv(index=False).encode("utf-8-sig"),
                file_name="bunseki_registros_docente.csv",
                mime="text/csv",
                use_container_width=True,
            )

    with st.expander("Metodología y uso responsable"):
        st.markdown(
            """
            **Riesgo académico:** usa precisión, práctica,
            inactividad, interacciones e intentos pendientes.

            **Riesgo de desconexión:** usa recencia,
            volumen de interacción y caída de momentum.

            **No se utiliza ubicación o distancia para puntuar
            el riesgo individual.**

            Estas señales sirven para priorizar acompañamiento;
            no sustituyen la revisión docente ni constituyen
            una decisión académica automática.
            """
        )

def teacher_scoped_page(user):

    """

    Dashboard exclusivo para docentes.

    Nunca llama admin_page() y nunca usa métricas globales.

    """

    # BUNSEKI-TEACHER-SCOPED-NAV-V1

    role = str(user.get("role", "")).lower() if user else ""



    if role not in {"teacher", "docente"}:

        st.error("Acceso docente no autorizado.")

        st.stop()



    scope = _teacher_scope_summary(user.get("id"))



    if not scope:

        st.error(

            "El usuario docente no posee una asignación "

            "académica válida."

        )

        st.stop()



    teacher_pages = (

        "📊 Dashboard docente",

        "📚 Planes analíticos",

    )

    nav_key = "teacher_scoped_nav_page"

    fallback_key = "teacher_scoped_nav_fallback"



    if st.session_state.get(nav_key) not in teacher_pages:

        st.session_state[nav_key] = teacher_pages[0]

    if st.session_state.get(fallback_key) not in teacher_pages:

        st.session_state[fallback_key] = st.session_state[nav_key]



    with st.sidebar:

        st.markdown("## BunsekiChat")

        st.caption("Panel docente")

        st.success("🔒 Acceso limitado a tus asignaciones")



        st.markdown("---")



        for page in teacher_pages:

            if st.button(

                page,

                key=f"teacher_scoped_button_{page}",

                use_container_width=True,

            ):

                st.session_state[nav_key] = page

                st.session_state[fallback_key] = page

                st.rerun()



        st.markdown("---")

        st.write(f"**Usuario:** {user.get('username', 'Docente')}")

        st.write(f"**Cursos asignados:** {scope['courses']}")

        st.write(f"**Paralelos asignados:** {scope['parallels']}")



    def _sync_teacher_scoped_fallback():

        selected = st.session_state.get(fallback_key)

        if selected in teacher_pages:

            st.session_state[nav_key] = selected



    st.markdown("#### 🧭 Navegación docente")

    st.selectbox(

        "Menú docente alternativo",

        teacher_pages,

        key=fallback_key,

        on_change=_sync_teacher_scoped_fallback,

    )

    st.caption(

        "Este selector permanece disponible aunque el panel lateral "

        "esté oculto."

    )



    teacher_page = st.session_state.get(nav_key, teacher_pages[0])



    if teacher_page == "📚 Planes analíticos":

        render_teacher_plan_manager(user)

        return



    st.title("📊 Dashboard docente")

    st.caption(

        "Vista limitada exclusivamente a tus cursos "

        "y paralelos asignados."

    )



    c1, c2, c3 = st.columns(3)



    with c1:

        st.metric("Cursos asignados", scope["courses"])



    with c2:

        st.metric("Paralelos asignados", scope["parallels"])



    with c3:

        st.metric(

            "Estudiantes matriculados",

            scope["enrollments"],

        )



    st.markdown("---")



    if scope["enrollments"] == 0:

        st.info(

            "Actualmente no existen estudiantes matriculados "

            "en tus paralelos."

        )



    st.markdown("---")
    render_teacher_intervention_dashboard(user)
    st.markdown("---")

    st.subheader("🔐 Alcance de seguridad")



    st.success(

        "Tu sesión está restringida a las asignaciones "

        "registradas para este docente."

    )



    st.caption(

        "Las métricas globales y los estudiantes de otros "

        "docentes no están disponibles en esta vista."

    )



if __name__ == "__main__":

    setup_database_once(DATABASE_SCHEMA_VERSION)

    session_guard()

    if 'user' not in st.session_state:

        if st.session_state.get("landing_entered", False):
            login_page()
        else:
            landing_page()

    else:

        u = st.session_state.user

        capture_global_gps = True

        if u.get('role') not in ['admin', 'teacher', 'docente']:

            current_profile = get_profile(u['id'])

            capture_global_gps = not is_official_profile(current_profile) or official_profile_ready(u, current_profile)

        if capture_global_gps:

            capture_browser_gps(uid=u['id'], page='global', event_type='app_open', show_status=False)

        role = str(u.get("role", "")).lower()

        if role == "admin": admin_page(u)

        elif role in {"teacher", "docente"}: teacher_scoped_page(u)

        else: student_page(u)
